/****** Object:  StoredProcedure [dbo].[App_LoginAttemptCheck]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_LoginAttemptCheck]
    @UsernameKey NVARCHAR(256),
    @MaxAttempts INT = 5,
    @LockoutMinutes INT = 15
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FailedCount INT = 0;
    DECLARE @LockedUntil DATETIME2(7) = NULL;
    DECLARE @Now DATETIME2(7) = SYSUTCDATETIME();

    SELECT
        @FailedCount = FailedCount,
        @LockedUntil = LockedUntil
    FROM dbo.App_LoginAttempts
    WHERE UsernameKey = @UsernameKey;

    -- قفل هنوز معتبر است.
    IF @LockedUntil IS NOT NULL AND @LockedUntil > @Now
    BEGIN
        SELECT
            CAST(0 AS BIT) AS CanAttempt,
            @FailedCount AS FailedCount,
            @LockedUntil AS LockedUntil;
        RETURN;
    END;

    -- قفل قبلی منقضی شده؛ شمارنده از نو شروع شود.
    IF @LockedUntil IS NOT NULL AND @LockedUntil <= @Now
    BEGIN
        UPDATE dbo.App_LoginAttempts
        SET
            FailedCount = 0,
            LockedUntil = NULL,
            LastAttemptAt = @Now
        WHERE UsernameKey = @UsernameKey;

        SET @FailedCount = 0;
        SET @LockedUntil = NULL;
    END;

    IF @FailedCount >= @MaxAttempts
    BEGIN
        SET @LockedUntil = DATEADD(MINUTE, @LockoutMinutes, @Now);

        UPDATE dbo.App_LoginAttempts
        SET LockedUntil = @LockedUntil
        WHERE UsernameKey = @UsernameKey;

        SELECT
            CAST(0 AS BIT) AS CanAttempt,
            @FailedCount AS FailedCount,
            @LockedUntil AS LockedUntil;
        RETURN;
    END;

    SELECT
        CAST(1 AS BIT) AS CanAttempt,
        @FailedCount AS FailedCount,
        @LockedUntil AS LockedUntil;
END;
GO
/****** Object:  StoredProcedure [dbo].[App_LoginAttemptFail]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[App_LoginAttemptFail]
    @UsernameKey NVARCHAR(256),
    @MaxAttempts INT = 5,
    @LockoutMinutes INT = 15
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @NewCount INT;
    DECLARE @CurrentLock DATETIME2(7);

    BEGIN TRY
        BEGIN TRANSACTION;

        -- قفل رکورد موجود برای جلوگیری از به‌روزرسانی هم‌زمان
        SELECT
            @NewCount = FailedCount,
            @CurrentLock = LockedUntil
        FROM dbo.App_LoginAttempts WITH (UPDLOCK, HOLDLOCK)
        WHERE UsernameKey = @UsernameKey;

        IF @NewCount IS NULL
        BEGIN
            INSERT INTO dbo.App_LoginAttempts
            (
                UsernameKey,
                FailedCount,
                LockedUntil,
                LastAttemptAt
            )
            VALUES
            (
                @UsernameKey,
                1,
                CASE WHEN @MaxAttempts <= 1
                     THEN DATEADD(MINUTE, @LockoutMinutes, @Now)
                     ELSE NULL
                END,
                @Now
            );

            SET @NewCount = 1;
        END
        ELSE
        BEGIN
            -- اگر قفل قبلی تمام شده، تلاش جدید از شمارنده صفر شروع شود.
            IF @CurrentLock IS NOT NULL AND @CurrentLock <= @Now
                SET @NewCount = 0;

            SET @NewCount = @NewCount + 1;

            UPDATE dbo.App_LoginAttempts
            SET
                FailedCount = @NewCount,
                LockedUntil =
                    CASE
                        WHEN @NewCount >= @MaxAttempts
                        THEN DATEADD(MINUTE, @LockoutMinutes, @Now)
                        ELSE NULL
                    END,
                LastAttemptAt = @Now
            WHERE UsernameKey = @UsernameKey;
        END;

        COMMIT TRANSACTION;

        SELECT
            @NewCount AS FailedCount,
            CASE
                WHEN @NewCount >= @MaxAttempts
                THEN DATEADD(MINUTE, @LockoutMinutes, @Now)
                ELSE NULL
            END AS LockedUntil;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
