/* =========================================================
   CLEANUP
   ========================================================= */

CREATE PROCEDURE [dbo].[App_RefreshTokenCleanupExpired]
AS
BEGIN

    SET NOCOUNT ON;

    DELETE FROM dbo.App_RefreshTokens
    WHERE ExpiresAt < DATEADD(DAY, -7, GETUTCDATE())
       OR RevokedAt < DATEADD(DAY, -30, GETUTCDATE());

END
GO
/****** Object:  StoredProcedure [dbo].[App_RefreshTokenGetActive]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   GET ACTIVE
   ========================================================= */

CREATE PROCEDURE [dbo].[App_RefreshTokenGetActive]
(
    @TokenHash CHAR(64)
)
AS
BEGIN

    SET NOCOUNT ON;

    SELECT TOP (1)

        rt.Id,
        rt.UserId,
        rt.TokenHash,
        rt.ExpiresAt,
        rt.CreatedAt,
        rt.RevokedAt,
        rt.ReplacedByTokenHash,
        rt.SessionId,
        rt.DeviceName,
        rt.UserAgent,
        rt.CreatedIp,

        s.ActiveRoleId,
        s.RevokedAt AS SessionRevokedAt

    FROM dbo.App_RefreshTokens rt

    INNER JOIN dbo.App_UserSessions s
        ON s.SessionId = rt.SessionId

    WHERE rt.TokenHash = @TokenHash

      AND rt.RevokedAt IS NULL

      AND rt.ExpiresAt > GETUTCDATE()

      AND s.RevokedAt IS NULL;

END
GO
/****** Object:  StoredProcedure [dbo].[App_RefreshTokenGetActiveSessions]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[App_RefreshTokenGetActiveSessions]
    @UserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH LatestSessionTokens AS
    (
        SELECT
            Id,
            UserId,
            SessionId,
            TokenHash,
            ExpiresAt,
            CreatedAt,
            RevokedAt,
            ReplacedByTokenHash,
            DeviceName,
            UserAgent,
            CreatedIp,
            ROW_NUMBER() OVER
            (
                PARTITION BY SessionId
                ORDER BY CreatedAt DESC, Id DESC
            ) AS RowNumber
        FROM dbo.App_RefreshTokens
        WHERE UserId = @UserId
    )
    SELECT
        Id,
        UserId,
        SessionId,
        TokenHash,
        ExpiresAt,
        CreatedAt,
        RevokedAt,
        ReplacedByTokenHash,
        DeviceName,
        UserAgent,
        CreatedIp
    FROM LatestSessionTokens
    WHERE RowNumber = 1
      AND RevokedAt IS NULL
      AND ExpiresAt > SYSUTCDATETIME()
    ORDER BY CreatedAt DESC;
END;
GO
