/****** Object:  StoredProcedure [dbo].[App_SuperAdminRegister]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[App_SuperAdminRegister]
    @OrgName       NVARCHAR(200),
    @OrgType       INT,
    @GeoId         NVARCHAR(10),
    @Mobile        NVARCHAR(30) = NULL,
    @Username      NVARCHAR(100) = NULL,
    @PasswordHash  NVARCHAR(500),
    @FirstName     NVARCHAR(100) = NULL,
    @LastName      NVARCHAR(100) = NULL,
    @Email         NVARCHAR(150) = NULL,

    @UserId        BIGINT OUTPUT,
    @OrgId         BIGINT OUTPUT,
    @ResultCode    INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @UserId = NULL;
    SET @OrgId = NULL;
    SET @ResultCode = 500;
    SET @ResultMessage = N'ثبت‌نام انجام نشد.';

    /* اعتبارسنجی اولیه */
    SET @OrgName = NULLIF(LTRIM(RTRIM(@OrgName)), N'');
    SET @GeoId = NULLIF(LTRIM(RTRIM(@GeoId)), N'');
    SET @Mobile = NULLIF(LTRIM(RTRIM(@Mobile)), N'');
    SET @Username = NULLIF(LTRIM(RTRIM(@Username)), N'');
    SET @Email = NULLIF(LTRIM(RTRIM(@Email)), N'');

    IF @OrgName IS NULL
       OR @GeoId IS NULL
       OR NULLIF(LTRIM(RTRIM(@PasswordHash)), N'') IS NULL
       OR (@Mobile IS NULL AND @Username IS NULL)
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage =
            N'نام سازمان، موقعیت جغرافیایی، رمز عبور و موبایل یا نام کاربری الزامی است.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_Geo
        WHERE GeoId = @GeoId
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'موقعیت جغرافیایی انتخاب‌شده معتبر نیست.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_LookupValues
        WHERE LookupValueId = @OrgType
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نوع سازمان معتبر نیست.';
        RETURN;
    END;

    DECLARE @SuperAdminRoleId BIGINT;

    SELECT @SuperAdminRoleId = RoleId
    FROM dbo.App_Roles
    WHERE RoleCode = N'SUPER_ADMIN';

    IF @SuperAdminRoleId IS NULL
    BEGIN
        SET @ResultCode = 500;
        SET @ResultMessage = N'نقش سوپر ادمین در سیستم تعریف نشده است.';
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        /*
          فقط زمانی اجازه ثبت‌نام اولیه بده که هنوز هیچ
          کاربر فعال و حذف‌نشده‌ای با نقش SUPER_ADMIN وجود ندارد.
          قفل‌ها برای جلوگیری از ثبت‌نام هم‌زمان اولیه هستند.
        */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_UserRoles ur WITH (UPDLOCK, HOLDLOCK)
            INNER JOIN dbo.App_Roles r
                ON r.RoleId = ur.RoleId
            INNER JOIN dbo.App_Users u
                ON u.UserId = ur.UserId
            WHERE r.RoleCode = N'SUPER_ADMIN'
              AND ur.IsActive = 1
              AND ISNULL(ur.IsDeleted, 0) = 0
              AND (ur.ExpiresAt IS NULL OR ur.ExpiresAt > GETDATE())
              AND u.IsActive = 1
              AND ISNULL(u.IsDeleted, 0) = 0
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 403;
            SET @ResultMessage =
                N'ثبت‌نام اولیه غیرفعال است؛ سوپر ادمین از قبل وجود دارد.';
            RETURN;
        END;

        /* بررسی یکتایی اطلاعات ورود */
        IF @Username IS NOT NULL
           AND EXISTS
           (
               SELECT 1 FROM dbo.App_Users
               WHERE Username = @Username
           )
        BEGIN
            THROW 51001, 'Username already exists.', 1;
        END;

        IF @Email IS NOT NULL
           AND EXISTS
           (
               SELECT 1 FROM dbo.App_Users
               WHERE Email = @Email
           )
        BEGIN
            THROW 51002, 'Email already exists.', 1;
        END;

        IF @Mobile IS NOT NULL
           AND EXISTS
           (
               SELECT 1 FROM dbo.App_Users
               WHERE Mobile = @Mobile
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            THROW 51003, 'Mobile already exists.', 1;
        END;

        /* ایجاد کاربر */
        INSERT INTO dbo.App_Users
        (
            Username,
            PasswordHash,
            Email,
            Mobile,
            FirstName,
            LastName,
            Gender,
            PhoneVerified,
            IsActive,
            IsDeleted,
            CreatedAt
        )
        VALUES
        (
            @Username,
            @PasswordHash,
            @Email,
            COALESCE(@Mobile, @Username),
            COALESCE(NULLIF(LTRIM(RTRIM(@FirstName)), N''), @Username, @Mobile, N'Admin'),
            COALESCE(NULLIF(LTRIM(RTRIM(@LastName)), N''), N''),
            0,
            0,
            1,
            0,
            GETDATE()
        );

        SET @UserId = CONVERT(BIGINT, SCOPE_IDENTITY());

        /* اختصاص نقش سوپر ادمین */
        INSERT INTO dbo.App_UserRoles
        (
            UserId,
            RoleId,
            AssignedAt,
            IsActive,
            IsDeleted,
            CreatedAt
        )
        VALUES
        (
            @UserId,
            @SuperAdminRoleId,
            GETDATE(),
            1,
            0,
            GETDATE()
        );

        /* ایجاد سازمان */
        INSERT INTO dbo.Organizations
        (
            OrgName,
            OrgType,
            GeoId,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater
        )
        VALUES
        (
            @OrgName,
            @OrgType,
            @GeoId,
            1,
            0,
            GETDATE(),
            TRY_CONVERT(INT, @UserId)
        );

        SET @OrgId = CONVERT(BIGINT, SCOPE_IDENTITY());

        /* اتصال سازمان به همان سوپر ادمین */
        UPDATE dbo.App_Users
        SET OrgId = @OrgId,
            UpdatedAt = GETDATE(),
            UserUpdater = TRY_CONVERT(INT, @UserId)
        WHERE UserId = @UserId;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'کاربر سوپر ادمین و سازمان با موفقیت ایجاد شدند.';

        SELECT
            @UserId AS UserId,
            @OrgId AS OrgId,
            @ResultCode AS ResultCode,
            @ResultMessage AS ResultMessage;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @UserId = NULL;
        SET @OrgId = NULL;

        IF ERROR_NUMBER() BETWEEN 51001 AND 51003
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'نام کاربری، موبایل یا ایمیل قبلاً ثبت شده است.';
        END
        ELSE
        BEGIN
            SET @ResultCode = 500;
            SET @ResultMessage = N'خطا در ایجاد کاربر و سازمان.';
        END;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UserGetForRefresh]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[App_UserGetForRefresh]
    @UserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    -- Result Set 1: User
    SELECT
        u.UserId,
        u.Username,
        u.FirstName,
        u.LastName,
        CONCAT(u.FirstName, N' ', u.LastName) AS FullName,
        u.Email,
        u.Mobile,
        u.NationalId,
        u.Gender,
        u.BirthDate,
        u.PhoneVerified,
        u.LastLoginAt,
        u.CreatedAt,
        u.AvatarUrl AS Avatar
    FROM dbo.App_Users AS u
    WHERE u.UserId = @UserId
      AND u.IsActive = 1
      AND ISNULL(u.IsDeleted, 0) = 0;

    -- Result Set 2: Roles + Menus
    ;WITH MenuHierarchy AS
    (
        SELECT
            m.MenuId,
            m.ParentId,
            m.TitleFa,
            m.TitleEn,
            m.MenuUrl,
            m.Icon,
            m.SortOrder,
            m.MenuDescriptionFa,
            m.MenuDescriptionEn,
            0 AS MenuLevel,
            CAST(
                RIGHT('0000000000' + CAST(m.SortOrder AS VARCHAR(10)), 10)
                + '.'
                + RIGHT('0000000000' + CAST(m.MenuId AS VARCHAR(10)), 10)
                AS VARCHAR(MAX)
            ) AS HierarchyPath
        FROM dbo.App_Menus AS m
        WHERE m.ParentId IS NULL
          AND m.IsActive = 1
          AND ISNULL(m.IsDeleted, 0) = 0
          AND m.IsVisible = 1

        UNION ALL

        SELECT
            child.MenuId,
            child.ParentId,
            child.TitleFa,
            child.TitleEn,
            child.MenuUrl,
            child.Icon,
            child.SortOrder,
            child.MenuDescriptionFa,
            child.MenuDescriptionEn,
            parent.MenuLevel + 1,
            CAST(
                parent.HierarchyPath
                + '.'
                + RIGHT('0000000000' + CAST(child.SortOrder AS VARCHAR(10)), 10)
                + '.'
                + RIGHT('0000000000' + CAST(child.MenuId AS VARCHAR(10)), 10)
                AS VARCHAR(MAX)
            )
        FROM dbo.App_Menus AS child
        INNER JOIN MenuHierarchy AS parent
            ON child.ParentId = parent.MenuId
        WHERE child.IsActive = 1
          AND ISNULL(child.IsDeleted, 0) = 0
          AND child.IsVisible = 1
    )
    SELECT
        r.RoleId,
        r.RoleCode,
        r.RoleNameFa,
        r.RoleNameEn,
        r.RoleDescriptionFa,
        r.RoleDescriptionEn,
        mh.MenuId,
        mh.ParentId,
        mh.TitleFa,
        mh.TitleEn,
        mh.MenuUrl,
        mh.Icon,
        mh.SortOrder,
        mh.MenuDescriptionFa,
        mh.MenuDescriptionEn,
        mh.MenuLevel,
        CASE
            WHEN rm.RoleMenuId IS NULL THEN CAST(1 AS TINYINT)
            ELSE rm.PermissionLevel
        END AS PermissionLevel,
        mh.HierarchyPath
    FROM dbo.App_UserRoles AS ur
    INNER JOIN dbo.App_Roles AS r
        ON r.RoleId = ur.RoleId
    CROSS JOIN MenuHierarchy AS mh
    LEFT JOIN dbo.App_RoleMenus AS rm
        ON rm.RoleId = r.RoleId
       AND rm.MenuId = mh.MenuId
       AND rm.IsActive = 1
       AND ISNULL(rm.IsDeleted, 0) = 0
    WHERE ur.UserId = @UserId
      AND ur.IsActive = 1
      AND ISNULL(ur.IsDeleted, 0) = 0
      AND (ur.ExpiresAt IS NULL OR ur.ExpiresAt > GETDATE())
    ORDER BY r.RoleId, mh.HierarchyPath
    OPTION (MAXRECURSION 100);
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UserGetForSession]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_UserGetForSession]
(
    @UserId BIGINT
)
AS
BEGIN

    SET NOCOUNT ON;


    /* =====================================================
       USER
       ===================================================== */

    SELECT
        u.UserId,
        u.Username,
        u.Email,
        u.Mobile,
        u.FirstName,
        u.LastName,
        CONCAT(
            u.FirstName,
            N' ',
            u.LastName
        ) AS FullName,
        u.NationalId,
        u.Gender,
        u.BirthDate,
        u.AvatarUrl,
        u.PhoneVerified,
        u.LastLoginAt,
        u.IsActive,
        u.IsDeleted,
        u.CreatedAt,
        u.UpdatedAt,
		u.OrgId
    FROM dbo.App_Users u

    WHERE u.UserId = @UserId

      AND u.IsActive = 1

      AND ISNULL(u.IsDeleted, 0) = 0;


    /* =====================================================
       MENU HIERARCHY
       ===================================================== */

    ;WITH MenuHierarchy AS
    (
        SELECT

            m.MenuId,
            m.ParentId,
            m.TitleFa,
            m.TitleEn,
            m.MenuUrl,
            m.Icon,
            m.SortOrder,
            m.MenuDescriptionFa,
            m.MenuDescriptionEn,

            0 AS MenuLevel,

            CAST(
                RIGHT(
                    '0000000000'
                    + CAST(m.MenuId AS VARCHAR(10)),
                    10
                )
                AS VARCHAR(MAX)
            ) AS HierarchyPath

        FROM dbo.App_Menus m

        WHERE m.ParentId IS NULL

          AND m.IsActive = 1

          AND ISNULL(m.IsDeleted, 0) = 0

          AND m.IsVisible = 1


        UNION ALL


        SELECT

            child.MenuId,
            child.ParentId,
            child.TitleFa,
            child.TitleEn,
            child.MenuUrl,
            child.Icon,
            child.SortOrder,
            child.MenuDescriptionFa,
            child.MenuDescriptionEn,

            parent.MenuLevel + 1,

            CAST(
                parent.HierarchyPath
                + '/'
                + RIGHT(
                    '0000000000'
                    + CAST(child.MenuId AS VARCHAR(10)),
                    10
                )
                AS VARCHAR(MAX)
            )

        FROM dbo.App_Menus child

        INNER JOIN MenuHierarchy parent
            ON child.ParentId =
               parent.MenuId

        WHERE child.IsActive = 1

          AND ISNULL(child.IsDeleted, 0) = 0

          AND child.IsVisible = 1
    )


    /* =====================================================
       ROLES + MENUS
       ===================================================== */

    SELECT

        r.RoleId,
        r.RoleCode,
        r.RoleNameFa,
        r.RoleNameEn,
        r.RoleDescriptionFa,
        r.RoleDescriptionEn,

        mh.MenuId,
        mh.ParentId,

        mh.TitleFa,
        mh.TitleEn,

        mh.MenuUrl,
        mh.Icon,
        mh.SortOrder,

        mh.MenuDescriptionFa,
        mh.MenuDescriptionEn,

        mh.MenuLevel,

        CASE

            WHEN rm.RoleMenuId IS NULL
                THEN CAST(1 AS TINYINT)

            ELSE rm.PermissionLevel

        END AS PermissionLevel,

        mh.HierarchyPath

    FROM dbo.App_UserRoles ur

    INNER JOIN dbo.App_Roles r
        ON r.RoleId = ur.RoleId

    CROSS JOIN MenuHierarchy mh

    LEFT JOIN dbo.App_RoleMenus rm

        ON rm.RoleId = r.RoleId

        AND rm.MenuId = mh.MenuId

        AND rm.IsActive = 1

        AND ISNULL(rm.IsDeleted, 0) = 0

    WHERE ur.UserId = @UserId

      AND ur.IsActive = 1

      AND ISNULL(ur.IsDeleted, 0) = 0

      AND
      (
          ur.ExpiresAt IS NULL
          OR ur.ExpiresAt > GETDATE()
      )

    ORDER BY
        r.RoleId,
        mh.HierarchyPath

    OPTION (MAXRECURSION 100);

END
GO
/****** Object:  StoredProcedure [dbo].[App_UserLogin]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_UserLogin]
(
    @pUsername NVARCHAR(100),
    @pPassword NVARCHAR(500),

    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص';

    BEGIN TRY

        ------------------------------------------------------------
        -- Validation
        ------------------------------------------------------------

        IF NULLIF(LTRIM(RTRIM(@pUsername)), '') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نام کاربری الزامی است.';
            RETURN;
        END;


        IF NULLIF(@pPassword, '') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'رمز عبور الزامی است.';
            RETURN;
        END;


        ------------------------------------------------------------
        -- Get UserId
        ------------------------------------------------------------

        DECLARE @UserId BIGINT;


        SELECT TOP 1
            @UserId = u.UserId
        FROM dbo.App_Users u
        WHERE
            u.Username = @pUsername
            AND u.IsActive = 1
            AND ISNULL(u.IsDeleted, 0) = 0
            AND u.PasswordHash = @pPassword;


        ------------------------------------------------------------
        -- Invalid Username / Password
        ------------------------------------------------------------

        IF @UserId IS NULL
        BEGIN
            SET @ResultCode = 401;
            SET @ResultMessage = N'نام کاربری یا رمز عبور اشتباه است.';
            RETURN;
        END;


        ------------------------------------------------------------
        -- Result Set 1
        -- User Information
        ------------------------------------------------------------

        SELECT
            u.UserId,
            u.Username,
            u.Email,
            u.Mobile,
            u.FirstName,
            u.LastName,
            u.NationalId,
            u.Gender,
            u.BirthDate,
            u.AvatarUrl,
            u.PhoneVerified,
            u.LastLoginAt,
            u.IsActive,
            u.IsDeleted,
            u.OrgId

        FROM dbo.App_Users u

        WHERE
            u.UserId = @UserId;


        ------------------------------------------------------------
        -- Result Set 2
        -- Roles + Hierarchical Menus + Permissions
        ------------------------------------------------------------

        ;WITH MenuHierarchy AS
        (
            --------------------------------------------------------
            -- Root Menus
            --------------------------------------------------------

            SELECT
                m.MenuId,
                m.ParentId,
                m.TitleFa,
                m.TitleEn,
                m.MenuUrl,
                m.Icon,
                m.SortOrder,
                m.MenuDescriptionFa,
                m.MenuDescriptionEn,
                m.IsVisible,
                m.IsActive,
                m.IsDeleted,

                0 AS MenuLevel,

                CAST(
                    RIGHT(
                        '0000000000' +
                        CAST(m.SortOrder AS VARCHAR(10)),
                        10
                    )
                    +
                    '.' +
                    RIGHT(
                        '0000000000' +
                        CAST(m.MenuId AS VARCHAR(10)),
                        10
                    )
                    AS VARCHAR(MAX)
                ) AS HierarchyPath

            FROM dbo.App_Menus m

            WHERE
                m.ParentId IS NULL
                AND m.IsActive = 1
                AND ISNULL(m.IsDeleted, 0) = 0
                AND m.IsVisible = 1


            UNION ALL


            --------------------------------------------------------
            -- Child Menus
            --------------------------------------------------------

            SELECT
                child.MenuId,
                child.ParentId,
                child.TitleFa,
                child.TitleEn,
                child.MenuUrl,
                child.Icon,
                child.SortOrder,
                child.MenuDescriptionFa,
                child.MenuDescriptionEn,
                child.IsVisible,
                child.IsActive,
                child.IsDeleted,

                parent.MenuLevel + 1 AS MenuLevel,

                CAST(
                    parent.HierarchyPath
                    +
                    '.' +
                    RIGHT(
                        '0000000000' +
                        CAST(child.SortOrder AS VARCHAR(10)),
                        10
                    )
                    +
                    '.' +
                    RIGHT(
                        '0000000000' +
                        CAST(child.MenuId AS VARCHAR(10)),
                        10
                    )
                    AS VARCHAR(MAX)
                ) AS HierarchyPath

            FROM dbo.App_Menus child

            INNER JOIN MenuHierarchy parent
                ON child.ParentId = parent.MenuId

            WHERE
                child.IsActive = 1
                AND ISNULL(child.IsDeleted, 0) = 0
                AND child.IsVisible = 1
        )


        SELECT
            --------------------------------------------------------
            -- Role
            --------------------------------------------------------

            r.RoleId,
            r.RoleCode,
            r.RoleNameFa,
            r.RoleNameEn,
            r.RoleDescriptionFa,
            r.RoleDescriptionEn,


            --------------------------------------------------------
            -- Menu
            --------------------------------------------------------

            mh.MenuId,
            mh.ParentId,

            mh.TitleFa,
            mh.TitleEn,

            mh.MenuUrl,
            mh.Icon,
            mh.SortOrder,

            mh.MenuDescriptionFa,
            mh.MenuDescriptionEn,

            mh.MenuLevel,


            --------------------------------------------------------
            -- Permission
            --------------------------------------------------------

            CASE
                WHEN rm.RoleMenuId IS NULL
                    THEN CAST(1 AS TINYINT)

                ELSE rm.PermissionLevel
            END AS PermissionLevel,


            --------------------------------------------------------
            -- Hierarchy Ordering
            --------------------------------------------------------

            mh.HierarchyPath


        FROM dbo.App_UserRoles ur

        INNER JOIN dbo.App_Roles r
            ON r.RoleId = ur.RoleId


        CROSS JOIN MenuHierarchy mh


        LEFT JOIN dbo.App_RoleMenus rm
            ON rm.RoleId = r.RoleId
            AND rm.MenuId = mh.MenuId
            AND rm.IsActive = 1
            AND ISNULL(rm.IsDeleted, 0) = 0


        WHERE
            ur.UserId = @UserId

            AND ur.IsActive = 1

            AND ISNULL(ur.IsDeleted, 0) = 0

            AND
            (
                ur.ExpiresAt IS NULL
                OR ur.ExpiresAt > GETDATE()
            )


        ------------------------------------------------------------
        -- IMPORTANT
        -- Parent -> Child -> Grandchild
        ------------------------------------------------------------

        ORDER BY
            r.RoleId,
            mh.HierarchyPath

        OPTION (MAXRECURSION 100);


        ------------------------------------------------------------
        -- Update Last Login
        ------------------------------------------------------------

        UPDATE dbo.App_Users

        SET
            LastLoginAt = GETDATE()

        WHERE
            UserId = @UserId;


        ------------------------------------------------------------
        -- Success
        ------------------------------------------------------------

        SET @ResultCode = 200;

        SET @ResultMessage =
            N'ورود با موفقیت انجام شد.';


    END TRY

    BEGIN CATCH

        SET @ResultCode = 500;

        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[App_UserProfilesGet]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_UserProfilesGet]
(
    @UserId BIGINT,

    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص';

    BEGIN TRY

        ------------------------------------------------------------
        -- Validation
        ------------------------------------------------------------

        IF @UserId IS NULL OR @UserId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'شناسه کاربر معتبر نیست.';
            RETURN;
        END;


        ------------------------------------------------------------
        -- Check User
        ------------------------------------------------------------

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE UserId = @UserId
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'کاربر مورد نظر پیدا نشد.';
            RETURN;
        END;


        ------------------------------------------------------------
        -- Get User Profile
        ------------------------------------------------------------

        SELECT
            up.UserProfileId,
            up.UserId,
            up.FatherName,
            up.BirthPlace,
            up.LandlinePhone,
            up.UserPostalCode,
            up.UserAddress,
            up.EmergencyContactName,
            up.EmergencyContactMobile,
            up.EmergencyContactRelation,
            up.Notes,
            up.CreatedAt,
            up.UserCreater,
            up.UpdatedAt,
            up.UserUpdater
        FROM dbo.App_UserProfiles up
        WHERE up.UserId = @UserId;


        ------------------------------------------------------------
        -- Success
        ------------------------------------------------------------

        SET @ResultCode = 200;
        SET @ResultMessage = N'اطلاعات پروفایل با موفقیت دریافت شد.';

    END TRY

    BEGIN CATCH

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[App_UsersCompleteProfile]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[App_UsersCompleteProfile]
(
    @UserId BIGINT,

    /* =========================
       Users
    ========================= */

    @FirstName NVARCHAR(100) = NULL,
    @LastName NVARCHAR(100) = NULL,
    @Email NVARCHAR(150) = NULL,
    @NationalId NVARCHAR(10) = NULL,
    @Gender INT = NULL,
    @BirthDate DATETIME = NULL,
    @AvatarUrl NVARCHAR(500) = NULL,

    /* =========================
       UserProfiles
    ========================= */

    @FatherName NVARCHAR(100) = NULL,
    @BirthPlace NVARCHAR(150) = NULL,
    @LandlinePhone NVARCHAR(30) = NULL,
    @UserPostalCode NVARCHAR(20) = NULL,
    @UserAddress NVARCHAR(500) = NULL,
    @EmergencyContactName NVARCHAR(200) = NULL,
    @EmergencyContactMobile NVARCHAR(30) = NULL,
    @EmergencyContactRelation NVARCHAR(100) = NULL,
    @ProfileNotes NVARCHAR(2000) = NULL,

    /* =========================
       UserResidencies
    ========================= */

    @UnitId BIGINT = NULL,
    @RelationshipType TINYINT = NULL,
    @StartDate DATETIME = NULL,
    @EndDate DATETIME = NULL,
    @ResidencyNotes NVARCHAR(1000) = NULL,

    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص';


    BEGIN TRY

        /* =========================================
           User
        ========================================= */

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE UserId = @UserId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage =
                N'کاربر پیدا نشد.';
            RETURN;
        END;


        /* =========================================
           Email Duplicate
        ========================================= */

        IF @Email IS NOT NULL
        AND EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE Email = @Email
              AND UserId <> @UserId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این ایمیل قبلاً توسط کاربر دیگری ثبت شده است.';
            RETURN;
        END;


        /* =========================================
           NationalId Duplicate
        ========================================= */

        IF @NationalId IS NOT NULL
        AND EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE NationalId = @NationalId
              AND UserId <> @UserId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این کد ملی قبلاً توسط کاربر دیگری ثبت شده است.';
            RETURN;
        END;


        /* =========================================
           Gender
        ========================================= */

        IF @Gender IS NOT NULL
           AND @Gender NOT IN (1,2)
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'مقدار جنسیت معتبر نیست.';
            RETURN;
        END;


        /* =========================================
           Unit
        ========================================= */

        IF @UnitId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Units
                WHERE UnitId = @UnitId
                  AND IsActive = 1
                  AND ISNULL(IsDeleted, 0) = 0
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage =
                    N'واحد انتخاب شده معتبر نیست.';
                RETURN;
            END;


            IF @RelationshipType IS NULL
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'نوع رابطه با واحد الزامی است.';
                RETURN;
            END;


            IF @RelationshipType NOT BETWEEN 1 AND 5
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'نوع رابطه با واحد معتبر نیست.';
                RETURN;
            END;

        END;


        BEGIN TRANSACTION;


        /* =========================================
           Update Users
           
           COALESCE:
           اگر ورودی NULL بود مقدار قبلی حفظ می‌شود.
        ========================================= */

        UPDATE dbo.App_Users
        SET
            FirstName =
                COALESCE(@FirstName, FirstName),

            LastName =
                COALESCE(@LastName, LastName),

            Email =
                COALESCE(@Email, Email),

            NationalId =
                COALESCE(@NationalId, NationalId),

            Gender =
                COALESCE(@Gender, Gender),

            BirthDate =
                COALESCE(@BirthDate, BirthDate),

            AvatarUrl =
                COALESCE(@AvatarUrl, AvatarUrl),

            UpdatedAt = GETDATE(),

            UserUpdater = @UserId

        WHERE UserId = @UserId;


        /* =========================================
           UserProfiles
        ========================================= */

        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_UserProfiles
            WHERE UserId = @UserId
        )
        BEGIN

            UPDATE dbo.App_UserProfiles
            SET
                FatherName =
                    COALESCE(@FatherName, FatherName),

                BirthPlace =
                    COALESCE(@BirthPlace, BirthPlace),

                LandlinePhone =
                    COALESCE(@LandlinePhone, LandlinePhone),

                UserPostalCode =
                    COALESCE(@UserPostalCode, UserPostalCode),

                UserAddress =
                    COALESCE(@UserAddress, UserAddress),

                EmergencyContactName =
                    COALESCE(
                        @EmergencyContactName,
                        EmergencyContactName
                    ),

                EmergencyContactMobile =
                    COALESCE(
                        @EmergencyContactMobile,
                        EmergencyContactMobile
                    ),

                EmergencyContactRelation =
                    COALESCE(
                        @EmergencyContactRelation,
                        EmergencyContactRelation
                    ),

                Notes =
                    COALESCE(@ProfileNotes, Notes),

                UpdatedAt = GETDATE(),

                UserUpdater = @UserId

            WHERE UserId = @UserId;

        END
        ELSE
        BEGIN

            INSERT INTO dbo.App_UserProfiles
            (
                UserId,
                FatherName,
                BirthPlace,
                LandlinePhone,
                UserPostalCode,
                UserAddress,
                EmergencyContactName,
                EmergencyContactMobile,
                EmergencyContactRelation,
                Notes,
                CreatedAt,
                UserCreater
            )
            VALUES
            (
                @UserId,
                @FatherName,
                @BirthPlace,
                @LandlinePhone,
                @UserPostalCode,
                @UserAddress,
                @EmergencyContactName,
                @EmergencyContactMobile,
                @EmergencyContactRelation,
                @ProfileNotes,
                GETDATE(),
                @UserId
            );

        END;


        /* =========================================
           Residency
        ========================================= */

        IF @UnitId IS NOT NULL
        BEGIN

            /*
                اگر قبلاً همین واحد برای این کاربر
                وجود نداشته باشد ایجاد می‌کنیم.
            */

            IF EXISTS
            (
                SELECT 1
                FROM dbo.UserResidencies
                WHERE UserId = @UserId
                  AND UnitId = @UnitId
                  AND ISNULL(IsDeleted, 0) = 0
            )
            BEGIN

                UPDATE dbo.UserResidencies
                SET
                    RelationshipType =
                        COALESCE(
                            @RelationshipType,
                            RelationshipType
                        ),

                    StartDate =
                        COALESCE(@StartDate, StartDate),

                    EndDate =
                        COALESCE(@EndDate, EndDate),

                    Notes =
                        COALESCE(
                            @ResidencyNotes,
                            Notes
                        ),

                    IsActive = 1,

                    UpdatedAt = GETDATE(),

                    UserUpdater = @UserId

                WHERE UserId = @UserId
                  AND UnitId = @UnitId
                  AND ISNULL(IsDeleted, 0) = 0;

            END
            ELSE
            BEGIN

                INSERT INTO dbo.UserResidencies
                (
                    UserId,
                    UnitId,
                    RelationshipType,
                    StartDate,
                    EndDate,
                    IsActive,
                    IsDeleted,
                    Notes,
                    CreatedAt,
                    UserCreater
                )
                VALUES
                (
                    @UserId,
                    @UnitId,
                    @RelationshipType,
                    @StartDate,
                    @EndDate,
                    1,
                    0,
                    @ResidencyNotes,
                    GETDATE(),
                    @UserId
                );

            END;

        END;


        COMMIT TRANSACTION;


        SET @ResultCode = 200;
        SET @ResultMessage =
            N'اطلاعات پروفایل با موفقیت ثبت شد.';


        SELECT
            U.UserId,
            U.Username,
            U.Email,
            U.Mobile,
            U.FirstName,
            U.LastName,
            U.NationalId,
            U.Gender,
            U.BirthDate,
            U.AvatarUrl,
            U.PhoneVerified,
            U.IsActive
        FROM dbo.App_Users U
        WHERE U.UserId = @UserId;


        SELECT
            P.*
        FROM dbo.App_UserProfiles P
        WHERE P.UserId = @UserId;


        SELECT
            R.*
        FROM dbo.UserResidencies R
        WHERE R.UserId = @UserId
          AND ISNULL(R.IsDeleted, 0) = 0;


        RETURN;

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage =
            N'خطا در تکمیل اطلاعات کاربر: '
            + ERROR_MESSAGE();

        RETURN;

    END CATCH

END;
GO
/****** Object:  StoredProcedure [dbo].[App_UserSessionAuthorizationGet]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[App_UserSessionAuthorizationGet]
(
    @SessionId UNIQUEIDENTIFIER,
    @UserId BIGINT,

    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص.';

    BEGIN TRY

        SELECT TOP 1
            s.SessionId,
            s.UserId,
            s.ActiveRoleId,
            r.RoleCode
        FROM dbo.App_UserSessions s
        LEFT JOIN dbo.App_Roles r
            ON r.RoleId = s.ActiveRoleId
        INNER JOIN dbo.App_Users u
            ON u.UserId = s.UserId
           AND u.IsActive = 1
           AND ISNULL(u.IsDeleted, 0) = 0
        WHERE s.SessionId = @SessionId
          AND s.UserId = @UserId
          AND s.RevokedAt IS NULL;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultCode = 401;
            SET @ResultMessage = N'نشست کاربر معتبر نیست.';
            RETURN;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage = N'نشست معتبر است.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[App_UserSessionClearActiveRole]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[App_UserSessionClearActiveRole]
(
    @SessionId UNIQUEIDENTIFIER,
    @UserId BIGINT,

    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص.';

    BEGIN TRY

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_UserSessions
            WHERE SessionId = @SessionId
              AND UserId = @UserId
              AND RevokedAt IS NULL
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نشست کاربر پیدا نشد.';
            RETURN;
        END;

        UPDATE dbo.App_UserSessions
        SET ActiveRoleId = NULL
        WHERE SessionId = @SessionId
          AND UserId = @UserId
          AND RevokedAt IS NULL;

        IF @@ROWCOUNT <> 1
        BEGIN
            SET @ResultCode = 500;
            SET @ResultMessage = N'Active Role نشست به‌روزرسانی نشد.';
            RETURN;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage = N'Active Role نشست با موفقیت پاک شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END
