CREATE PROCEDURE [dbo].[App_UserSessionCreate]
(
    @SessionId UNIQUEIDENTIFIER,
    @UserId BIGINT,
    @ActiveRoleId BIGINT = NULL,
    @DeviceName NVARCHAR(200) = NULL,
    @UserAgent NVARCHAR(1000) = NULL,
    @CreatedIp NVARCHAR(64) = NULL
)
AS
BEGIN

    SET NOCOUNT ON;

    INSERT INTO dbo.App_UserSessions
    (
        SessionId,
        UserId,
        ActiveRoleId,
        DeviceName,
        UserAgent,
        CreatedIp,
        CreatedAt,
        LastSeenAt
    )
    VALUES
    (
        @SessionId,
        @UserId,
        @ActiveRoleId,
        @DeviceName,
        @UserAgent,
        @CreatedIp,
        SYSUTCDATETIME(),
        SYSUTCDATETIME()
    );

    SELECT
        SessionId,
        UserId,
        ActiveRoleId,
        DeviceName,
        UserAgent,
        CreatedIp,
        CreatedAt,
        LastSeenAt,
        RevokedAt
    FROM dbo.App_UserSessions
    WHERE SessionId = @SessionId;

END
