/****** Object:  StoredProcedure [dbo].[App_UserSessionRevoke]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   REVOKE CURRENT SESSION
   ========================================================= */

CREATE PROCEDURE [dbo].[App_UserSessionRevoke]
(
    @SessionId UNIQUEIDENTIFIER
)
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        UPDATE dbo.App_UserSessions
        SET RevokedAt = SYSUTCDATETIME()
        WHERE SessionId = @SessionId
          AND RevokedAt IS NULL;


        UPDATE dbo.App_RefreshTokens
        SET RevokedAt = GETUTCDATE()
        WHERE SessionId = @SessionId
          AND RevokedAt IS NULL;


        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        THROW;

    END CATCH

END
GO
