/****** Object:  StoredProcedure [dbo].[App_UserSessionSetActiveRole]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   SET ACTIVE ROLE
   ========================================================= */

CREATE PROCEDURE [dbo].[App_UserSessionSetActiveRole]
(
    @SessionId UNIQUEIDENTIFIER,
    @UserId BIGINT,
    @RoleId BIGINT,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN

    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطا در انتخاب نقش.';

    BEGIN TRY

        BEGIN TRANSACTION;

        /* Session */

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_UserSessions WITH (UPDLOCK, HOLDLOCK)
            WHERE SessionId = @SessionId
              AND UserId = @UserId
              AND RevokedAt IS NULL
        )
        BEGIN

            SET @ResultCode = 404;
            SET @ResultMessage = N'نشست معتبر نیست.';

            ROLLBACK TRANSACTION;
            RETURN;

        END


        /* User */

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE UserId = @UserId
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN

            SET @ResultCode = 401;
            SET @ResultMessage = N'کاربر فعال نیست.';

            ROLLBACK TRANSACTION;
            RETURN;

        END


        /* User Role */

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_UserRoles ur
            INNER JOIN dbo.App_Roles r
                ON r.RoleId = ur.RoleId
            WHERE ur.UserId = @UserId
              AND ur.RoleId = @RoleId
              AND ur.IsActive = 1
              AND ISNULL(ur.IsDeleted, 0) = 0
              AND
              (
                    ur.ExpiresAt IS NULL
                    OR ur.ExpiresAt > GETDATE()
              )
        )
        BEGIN

            SET @ResultCode = 403;
            SET @ResultMessage = N'کاربر دسترسی به این نقش را ندارد.';

            ROLLBACK TRANSACTION;
            RETURN;

        END


        UPDATE dbo.App_UserSessions
        SET
            ActiveRoleId = @RoleId,
            LastSeenAt = SYSUTCDATETIME()
        WHERE SessionId = @SessionId
          AND UserId = @UserId
          AND RevokedAt IS NULL;


        SET @ResultCode = 200;
        SET @ResultMessage = N'نقش فعال با موفقیت تغییر کرد.';

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH

END
GO
