/****** Object:  StoredProcedure [dbo].[App_UsersLoginGet]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[App_UsersLoginGet]
(
    @Username NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(LTRIM(RTRIM(@Username)), '') IS NULL
        THROW 50001, N'نام کاربری الزامی است.', 1;


    ---------------------------------------------------------
    -- USER
    ---------------------------------------------------------

    SELECT
        u.UserId,
        u.Username,
        u.PasswordHash,
        u.Email,
        u.Mobile,
        u.FirstName,
        u.LastName,
        u.NationalId,
        u.Gender,
        u.BirthDate,
        u.AvatarUrl,
        u.PhoneVerified,
        u.LastLoginAt,
        u.IsActive,
        u.IsDeleted
    FROM dbo.App_Users u
    WHERE
        u.Username = @Username
        AND u.IsActive = 1
        AND ISNULL(u.IsDeleted, 0) = 0;


    ---------------------------------------------------------
    -- ROLE + MENU + PERMISSION
    ---------------------------------------------------------

    SELECT
        r.RoleId,
        r.RoleCode,

        r.RoleNameFa,
        r.RoleNameEn,

        r.RoleDescriptionFa,
        r.RoleDescriptionEn,

        m.MenuId,
        m.ParentId,

        m.TitleFa,
        m.TitleEn,

        m.MenuUrl,
        m.Icon,
        m.SortOrder,

        ISNULL(rm.PermissionLevel, 1) AS PermissionLevel

    FROM dbo.App_UserRoles ur

    INNER JOIN dbo.App_Roles r
        ON r.RoleId = ur.RoleId

    LEFT JOIN dbo.App_RoleMenus rm
        ON rm.RoleId = r.RoleId
        AND rm.IsActive = 1
        AND ISNULL(rm.IsDeleted, 0) = 0

    LEFT JOIN dbo.App_Menus m
        ON m.MenuId = rm.MenuId
        AND m.IsActive = 1
        AND ISNULL(m.IsDeleted, 0) = 0

    WHERE
        ur.UserId =
        (
            SELECT TOP 1 UserId
            FROM dbo.App_Users
            WHERE Username = @Username
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
        )

        AND ur.IsActive = 1
        AND ISNULL(ur.IsDeleted, 0) = 0

        AND
        (
            ur.ExpiresAt IS NULL
            OR ur.ExpiresAt > GETDATE()
        )

    ORDER BY
        r.RoleId,
        m.ParentId,
        m.SortOrder;
END
GO
/****** Object:  StoredProcedure [dbo].[App_UsersOtpVerify]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_UsersOtpVerify]
(
    @UserId             BIGINT,
    @OtpRequestId       BIGINT,
    @OtpCode            VARCHAR(6),

    @RoleId             BIGINT = NULL,

    @UnitId             BIGINT = NULL,
    @RelationshipType   TINYINT = NULL,
    @StartDate          DATETIME = NULL,
    @EndDate            DATETIME = NULL,

    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص';

    DECLARE @Now DATETIME2(0) = SYSDATETIME(),
        @StoredOtpCode NVARCHAR(10),
        @ExpiresAt DATETIME2(0),
        @AttemptCount INT,
        @MaxAttempts INT,
        @IsUsed BIT,
        @IsBlocked BIT,
        @Mobile NVARCHAR(30),
        @UserExists BIT = 0;


    BEGIN TRY

        /* =========================================
           Validation
        ========================================= */

        IF @UserId IS NULL
           OR @OtpRequestId IS NULL
           OR @OtpCode IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'اطلاعات تایید OTP ناقص است.';
            RETURN;
        END;


        IF LEN(@OtpCode) <> 6
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'کد تایید باید 6 رقمی باشد.';
            RETURN;
        END;


        /* =========================================
           User
        ========================================= */

        SELECT
            @UserExists = 1,
            @Mobile = Mobile
        FROM dbo.App_Users
        WHERE UserId = @UserId
          AND ISNULL(IsDeleted, 0) = 0;


        IF @UserExists = 0
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage =
                N'کاربر پیدا نشد.';
            RETURN;
        END;


        /* =========================================
           OTP
        ========================================= */

        SELECT
            @StoredOtpCode = OtpCode,
            @ExpiresAt = ExpiresAt,
            @AttemptCount = AttemptCount,
            @MaxAttempts = MaxAttempts,
            @IsUsed = IsUsed,
            @IsBlocked = IsBlocked
        FROM dbo.App_UserOtpRequests
        WHERE OtpRequestId = @OtpRequestId
          AND UserId = @UserId
          AND Mobile = @Mobile
          AND OtpPurpose = 1;


        IF @StoredOtpCode IS NULL
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage =
                N'کد تایید پیدا نشد.';
            RETURN;
        END;


        IF @IsUsed = 1
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این کد قبلاً استفاده شده است.';
            RETURN;
        END;


        IF @IsBlocked = 1
        BEGIN
            SET @ResultCode = 429;
            SET @ResultMessage =
                N'این کد دیگر قابل استفاده نیست.';
            RETURN;
        END;


        IF @ExpiresAt <= @Now
        BEGIN
            SET @ResultCode = 410;
            SET @ResultMessage =
                N'کد تایید منقضی شده است.';
            RETURN;
        END;


        IF @AttemptCount >= @MaxAttempts
        BEGIN

            UPDATE dbo.App_UserOtpRequests
            SET IsBlocked = 1
            WHERE OtpRequestId = @OtpRequestId;

            SET @ResultCode = 429;
            SET @ResultMessage =
                N'تعداد تلاش‌های مجاز برای این کد به پایان رسیده است.';
            RETURN;
        END;


        /* =========================================
           Calculate Hash
        ========================================= */

        --SET @OtpCode = '1234'
            


        /* =========================================
           Wrong OTP
        ========================================= */

        IF @OtpCode <> @StoredOtpCode
        BEGIN

            UPDATE dbo.App_UserOtpRequests
            SET
                AttemptCount = AttemptCount + 1,
                IsBlocked =
                    CASE
                        WHEN AttemptCount + 1 >= MaxAttempts
                        THEN 1
                        ELSE 0
                    END
            WHERE OtpRequestId = @OtpRequestId;

            SET @ResultCode = 401;
            SET @ResultMessage =
                N'کد تایید صحیح نیست.';
            RETURN;
        END;


        /* =========================================
           Role Validation
        ========================================= */

        IF @RoleId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.App_Roles
                WHERE RoleId = @RoleId
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage =
                    N'نقش انتخاب شده وجود ندارد.';
                RETURN;
            END;

        END;


        /* =========================================
           Unit Validation
        ========================================= */

        IF @UnitId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Units
                WHERE UnitId = @UnitId
                  AND IsActive = 1
                  AND ISNULL(IsDeleted, 0) = 0
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage =
                    N'واحد انتخاب شده وجود ندارد یا فعال نیست.';
                RETURN;
            END;


            IF @RelationshipType IS NULL
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'نوع رابطه با واحد الزامی است.';
                RETURN;
            END;


            IF @RelationshipType NOT BETWEEN 1 AND 5
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'نوع رابطه با واحد معتبر نیست.';
                RETURN;
            END;

        END;


        BEGIN TRANSACTION;


        /* =========================================
           Mark OTP Used
        ========================================= */

        UPDATE dbo.App_UserOtpRequests
        SET
            IsUsed = 1,
            VerifiedAt = @Now
        WHERE OtpRequestId = @OtpRequestId
          AND IsUsed = 0
          AND IsBlocked = 0;


        IF @@ROWCOUNT <> 1
        BEGIN
            ROLLBACK TRANSACTION;

            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این درخواست OTP دیگر قابل استفاده نیست.';
            RETURN;
        END;


        /* =========================================
           Activate User
        ========================================= */

        UPDATE dbo.App_Users
        SET
            PhoneVerified = 1,
            IsActive = 1,
            IsDeleted = 0,
            UpdatedAt = GETDATE(),
            UserUpdater = NULL
        WHERE UserId = @UserId;


        /* =========================================
           Default UserProfile
        ========================================= */

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_UserProfiles
            WHERE UserId = @UserId
        )
        BEGIN

            INSERT INTO dbo.App_UserProfiles
            (
                UserId,
                FatherName,
                BirthPlace,
                LandlinePhone,
                UserPostalCode,
                UserAddress,
                EmergencyContactName,
                EmergencyContactMobile,
                EmergencyContactRelation,
                Notes,
                CreatedAt,
                UserCreater
            )
            VALUES
            (
                @UserId,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                GETDATE(),
                NULL
            );

        END;


        /* =========================================
           User Role
        ========================================= */

        IF @RoleId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.App_UserRoles
                WHERE UserId = @UserId
                  AND RoleId = @RoleId
            )
            BEGIN

                INSERT INTO dbo.App_UserRoles
                (
                    UserId,
                    RoleId,
                    AssignedAt,
                    ExpiresAt,
                    IsActive,
                    IsDeleted,
                    CreatedAt,
                    UserCreater,
                    Notes
                )
                VALUES
                (
                    @UserId,
                    @RoleId,
                    GETDATE(),
                    NULL,
                    1,
                    0,
                    GETDATE(),
                    NULL,
                    N'Assigned during signup'
                );

            END;

        END;


        /* =========================================
           User Residency
        ========================================= */

        IF @UnitId IS NOT NULL
        BEGIN

            INSERT INTO dbo.UserResidencies
            (
                UserId,
                UnitId,
                RelationshipType,
                StartDate,
                EndDate,
                IsActive,
                IsDeleted,
                Notes,
                CreatedAt,
                UserCreater
            )
            VALUES
            (
                @UserId,
                @UnitId,
                @RelationshipType,
                @StartDate,
                @EndDate,
                1,
                0,
                NULL,
                GETDATE(),
                NULL
            );

        END;


        COMMIT TRANSACTION;


        SET @ResultCode = 200;
        SET @ResultMessage =
            N'ثبت نام با موفقیت انجام شد.';

        /* اطلاعات مناسب برای ساخت Session/JWT */

        SELECT
            U.UserId,
            U.Username,
            U.Email,
            U.Mobile,
            U.FirstName,
            U.LastName,
            U.Gender,
            U.PhoneVerified,
            U.IsActive
        FROM dbo.App_Users U
        WHERE U.UserId = @UserId;

        RETURN;

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage =
            N'خطا در تایید ثبت نام: '
            + ERROR_MESSAGE();

        RETURN;

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UsersSignup]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[App_UsersSignup]
(
    @Mobile             NVARCHAR(30),
    @Username           NVARCHAR(100) = NULL,
    @PasswordHash       NVARCHAR(500) = NULL,

    @FirstName          NVARCHAR(100) = NULL,
    @LastName           NVARCHAR(100) = NULL,
    @Gender             INT = 0,

    @Email              NVARCHAR(150) = NULL,
    @NationalId         NVARCHAR(10) = NULL,
    @BirthDate          DATETIME = NULL,

    -- این پارامتر دیگر نباید برای تعیین نقش مدیریتی استفاده شود
    @RoleId             BIGINT = NULL,

    @RequestIp          NVARCHAR(50) = NULL,
    @UserAgent          NVARCHAR(500) = NULL,

    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT,

    @UserId             BIGINT OUTPUT,
    @OtpRequestId       BIGINT OUTPUT,
    @OtpCode            VARCHAR(6) OUTPUT,

    -- اطلاعات سازمان برای تکمیل ثبت‌نام پس از تأیید OTP
    @OrgName            NVARCHAR(200) = NULL,
    @OrgType            INT = NULL,
    @GeoId              NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای نامشخص';
    SET @UserId = NULL;
    SET @OtpRequestId = NULL;
    SET @OtpCode = NULL;

    DECLARE
        @Now DATETIME2(0) = SYSDATETIME(),
        @OtpExpiresAt DATETIME2(0),
        @NormalizedMobile NVARCHAR(30),
        @OtpCodeInt INT,
        @ExistingUserId BIGINT = NULL,
        @LastOtpCreatedAt DATETIME2(0),
        @OtpCount15Min INT,
        @DailyOtpCount INT,
        @RateLimitId BIGINT;

    BEGIN TRY
        /* =========================================
           اعتبارسنجی ورودی‌ها
        ========================================= */

        SET @NormalizedMobile =
            REPLACE(
                REPLACE(
                    REPLACE(
                        REPLACE(LTRIM(RTRIM(@Mobile)), N' ', N''),
                    N'-', N''),
                N'(', N''),
            N')', N'');

        SET @Username = NULLIF(LTRIM(RTRIM(@Username)), N'');
        SET @Email = NULLIF(LTRIM(RTRIM(@Email)), N'');
        SET @NationalId = NULLIF(LTRIM(RTRIM(@NationalId)), N'');
        SET @OrgName = NULLIF(LTRIM(RTRIM(@OrgName)), N'');
        SET @GeoId = NULLIF(LTRIM(RTRIM(@GeoId)), N'');

        SET @FirstName =
            ISNULL(NULLIF(LTRIM(RTRIM(@FirstName)), N''), N'کاربر');

        SET @LastName =
            ISNULL(NULLIF(LTRIM(RTRIM(@LastName)), N''), N'جدید');

        IF @NormalizedMobile IS NULL
           OR LEN(@NormalizedMobile) < 10
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'شماره موبایل معتبر نیست.';
            RETURN;
        END;

        IF @OrgName IS NULL OR @OrgType IS NULL OR @GeoId IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'نام سازمان، نوع سازمان و موقعیت جغرافیایی الزامی است.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_Geo
            WHERE GeoId = @GeoId
        )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'موقعیت جغرافیایی معتبر نیست.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_LookupValues
            WHERE LookupValueId = @OrgType
        )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نوع سازمان معتبر نیست.';
            RETURN;
        END;

        /*
          نقش از سمت کلاینت پذیرفته نمی‌شود.
          این مسیر فقط درخواست ثبت‌نام اولیه است.
        */
        SET @RoleId = NULL;

        IF @Username IS NOT NULL AND @PasswordHash IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'برای ثبت‌نام با نام کاربری، کلمه عبور الزامی است.';
            RETURN;
        END;

        IF @Username IS NOT NULL AND LEN(@Username) < 3
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'نام کاربری باید حداقل 3 کاراکتر باشد.';
            RETURN;
        END;

        IF @Username IS NOT NULL AND LEN(@PasswordHash) < 20
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'PasswordHash معتبر نیست.';
            RETURN;
        END;

        /* =========================================
           بررسی تکراری بودن اطلاعات
        ========================================= */

        IF @Username IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE Username = @Username
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این نام کاربری قبلاً ثبت شده است.';
            RETURN;
        END;

        IF @Email IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE Email = @Email
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این ایمیل قبلاً ثبت شده است.';
            RETURN;
        END;

        IF @NationalId IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE NationalId = @NationalId
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این کد ملی قبلاً ثبت شده است.';
            RETURN;
        END;

        /*
          اگر موبایل قبلاً متعلق به کاربر فعال و تأییدشده باشد،
          ثبت‌نام مجدد مجاز نیست.
        */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE Mobile = @NormalizedMobile
              AND IsActive = 1
              AND PhoneVerified = 1
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این شماره موبایل قبلاً ثبت‌نام و تأیید شده است.';
            RETURN;
        END;

        /*
          از اتصال مجدد یک کاربر موجود به ثبت‌نام اولیه سازمان
          جلوگیری می‌کنیم. کاربر موقت قدیمی باید فقط در صورتی
          قابل استفاده باشد که هنوز OrgId نداشته باشد.
        */
        SELECT TOP (1)
            @ExistingUserId = UserId
        FROM dbo.App_Users
        WHERE Mobile = @NormalizedMobile
          AND ISNULL(IsDeleted, 0) = 0
        ORDER BY UserId DESC;

        IF @ExistingUserId IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE UserId = @ExistingUserId
                 AND OrgId IS NOT NULL
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این کاربر قبلاً به یک سازمان متصل شده است.';
            RETURN;
        END;

        /* =========================================
           محدودیت درخواست OTP
        ========================================= */

        SELECT
            @RateLimitId = RateLimitId,
            @LastOtpCreatedAt = LastRequestAt,
            @DailyOtpCount = DailyCount
        FROM dbo.App_UserOtpRateLimits
        WHERE Mobile = @NormalizedMobile;

        IF @LastOtpCreatedAt IS NOT NULL
           AND DATEDIFF(SECOND, @LastOtpCreatedAt, @Now) < 60
        BEGIN
            SET @ResultCode = 429;
            SET @ResultMessage =
                N'لطفاً حداقل 60 ثانیه برای ارسال مجدد کد صبر کنید.';
            RETURN;
        END;

        IF ISNULL(@DailyOtpCount, 0) >= 20
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_UserOtpRateLimits
               WHERE RateLimitId = @RateLimitId
                 AND DailyDate = CONVERT(DATE, @Now)
           )
        BEGIN
            SET @ResultCode = 429;
            SET @ResultMessage =
                N'تعداد درخواست‌های OTP این شماره برای امروز بیش از حد مجاز است.';
            RETURN;
        END;

        SELECT @OtpCount15Min = COUNT(*)
        FROM dbo.App_UserOtpRequests
        WHERE Mobile = @NormalizedMobile
          AND CreatedAt >= DATEADD(MINUTE, -15, @Now);

        IF @OtpCount15Min >= 5
        BEGIN
            SET @ResultCode = 429;
            SET @ResultMessage =
                N'تعداد درخواست‌های OTP بیش از حد مجاز است. لطفاً بعداً تلاش کنید.';
            RETURN;
        END;

        /* =========================================
           تولید OTP
        ========================================= */

        SET @OtpCodeInt = ABS(CHECKSUM(NEWID())) % 900000 + 100000;
        SET @OtpCode =
            RIGHT('000000' + CONVERT(VARCHAR(6), @OtpCodeInt), 6);

        SET @OtpExpiresAt = DATEADD(MINUTE, 2, @Now);

        BEGIN TRANSACTION;

        /* =========================================
           ایجاد یا به‌روزرسانی کاربر موقت
        ========================================= */

        IF @ExistingUserId IS NULL
        BEGIN
            INSERT INTO dbo.App_Users
            (
                Username,
                PasswordHash,
                Email,
                Mobile,
                FirstName,
                LastName,
                NationalId,
                Gender,
                BirthDate,
                PhoneVerified,
                IsActive,
                IsDeleted,
                CreatedAt
            )
            VALUES
            (
                @Username,
                @PasswordHash,
                @Email,
                @NormalizedMobile,
                @FirstName,
                @LastName,
                @NationalId,
                @Gender,
                @BirthDate,
                0,
                0,
                0,
                GETDATE()
            );

            SET @UserId = CONVERT(BIGINT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            SET @UserId = @ExistingUserId;

            UPDATE dbo.App_Users
            SET
                Username = @Username,
                PasswordHash = @PasswordHash,
                Email = @Email,
                FirstName = @FirstName,
                LastName = @LastName,
                NationalId = @NationalId,
                Gender = @Gender,
                BirthDate = @BirthDate,
                PhoneVerified = 0,
                IsActive = 0,
                UpdatedAt = GETDATE()
            WHERE UserId = @UserId
              AND OrgId IS NULL;
        END;

        /* =========================================
           باطل کردن OTPهای قبلی تأییدنشده
        ========================================= */

        UPDATE dbo.App_UserOtpRequests
        SET IsBlocked = 1
        WHERE UserId = @UserId
          AND OtpPurpose = 1
          AND IsUsed = 0
          AND IsBlocked = 0;

        /*
          مهم:
          در این نقطه باید مقدار OTP با قالبی ذخیره شود که
          پروسیجر تأیید OTP فعلی تو انتظار دارد.

          مقدار ثابت '1234' عمداً استفاده نشده است.
          برای تعیین عبارت INSERT صحیح، نوع ستون OtpCode
          و کد پروسیجر تأیید OTP لازم است.
        */

        INSERT INTO dbo.App_UserOtpRequests
        (
            UserId,
            Mobile,
            OtpPurpose,
            OtpCode,
            CreatedAt,
            ExpiresAt,
            VerifiedAt,
            AttemptCount,
            MaxAttempts,
            IsUsed,
            IsBlocked,
            RequestIp,
            UserAgent
        )
        VALUES
        (
            @UserId,
            @NormalizedMobile,
            1,
            @OtpCode, -- موقت؛ باید با قالب ذخیره‌سازی OTP فعلی هماهنگ شود
            @Now,
            @OtpExpiresAt,
            NULL,
            0,
            5,
            0,
            0,
            @RequestIp,
            @UserAgent
        );

        SET @OtpRequestId = CONVERT(BIGINT, SCOPE_IDENTITY());

        /* =========================================
           ثبت محدودیت ارسال
        ========================================= */

        IF @RateLimitId IS NULL
        BEGIN
            INSERT INTO dbo.App_UserOtpRateLimits
            (
                Mobile,
                WindowStart,
                RequestCount,
                DailyDate,
                DailyCount,
                BlockedUntil,
                LastRequestAt
            )
            VALUES
            (
                @NormalizedMobile,
                @Now,
                1,
                CONVERT(DATE, @Now),
                1,
                NULL,
                @Now
            );
        END
        ELSE
        BEGIN
            UPDATE dbo.App_UserOtpRateLimits
            SET
                RequestCount =
                    CASE
                        WHEN WindowStart < DATEADD(MINUTE, -15, @Now)
                        THEN 1
                        ELSE RequestCount + 1
                    END,
                WindowStart =
                    CASE
                        WHEN WindowStart < DATEADD(MINUTE, -15, @Now)
                        THEN @Now
                        ELSE WindowStart
                    END,
                DailyCount =
                    CASE
                        WHEN DailyDate <> CONVERT(DATE, @Now)
                        THEN 1
                        ELSE DailyCount + 1
                    END,
                DailyDate = CONVERT(DATE, @Now),
                LastRequestAt = @Now,
                BlockedUntil = NULL
            WHERE RateLimitId = @RateLimitId;
        END;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage =
            N'درخواست ثبت‌نام ایجاد شد؛ برای تکمیل ثبت‌نام، OTP را تأیید کنید.';

        SELECT
            @UserId AS UserId,
            @OtpRequestId AS OtpRequestId,
            @OtpCode AS OtpCode,
            @OtpExpiresAt AS OtpExpiresAt;

        RETURN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage =
            N'خطا در ایجاد ثبت‌نام: ' + ERROR_MESSAGE();

        SET @UserId = NULL;
        SET @OtpRequestId = NULL;
        SET @OtpCode = NULL;

        RETURN;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UsersSignupStartOtp]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[App_UsersSignupStartOtp]
(
    @Mobile       NVARCHAR(30),
    @OrgName      NVARCHAR(200),
    @OrgType      INT,
    @GeoId        NVARCHAR(10),
    @RequestIp    NVARCHAR(50) = NULL,
    @UserAgent    NVARCHAR(500) = NULL,

    @ResultCode    INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT,
    @UserId        BIGINT OUTPUT,
    @OtpRequestId  BIGINT OUTPUT,
    @OtpExpiresAt  DATETIME2(0) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(0) = SYSDATETIME();
    DECLARE @NormalizedMobile NVARCHAR(30);
    DECLARE @NormalizedOrgName NVARCHAR(200);
    DECLARE @OtpCode NVARCHAR(30) = N'1234';
    DECLARE @RoleId BIGINT = 1;

    SELECT
        @ResultCode = 500,
        @ResultMessage = N'خطای پیش‌بینی‌نشده.',
        @UserId = NULL,
        @OtpRequestId = NULL,
        @OtpExpiresAt = NULL;

    SET @NormalizedMobile = LTRIM(RTRIM(@Mobile));
    SET @NormalizedMobile = REPLACE(@NormalizedMobile, N' ', N'');
    SET @NormalizedMobile = REPLACE(@NormalizedMobile, N'-', N'');
    SET @NormalizedMobile = REPLACE(@NormalizedMobile, N'(', N'');
    SET @NormalizedMobile = REPLACE(@NormalizedMobile, N')', N'');

    SET @NormalizedOrgName = LTRIM(RTRIM(@OrgName));

    IF NULLIF(@NormalizedMobile, N'') IS NULL
       OR LEN(@NormalizedMobile) < 10
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شماره موبایل معتبر نیست.';
        RETURN;
    END;

    IF NULLIF(@NormalizedOrgName, N'') IS NULL
       OR @OrgType IS NULL
       OR NULLIF(LTRIM(RTRIM(@GeoId)), N'') IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام سازمان، نوع سازمان و موقعیت جغرافیایی الزامی هستند.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_Geo
        WHERE GeoId = @GeoId
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'موقعیت جغرافیایی معتبر نیست.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_LookupValues
        WHERE LookupValueId = @OrgType
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نوع سازمان معتبر نیست.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.App_Roles
        WHERE RoleId = @RoleId
    )
    BEGIN
        SET @ResultCode = 500;
        SET @ResultMessage = N'نقش مدیر ساختمان با شناسه 1 در دیتابیس وجود ندارد.';
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* جلوگیری از ثبت سازمان تکراری */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Organizations WITH (UPDLOCK, HOLDLOCK)
            WHERE LTRIM(RTRIM(OrgName)) = @NormalizedOrgName
              AND OrgType = @OrgType
              AND GeoId = @GeoId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'سازمانی با این نام، نوع و موقعیت جغرافیایی قبلاً ثبت شده است.';
            RETURN;
        END;

        /* شماره متعلق به حساب فعال و تأییدشده نباشد */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_Users WITH (UPDLOCK, HOLDLOCK)
            WHERE Mobile = @NormalizedMobile
              AND ISNULL(IsDeleted, 0) = 0
              AND IsActive = 1
              AND PhoneVerified = 1
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'این شماره موبایل قبلاً ثبت و تأیید شده است.';
            RETURN;
        END;

        /* محدودیت درخواست موبایل: یک درخواست در هر 60 ثانیه */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_UserOtpRateLimits WITH (UPDLOCK, HOLDLOCK)
            WHERE Mobile = @NormalizedMobile
              AND LastRequestAt > DATEADD(SECOND, -60, @Now)
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'لطفاً قبل از درخواست مجدد کد تأیید، کمی صبر کنید.';
            RETURN;
        END;

        /* محدودیت روزانه */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_UserOtpRateLimits WITH (UPDLOCK, HOLDLOCK)
            WHERE Mobile = @NormalizedMobile
              AND DailyDate = CONVERT(DATE, @Now)
              AND DailyCount >= 20
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'سقف درخواست روزانه کد تأیید برای این شماره تکمیل شده است.';
            RETURN;
        END;

        /* حداکثر 5 درخواست در 15 دقیقه */
        IF
        (
            SELECT COUNT_BIG(*)
            FROM dbo.App_UserOtpRequests WITH (UPDLOCK, HOLDLOCK)
            WHERE Mobile = @NormalizedMobile
              AND OtpPurpose = 1
              AND CreatedAt >= DATEADD(MINUTE, -15, @Now)
        ) >= 5
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'تعداد درخواست‌های کد تأیید بیش از حد مجاز است.';
            RETURN;
        END;

        /* حساب موقت قبلی یا حساب جدید */
        SELECT TOP (1) @UserId = UserId
        FROM dbo.App_Users WITH (UPDLOCK, HOLDLOCK)
        WHERE Mobile = @NormalizedMobile
          AND ISNULL(IsDeleted, 0) = 0
          AND NOT (IsActive = 1 AND PhoneVerified = 1)
        ORDER BY UserId DESC;

        IF @UserId IS NULL
        BEGIN
            INSERT INTO dbo.App_Users
            (
                Username, PasswordHash, Email, Mobile,
                FirstName, LastName, Gender,
                PhoneVerified, IsActive, IsDeleted, CreatedAt
            )
            VALUES
            (
                NULL, NULL, NULL, @NormalizedMobile,
                NULL, NULL, 0,
                0, 0, 0, GETDATE()
            );

            SET @UserId = CONVERT(BIGINT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            UPDATE dbo.App_Users
            SET IsActive = 0,
                PhoneVerified = 0,
                UpdatedAt = GETDATE()
            WHERE UserId = @UserId;

            DELETE FROM dbo.App_UserSignupPending
            WHERE UserId = @UserId;
        END;

        INSERT INTO dbo.App_UserSignupPending
        (
            UserId, OrgName, OrgType, GeoId
        )
        VALUES
        (
            @UserId, @NormalizedOrgName, @OrgType, @GeoId
        );

        /* کدهای قبلی مصرف‌نشده بی‌اعتبار شوند */
        UPDATE dbo.App_UserOtpRequests
        SET IsBlocked = 1
        WHERE UserId = @UserId
          AND OtpPurpose = 1
          AND IsUsed = 0
          AND IsBlocked = 0;

        SET @OtpExpiresAt = DATEADD(MINUTE, 2, @Now);

        INSERT INTO dbo.App_UserOtpRequests
        (
            UserId, Mobile, OtpCode, OtpPurpose,
            CreatedAt, ExpiresAt, AttemptCount,
            MaxAttempts, IsUsed, IsBlocked,
            RequestIp, UserAgent
        )
        VALUES
        (
            @UserId, @NormalizedMobile, @OtpCode, 1,
            @Now, @OtpExpiresAt, 0,
            5, 0, 0, @RequestIp, @UserAgent
        );

        SET @OtpRequestId = CONVERT(BIGINT, SCOPE_IDENTITY());

        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_UserOtpRateLimits WITH (UPDLOCK, HOLDLOCK)
            WHERE Mobile = @NormalizedMobile
        )
        BEGIN
            UPDATE dbo.App_UserOtpRateLimits
            SET RequestCount =
                    CASE
                        WHEN WindowStart <= DATEADD(MINUTE, -15, @Now)
                        THEN 1 ELSE RequestCount + 1
                    END,
                WindowStart =
                    CASE
                        WHEN WindowStart <= DATEADD(MINUTE, -15, @Now)
                        THEN @Now ELSE WindowStart
                    END,
                DailyDate =
                    CASE WHEN DailyDate <> CONVERT(DATE, @Now)
                         THEN CONVERT(DATE, @Now) ELSE DailyDate END,
                DailyCount =
                    CASE WHEN DailyDate <> CONVERT(DATE, @Now)
                         THEN 1 ELSE DailyCount + 1 END,
                LastRequestAt = @Now,
                BlockedUntil = NULL
            WHERE Mobile = @NormalizedMobile;
        END
        ELSE
        BEGIN
            INSERT INTO dbo.App_UserOtpRateLimits
            (
                Mobile, WindowStart, RequestCount,
                DailyDate, DailyCount, LastRequestAt
            )
            VALUES
            (
                @NormalizedMobile, @Now, 1,
                CONVERT(DATE, @Now), 1, @Now
            );
        END;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'درخواست ثبت‌نام ایجاد شد. کد تأیید تا دو دقیقه معتبر است.';
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UsersSignupVerifyOtp]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[App_UsersSignupVerifyOtp]
(
    @UserId         BIGINT,
    @OtpRequestId   BIGINT,
    @OtpCode        NVARCHAR(10),

    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT,
    @OrgId          BIGINT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(0) = SYSDATETIME();
    DECLARE @Mobile NVARCHAR(30);
    DECLARE @StoredCode NVARCHAR(30);
    DECLARE @ExpiresAt DATETIME2(0);
    DECLARE @AttemptCount INT;
    DECLARE @MaxAttempts INT;
    DECLARE @IsUsed BIT;
    DECLARE @IsBlocked BIT;
    DECLARE @OrgName NVARCHAR(200);
    DECLARE @OrgType INT;
    DECLARE @GeoId NVARCHAR(10);
    DECLARE @RoleId BIGINT = 1;
    DECLARE @PhoneVerified BIT;
    DECLARE @IsActive BIT;

    SELECT
        @ResultCode = 500,
        @ResultMessage = N'خطای پیش‌بینی‌نشده.',
        @OrgId = NULL;

    IF @UserId IS NULL OR @OtpRequestId IS NULL
       OR @OtpCode IS NULL OR LEN(@OtpCode) <> 4
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'اطلاعات تأیید کد معتبر نیست.';
        RETURN;
    END;

    /* کد ثابت فقط برای توسعه */
    IF @OtpCode <> N'1234'
    BEGIN
        /* این بررسی عمداً در ادامه هم انجام می‌شود؛
           شمارش تلاش‌ها باید در برابر درخواست‌های هم‌زمان محافظت شود. */
        SET @StoredCode = NULL;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @Mobile = O.Mobile,
            @StoredCode = O.OtpCode,
            @ExpiresAt = O.ExpiresAt,
            @AttemptCount = O.AttemptCount,
            @MaxAttempts = O.MaxAttempts,
            @IsUsed = O.IsUsed,
            @IsBlocked = O.IsBlocked
        FROM dbo.App_UserOtpRequests O WITH (UPDLOCK, HOLDLOCK)
        WHERE O.OtpRequestId = @OtpRequestId
          AND O.UserId = @UserId
          AND O.OtpPurpose = 1;

        IF @Mobile IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 404;
            SET @ResultMessage = N'درخواست کد تأیید پیدا نشد.';
            RETURN;
        END;

        IF @IsUsed = 1
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'این کد قبلاً استفاده شده است.';
            RETURN;
        END;

        IF @IsBlocked = 1
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'درخواست کد تأیید مسدود شده است.';
            RETURN;
        END;

        IF @ExpiresAt <= @Now
        BEGIN
            UPDATE dbo.App_UserOtpRequests
            SET IsBlocked = 1
            WHERE OtpRequestId = @OtpRequestId;

            COMMIT TRANSACTION;

            SET @ResultCode = 410;
            SET @ResultMessage = N'کد تأیید منقضی شده است؛ کد جدید درخواست کنید.';
            RETURN;
        END;

        IF @AttemptCount >= @MaxAttempts
        BEGIN
            UPDATE dbo.App_UserOtpRequests
            SET IsBlocked = 1
            WHERE OtpRequestId = @OtpRequestId;

            COMMIT TRANSACTION;

            SET @ResultCode = 429;
            SET @ResultMessage = N'تعداد تلاش‌های مجاز تمام شده است.';
            RETURN;
        END;

        /* در محیط فعلی کد معتبر ثابت 1234 است. */
        IF @OtpCode <> N'1234' OR @StoredCode <> N'1234'
        BEGIN
            UPDATE dbo.App_UserOtpRequests
            SET AttemptCount = AttemptCount + 1,
                IsBlocked =
                    CASE WHEN AttemptCount + 1 >= MaxAttempts
                         THEN 1 ELSE 0 END
            WHERE OtpRequestId = @OtpRequestId;

            COMMIT TRANSACTION;

            SET @ResultCode = 401;
            SET @ResultMessage = N'کد تأیید اشتباه است.';
            RETURN;
        END;

        SELECT
            @OrgName = OrgName,
            @OrgType = OrgType,
            @GeoId = GeoId
        FROM dbo.App_UserSignupPending WITH (UPDLOCK, HOLDLOCK)
        WHERE UserId = @UserId;

        IF @OrgName IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'اطلاعات موقت سازمان پیدا نشد؛ ثبت‌نام را دوباره شروع کنید.';
            RETURN;
        END;

        SELECT
            @PhoneVerified = PhoneVerified,
            @IsActive = IsActive
        FROM dbo.App_Users WITH (UPDLOCK, HOLDLOCK)
        WHERE UserId = @UserId
          AND Mobile = @Mobile
          AND ISNULL(IsDeleted, 0) = 0;

        IF @PhoneVerified IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 404;
            SET @ResultMessage = N'کاربر ثبت‌نام پیدا نشد.';
            RETURN;
        END;

        IF @PhoneVerified = 1 AND @IsActive = 1
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'این حساب قبلاً فعال شده است.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1 FROM dbo.App_Roles WHERE RoleId = @RoleId
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 500;
            SET @ResultMessage = N'نقش مدیر ساختمان با شناسه 1 تعریف نشده است.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.Organizations WITH (UPDLOCK, HOLDLOCK)
            WHERE LTRIM(RTRIM(OrgName)) = LTRIM(RTRIM(@OrgName))
              AND OrgType = @OrgType
              AND GeoId = @GeoId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'سازمانی با این نام، نوع و موقعیت جغرافیایی قبلاً ثبت شده است.';
            RETURN;
        END;

        /* مصرف اتمیک OTP */
        UPDATE dbo.App_UserOtpRequests
        SET IsUsed = 1,
            VerifiedAt = @Now
        WHERE OtpRequestId = @OtpRequestId
          AND UserId = @UserId
          AND IsUsed = 0
          AND IsBlocked = 0
          AND ExpiresAt > @Now;

        IF @@ROWCOUNT <> 1
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'درخواست تأیید قبلاً تغییر کرده است؛ دوباره تلاش کنید.';
            RETURN;
        END;

        INSERT INTO dbo.Organizations
        (
            OrgName, OrgType, GeoId, OrgDesc,
            IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            LTRIM(RTRIM(@OrgName)), @OrgType, @GeoId, NULL,
            1, 0, GETDATE(), NULL
        );

        SET @OrgId = CONVERT(BIGINT, SCOPE_IDENTITY());

        UPDATE dbo.App_Users
        SET OrgId = @OrgId,
            PhoneVerified = 1,
            IsActive = 1,
            IsDeleted = 0,
            UpdatedAt = GETDATE()
        WHERE UserId = @UserId;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_UserRoles
            WHERE UserId = @UserId
              AND RoleId = @RoleId
        )
        BEGIN
            INSERT INTO dbo.App_UserRoles
            (
                UserId, RoleId, AssignedAt, IsActive,
                IsDeleted, CreatedAt, Notes
            )
            VALUES
            (
                @UserId, @RoleId, GETDATE(), 1,
                0, GETDATE(), N'نقش مدیر ساختمان هنگام ثبت‌نام'
            );
        END
        ELSE
        BEGIN
            UPDATE dbo.App_UserRoles
            SET IsActive = 1,
                IsDeleted = 0,
                UpdatedAt = GETDATE(),
                Notes = N'نقش مدیر ساختمان هنگام ثبت‌نام'
            WHERE UserId = @UserId
              AND RoleId = @RoleId;
        END;

        DELETE FROM dbo.App_UserSignupPending
        WHERE UserId = @UserId;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'ثبت‌نام با موفقیت تکمیل شد.';

        SELECT
            U.UserId,
            U.Username,
            U.Mobile,
            U.FirstName,
            U.LastName,
            U.OrgId,
            O.OrgName,
            O.OrgType,
            O.GeoId,
            @RoleId AS RoleId
        FROM dbo.App_Users U
        INNER JOIN dbo.Organizations O ON O.OrgId = U.OrgId
        WHERE U.UserId = @UserId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
        SET @OrgId = NULL;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[App_UsersSignupWithPassword]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[App_UsersSignupWithPassword]
(
    @Username       NVARCHAR(100),
    @PasswordHash   NVARCHAR(500),
    @OrgName        NVARCHAR(200),
    @OrgType        INT,
    @GeoId          NVARCHAR(10),
    @RequestIp      NVARCHAR(50) = NULL,

    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT,
    @UserId         BIGINT OUTPUT,
    @OrgId          BIGINT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(0) = SYSDATETIME();
    DECLARE @NormalizedUsername NVARCHAR(100);
    DECLARE @NormalizedOrgName NVARCHAR(200);
    DECLARE @RateKey NVARCHAR(200);
    DECLARE @RoleId BIGINT = 1;
    DECLARE @RequestCount INT;
    DECLARE @WindowStart DATETIME2(0);
    DECLARE @LastRequestAt DATETIME2(0);

    SELECT
        @ResultCode = 500,
        @ResultMessage = N'خطای پیش‌بینی‌نشده.',
        @UserId = NULL,
        @OrgId = NULL;

    SET @NormalizedUsername = LTRIM(RTRIM(@Username));
    SET @NormalizedOrgName = LTRIM(RTRIM(@OrgName));
    SET @RateKey = N'USERNAME:' + LOWER(@NormalizedUsername);

    IF LEN(@NormalizedUsername) < 3
       OR LEN(@NormalizedUsername) > 100
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام کاربری باید حداقل 3 کاراکتر داشته باشد.';
        RETURN;
    END;

    IF NULLIF(@PasswordHash, N'') IS NULL
       OR LEN(@PasswordHash) < 20
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'هش رمز عبور معتبر نیست.';
        RETURN;
    END;

    IF NULLIF(@NormalizedOrgName, N'') IS NULL
       OR @OrgType IS NULL
       OR NULLIF(LTRIM(RTRIM(@GeoId)), N'') IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام سازمان، نوع سازمان و موقعیت جغرافیایی الزامی هستند.';
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM dbo.Base_Geo WHERE GeoId = @GeoId)
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'موقعیت جغرافیایی معتبر نیست.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1 FROM dbo.Base_LookupValues
        WHERE LookupValueId = @OrgType
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نوع سازمان معتبر نیست.';
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* ثبت یا بررسی محدودیت درخواست‌ها */
        SELECT
            @RequestCount = RequestCount,
            @WindowStart = WindowStart,
            @LastRequestAt = LastRequestAt
        FROM dbo.App_UserSignupRateLimits WITH (UPDLOCK, HOLDLOCK)
        WHERE RateKey = @RateKey;

        IF @LastRequestAt > DATEADD(SECOND, -10, @Now)
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'لطفاً پیش از تلاش مجدد کمی صبر کنید.';
            RETURN;
        END;

        IF @WindowStart IS NOT NULL
           AND @WindowStart > DATEADD(MINUTE, -15, @Now)
           AND @RequestCount >= 5
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 429;
            SET @ResultMessage = N'تعداد درخواست‌های ثبت‌نام برای این نام کاربری بیش از حد مجاز است.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_Users WITH (UPDLOCK, HOLDLOCK)
            WHERE Username = @NormalizedUsername
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'این نام کاربری قبلاً استفاده شده است.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.Organizations WITH (UPDLOCK, HOLDLOCK)
            WHERE LTRIM(RTRIM(OrgName)) = @NormalizedOrgName
              AND OrgType = @OrgType
              AND GeoId = @GeoId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 409;
            SET @ResultMessage = N'سازمانی با این نام، نوع و موقعیت جغرافیایی قبلاً ثبت شده است.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1 FROM dbo.App_Roles WHERE RoleId = @RoleId
        )
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 500;
            SET @ResultMessage = N'نقش مدیر ساختمان با شناسه 1 تعریف نشده است.';
            RETURN;
        END;

        /* ایجاد کاربر */
        INSERT INTO dbo.App_Users
        (
            Username, PasswordHash, Email, Mobile,
            FirstName, LastName, Gender,
            PhoneVerified, IsActive, IsDeleted,
            CreatedAt
        )
        VALUES
        (
            @NormalizedUsername, @PasswordHash, NULL, NULL,
            NULL, NULL, 0,
            0, 1, 0,
            GETDATE()
        );

        SET @UserId = CONVERT(BIGINT, SCOPE_IDENTITY());

        /* ایجاد سازمان */
        INSERT INTO dbo.Organizations
        (
            OrgName, OrgType, GeoId, OrgDesc,
            IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @NormalizedOrgName, @OrgType, @GeoId, NULL,
            1, 0, GETDATE(), NULL
        );

        SET @OrgId = CONVERT(BIGINT, SCOPE_IDENTITY());

        UPDATE dbo.App_Users
        SET OrgId = @OrgId
        WHERE UserId = @UserId;

        /* اختصاص نقش مدیر ساختمان */
        INSERT INTO dbo.App_UserRoles
        (
            UserId, RoleId, AssignedAt, IsActive,
            IsDeleted, CreatedAt, Notes
        )
        VALUES
        (
            @UserId, @RoleId, GETDATE(), 1,
            0, GETDATE(), N'نقش مدیر ساختمان هنگام ثبت‌نام'
        );

        /* ذخیره شمارنده محدودیت درخواست */
        IF @WindowStart IS NULL
        BEGIN
            INSERT INTO dbo.App_UserSignupRateLimits
            (
                RateKey, WindowStart, RequestCount, LastRequestAt
            )
            VALUES
            (
                @RateKey, @Now, 1, @Now
            );
        END
        ELSE
        BEGIN
            UPDATE dbo.App_UserSignupRateLimits
            SET RequestCount =
                    CASE
                        WHEN WindowStart <= DATEADD(MINUTE, -15, @Now)
                        THEN 1 ELSE RequestCount + 1
                    END,
                WindowStart =
                    CASE
                        WHEN WindowStart <= DATEADD(MINUTE, -15, @Now)
                        THEN @Now ELSE WindowStart
                    END,
                LastRequestAt = @Now
            WHERE RateKey = @RateKey;
        END;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'ثبت‌نام با موفقیت انجام شد.';

        SELECT
            U.UserId,
            U.Username,
            U.OrgId,
            O.OrgName,
            O.OrgType,
            O.GeoId,
            @RoleId AS RoleId
        FROM dbo.App_Users U
        INNER JOIN dbo.Organizations O ON O.OrgId = U.OrgId
        WHERE U.UserId = @UserId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
        SET @UserId = NULL;
        SET @OrgId = NULL;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Base_Geo_GetById]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Base_Geo_GetById]
(
    @GeoId          NVARCHAR(10),
    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده.';

    ---------------------------------------------------------
    -- اعتبارسنجی GeoId
    ---------------------------------------------------------
    IF NULLIF(LTRIM(RTRIM(@GeoId)), N'') IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'کد موقعیت جغرافیایی الزامی است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- بررسی وجود موقعیت جغرافیایی
    ---------------------------------------------------------
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_Geo
        WHERE GeoId = LTRIM(RTRIM(@GeoId))
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'موقعیت جغرافیایی موردنظر یافت نشد.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- دریافت اطلاعات موقعیت جغرافیایی
    ---------------------------------------------------------
    SELECT
        G.GeoId,
        G.GeoNameFa,
        G.GeoNameEn,
        G.GeoType,
        G.ParantId,
        G.PL1,
        G.PL2,
        G.PL3,
        G.PL4,
        G.PL5,
        G.GeoPathFa,
        G.GeoPathEn
    FROM dbo.Base_Geo AS G
    WHERE G.GeoId = LTRIM(RTRIM(@GeoId));

    SET @ResultCode = 200;
    SET @ResultMessage = N'اطلاعات موقعیت جغرافیایی با موفقیت دریافت شد.';
END;
GO
/****** Object:  StoredProcedure [dbo].[Base_GeoGetChildren]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Base_GeoGetChildren]
(
    @GeoType       TINYINT,
    @ParentGeoId   NVARCHAR(10) = NULL,
    @Search        NVARCHAR(300) = NULL,

    @ResultCode    INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @ResultCode = 500,
        @ResultMessage = N'خطای پیش‌بینی‌نشده.';

    BEGIN TRY

        ------------------------------------------------
        -- 1. بررسی نوع موقعیت جغرافیایی
        ------------------------------------------------
        IF @GeoType NOT BETWEEN 1 AND 5
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'نوع موقعیت جغرافیایی باید بین 1 تا 5 باشد.';
            RETURN;
        END;

        ------------------------------------------------
        -- 2. کشور والد ندارد
        ------------------------------------------------
        IF @GeoType = 1
        BEGIN
            IF @ParentGeoId IS NOT NULL
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'برای دریافت فهرست کشورها نباید والد ارسال شود.';
                RETURN;
            END;
        END
        ELSE
        BEGIN
            ------------------------------------------------
            -- 3. سطوح 2 تا 5 باید والد معتبر داشته باشند
            ------------------------------------------------
            IF @ParentGeoId IS NULL
               OR NOT EXISTS
               (
                   SELECT 1
                   FROM dbo.Base_Geo
                   WHERE GeoId = @ParentGeoId
                     AND GeoType = @GeoType - 1
               )
            BEGIN
                SET @ResultCode = 400;
                SET @ResultMessage =
                    N'موقعیت جغرافیایی والد معتبر نیست.';
                RETURN;
            END;
        END;

        ------------------------------------------------
        -- 4. دریافت موارد سطح انتخاب‌شده
        ------------------------------------------------
        SELECT
            G.GeoId,
            G.GeoNameFa,
            G.GeoNameEn,
            G.GeoType,
            G.ParantId,
            G.PL1,
            G.PL2,
            G.PL3,
            G.PL4,
            G.PL5,
            G.GeoPathFa,
            G.GeoPathEn
        FROM dbo.Base_Geo AS G
        WHERE G.GeoType = @GeoType
          AND
          (
              @GeoType = 1
              OR G.ParantId = @ParentGeoId
          )
          AND
          (
              NULLIF(LTRIM(RTRIM(@Search)), N'') IS NULL
              OR G.GeoNameFa LIKE N'%' + @Search + N'%'
              OR G.GeoNameEn LIKE N'%' + @Search + N'%'
              OR G.GeoId LIKE N'%' + @Search + N'%'
          )
        ORDER BY G.GeoNameFa;

        SET @ResultCode = 200;
        SET @ResultMessage = N'اطلاعات با موفقیت دریافت شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = 500;
        SET @ResultMessage = LEFT(ERROR_MESSAGE(), 500);

    END CATCH;
END;
GO
