/****** Object:  StoredProcedure [dbo].[Base_LookupValues_GetById]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Base_LookupValues_GetById]
(
    @LookupValueId INT,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @LookupValueId IS NULL OR @LookupValueId <= 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه مقدار پایه معتبر نیست.';
        RETURN;
    END;

    SELECT *
    FROM dbo.Base_LookupValues
    WHERE LookupValueId = @LookupValueId;

    IF @@ROWCOUNT = 0
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'مقدار پایه موردنظر یافت نشد.';
        RETURN;
    END;

    SET @ResultCode = 200;
    SET @ResultMessage = N'مقدار پایه با موفقیت دریافت شد.';
END;
GO
/****** Object:  StoredProcedure [dbo].[Booking_ClassSeries_Delete]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   PROCEDURE [dbo].[Booking_ClassSeries_Delete]
    @ClassSeriesId BIGINT,
    @UserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Booking_ClassSessions
        WHERE ClassSeriesId = @ClassSeriesId
          AND ISNULL(IsDeleted, 0) = 0
    )
        THROW 50004, N'برای این سری کلاس جلسه ثبت شده است؛ حذف نرم انجام نشد.', 1;

    UPDATE dbo.Booking_ClassSeries
    SET IsDeleted = 1,
        IsActive = 0,
        UpdatedAt = SYSDATETIME(),
        UserUpdater = @UserId
    WHERE ClassSeriesId = @ClassSeriesId
      AND ISNULL(IsDeleted, 0) = 0;

    IF @@ROWCOUNT = 0
        THROW 50005, N'سری کلاس یافت نشد یا قبلاً حذف شده است.', 1;
END;
GO
/****** Object:  StoredProcedure [dbo].[Booking_ClassSeries_GetActiveList]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Booking_ClassSeries_GetActiveList]
    @OrgId BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT *
    FROM dbo.Booking_ClassSeries
    WHERE IsDeleted = 0
      AND IsActive = 1
      AND (@OrgId IS NULL OR OrgId = @OrgId)
    ORDER BY ClassName;
