/* =========================================================
   2. Booking_ClassSeries
   ========================================================= */

CREATE PROCEDURE [dbo].[Booking_ClassSeries_Save]
    @ClassSeriesId BIGINT = NULL,
    @OrgId BIGINT,
    @ClassName NVARCHAR(200),
    @ClassNameEn NVARCHAR(200) = NULL,
    @ClassDescription NVARCHAR(1000) = NULL,
    @ClassDescriptionEn NVARCHAR(1000) = NULL,
    @CoachEmployeeId BIGINT = NULL,
    @ExternalCoachName NVARCHAR(200) = NULL,
    @ExternalCoachMobile NVARCHAR(20) = NULL,
    @Capacity INT,
    @IsRegistrationOpen BIT = 1,
    @RegistrationStartAt DATETIME2(0) = NULL,
    @RegistrationEndAt DATETIME2(0) = NULL,
    @IsActive BIT = 1,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Capacity <= 0
        THROW 50010, N'ظرفیت کلاس باید بیشتر از صفر باشد.', 1;

    IF @RegistrationStartAt IS NOT NULL
       AND @RegistrationEndAt IS NOT NULL
       AND @RegistrationEndAt < @RegistrationStartAt
        THROW 50011, N'پایان ثبت‌نام نمی‌تواند قبل از شروع آن باشد.', 1;

    IF @ClassSeriesId IS NULL
    BEGIN
        INSERT INTO dbo.Booking_ClassSeries
        (
            OrgId, ClassName, ClassNameEn,
            ClassDescription, ClassDescriptionEn,
            CoachEmployeeId, ExternalCoachName, ExternalCoachMobile,
            Capacity, IsRegistrationOpen,
            RegistrationStartAt, RegistrationEndAt,
            IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @ClassName, @ClassNameEn,
            @ClassDescription, @ClassDescriptionEn,
            @CoachEmployeeId, @ExternalCoachName, @ExternalCoachMobile,
            @Capacity, @IsRegistrationOpen,
            @RegistrationStartAt, @RegistrationEndAt,
            @IsActive, 0, GETDATE(), @UserId
        );

        SET @ClassSeriesId = CONVERT(BIGINT, SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        UPDATE dbo.Booking_ClassSeries
        SET OrgId = @OrgId,
            ClassName = @ClassName,
            ClassNameEn = @ClassNameEn,
            ClassDescription = @ClassDescription,
            ClassDescriptionEn = @ClassDescriptionEn,
            CoachEmployeeId = @CoachEmployeeId,
            ExternalCoachName = @ExternalCoachName,
            ExternalCoachMobile = @ExternalCoachMobile,
            Capacity = @Capacity,
            IsRegistrationOpen = @IsRegistrationOpen,
            RegistrationStartAt = @RegistrationStartAt,
            RegistrationEndAt = @RegistrationEndAt,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE ClassSeriesId = @ClassSeriesId
          AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 50012, N'سری کلاس یافت نشد یا حذف شده است.', 1;
    END;

    EXEC dbo.Booking_ClassSeries_GetById @ClassSeriesId;
END;
GO
