/* =========================================================
   3. Booking_ClassSessions
   توجه: اسکیمای فعلی SessionTitleEn دارد، اما
   SessionTitle فارسی در دیتابیس nullable است.
   ========================================================= */

CREATE PROCEDURE [dbo].[Booking_ClassSession_Save]
    @ClassSessionId BIGINT = NULL,
    @ClassSeriesId BIGINT,
    @BookingId BIGINT,
    @SessionTitle NVARCHAR(200) = NULL,
    @SessionTitleEn NVARCHAR(200) = NULL,
    @SessionStatus TINYINT = 1,
    @IsActive BIT = 1,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ClassSessionId IS NULL
    BEGIN
        INSERT INTO dbo.Booking_ClassSessions
        (
            ClassSeriesId, BookingId, SessionTitle, SessionTitleEn,
            SessionStatus, IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @ClassSeriesId, @BookingId, @SessionTitle, @SessionTitleEn,
            @SessionStatus, @IsActive, 0, GETDATE(), @UserId
        );

        SET @ClassSessionId = CONVERT(BIGINT, SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        UPDATE dbo.Booking_ClassSessions
        SET ClassSeriesId = @ClassSeriesId,
            BookingId = @BookingId,
            SessionTitle = @SessionTitle,
            SessionTitleEn = @SessionTitleEn,
            SessionStatus = @SessionStatus,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE ClassSessionId = @ClassSessionId
          AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 50020, N'جلسه کلاس یافت نشد یا حذف شده است.', 1;
    END;

    EXEC dbo.Booking_ClassSession_GetById @ClassSessionId;
END;
GO
