CREATE   PROCEDURE [dbo].[Booking_ClassSessions_Delete]
    @ClassSessionId BIGINT,
    @UserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Enrollment_Class
        WHERE ClassSessionId = @ClassSessionId
          AND EnrollmentStatus NOT IN (4, 5)
    )
        THROW 50105, N'برای این جلسه ثبت‌نام فعال وجود دارد؛ حذف امکان‌پذیر نیست.', 1;

    UPDATE dbo.Booking_ClassSessions
    SET IsDeleted = 1,
        IsActive = 0,
        UpdatedAt = SYSDATETIME(),
        UserUpdater = @UserId
    WHERE ClassSessionId = @ClassSessionId
      AND ISNULL(IsDeleted, 0) = 0;

    IF @@ROWCOUNT = 0
        THROW 50106, N'جلسه یافت نشد یا قبلاً حذف شده است.', 1;
END;
GO
