CREATE   PROCEDURE [dbo].[Booking_ClassSessions_GetById]
    @ClassSessionId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        S.*,
        C.ClassName,
        C.ClassNameEn
    FROM dbo.Booking_ClassSessions AS S
    INNER JOIN dbo.Booking_ClassSeries AS C
        ON C.ClassSeriesId = S.ClassSeriesId
    WHERE S.ClassSessionId = @ClassSessionId
      AND ISNULL(S.IsDeleted, 0) = 0
      AND ISNULL(C.IsDeleted, 0) = 0;
END;
