    @OrgId BIGINT = NULL,
    @BuildingId BIGINT = NULL,
    @DefaultSpaceId BIGINT = NULL,
    @OnlyAvailable BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT *
    FROM dbo.Booking_Equipment
    WHERE IsDeleted = 0
      AND (@OrgId IS NULL OR OrgId = @OrgId)
      AND (@BuildingId IS NULL OR BuildingId = @BuildingId)
      AND (@DefaultSpaceId IS NULL OR DefaultSpaceId = @DefaultSpaceId)
      AND (@OnlyAvailable = 0 OR (IsActive = 1 AND AvailableQuantity > 0))
    ORDER BY EquipmentName;
END;
