CREATE   PROCEDURE [dbo].[Booking_Equipment_Save]
    @EquipmentId BIGINT = NULL,
    @OrgId BIGINT,
    @BuildingId BIGINT,
    @DefaultSpaceId BIGINT = NULL,
    @EquipmentName NVARCHAR(200),
    @EquipmentNameEn NVARCHAR(200) = NULL,
    @EquipmentCode NVARCHAR(100) = NULL,
    @EquipmentDescription NVARCHAR(2000) = NULL,
    @EquipmentDescriptionEn NVARCHAR(2000) = NULL,
    @Quantity INT = 1,
    @AvailableQuantity INT = 1,
    @OperatorEmployeeId BIGINT = NULL,
    @EquipmentStatus TINYINT = 1,
    @IsActive BIT = 1,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Quantity < 0 OR @AvailableQuantity < 0
       OR @AvailableQuantity > @Quantity
        THROW 51310, N'موجودی تجهیزات نامعتبر است.', 1;

    IF @EquipmentId IS NULL
    BEGIN
        INSERT INTO dbo.Booking_Equipment
        (
            OrgId, BuildingId, DefaultSpaceId,
            EquipmentName, EquipmentNameEn, EquipmentCode,
            EquipmentDescription, EquipmentDescriptionEn,
            Quantity, AvailableQuantity, OperatorEmployeeId,
            EquipmentStatus, IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @BuildingId, @DefaultSpaceId,
            @EquipmentName, @EquipmentNameEn, @EquipmentCode,
            @EquipmentDescription, @EquipmentDescriptionEn,
            @Quantity, @AvailableQuantity, @OperatorEmployeeId,
            @EquipmentStatus, @IsActive, 0, GETDATE(), @UserId
        );

        SET @EquipmentId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Booking_Equipment
        SET OrgId = @OrgId,
            BuildingId = @BuildingId,
            DefaultSpaceId = @DefaultSpaceId,
            EquipmentName = @EquipmentName,
            EquipmentNameEn = @EquipmentNameEn,
            EquipmentCode = @EquipmentCode,
            EquipmentDescription = @EquipmentDescription,
            EquipmentDescriptionEn = @EquipmentDescriptionEn,
            Quantity = @Quantity,
            AvailableQuantity = @AvailableQuantity,
            OperatorEmployeeId = @OperatorEmployeeId,
            EquipmentStatus = @EquipmentStatus,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE EquipmentId = @EquipmentId AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 51311, N'تجهیزات پیدا نشد.', 1;
    END;

    EXEC dbo.Booking_Equipment_GetById @EquipmentId;
END;
GO
