CREATE   PROCEDURE [dbo].[Booking_HallRentalDetails_GetList]
    @RenterParticipantId BIGINT = NULL,
    @OrgId BIGINT = NULL,
    @From DATETIME2(0) = NULL,
    @To DATETIME2(0) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT d.*, b.OrgId, b.BuildingId, b.SpaceId,
           b.StartAt, b.EndAt, b.BookingStatus
    FROM dbo.Booking_HallRentalDetails d
    INNER JOIN dbo.Booking_Space b ON b.BookingId = d.BookingId
    WHERE b.IsDeleted = 0
      AND (@RenterParticipantId IS NULL OR d.RenterParticipantId = @RenterParticipantId)
      AND (@OrgId IS NULL OR b.OrgId = @OrgId)
      AND (@From IS NULL OR b.StartAt >= @From)
      AND (@To IS NULL OR b.StartAt <= @To)
    ORDER BY b.StartAt DESC;
END;
GO
