CREATE   PROCEDURE [dbo].[Booking_HallRentalDetails_Save]
    @BookingId BIGINT,
    @RenterParticipantId BIGINT,
    @RentalPurpose NVARCHAR(1000) = NULL,
    @RentalPurposeEn NVARCHAR(1000) = NULL,
    @ExpectedAttendeeCount INT = NULL,
    @SetupNotes NVARCHAR(2000) = NULL,
    @SetupNotesEn NVARCHAR(2000) = NULL,
    @AgreedAmount DECIMAL(18,2) = NULL,
    @DepositAmount DECIMAL(18,2) = 0,
    @FinalAmount DECIMAL(18,2) = NULL,
    @RentalTerms NVARCHAR(4000) = NULL,
    @RentalTermsEn NVARCHAR(4000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ExpectedAttendeeCount < 0 OR @DepositAmount < 0
       OR @AgreedAmount < 0 OR @FinalAmount < 0
        THROW 51001, N'تعداد افراد یا مبلغ واردشده نامعتبر است.', 1;

    IF EXISTS (
        SELECT 1 FROM dbo.Booking_HallRentalDetails
        WHERE BookingId = @BookingId
    )
    BEGIN
        UPDATE dbo.Booking_HallRentalDetails
        SET RenterParticipantId = @RenterParticipantId,
            RentalPurpose = @RentalPurpose,
            RentalPurposeEn = @RentalPurposeEn,
            ExpectedAttendeeCount = @ExpectedAttendeeCount,
            SetupNotes = @SetupNotes,
            SetupNotesEn = @SetupNotesEn,
            AgreedAmount = @AgreedAmount,
            DepositAmount = @DepositAmount,
            FinalAmount = @FinalAmount,
            RentalTerms = @RentalTerms,
            RentalTermsEn = @RentalTermsEn,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE BookingId = @BookingId;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.Booking_HallRentalDetails
        (
            BookingId, RenterParticipantId,
            RentalPurpose, RentalPurposeEn,
            ExpectedAttendeeCount, SetupNotes, SetupNotesEn,
            AgreedAmount, DepositAmount, FinalAmount,
            RentalTerms, RentalTermsEn, CreatedAt, UserCreater
        )
        VALUES
        (
            @BookingId, @RenterParticipantId,
            @RentalPurpose, @RentalPurposeEn,
            @ExpectedAttendeeCount, @SetupNotes, @SetupNotesEn,
            @AgreedAmount, @DepositAmount, @FinalAmount,
            @RentalTerms, @RentalTermsEn, GETDATE(), @UserId
        );
    END;

    EXEC dbo.Booking_HallRentalDetails_GetById @BookingId;
END;
GO
