CREATE PROCEDURE [dbo].[Booking_Participant_Save]
    @ParticipantId BIGINT = NULL,
    @UserId BIGINT = NULL,
    @FullName NVARCHAR(200),
    @MobileNumber NVARCHAR(20) = NULL,
    @Email NVARCHAR(254) = NULL,
    @ParticipantType TINYINT,
    @IsActive BIT = 1,
    @AuditUserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ParticipantId IS NULL
    BEGIN
        INSERT INTO dbo.Booking_Participants
        (
            UserId, FullName, MobileNumber, Email,
            ParticipantType, IsActive, IsDeleted,
            CreatedAt, UserCreater
        )
        VALUES
        (
            @UserId, @FullName, @MobileNumber, @Email,
            @ParticipantType, @IsActive, 0,
            GETDATE(), @AuditUserId
        );

        SET @ParticipantId = CONVERT(BIGINT, SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        UPDATE dbo.Booking_Participants
        SET UserId = @UserId,
            FullName = @FullName,
            MobileNumber = @MobileNumber,
            Email = @Email,
            ParticipantType = @ParticipantType,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @AuditUserId
        WHERE ParticipantId = @ParticipantId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @@ROWCOUNT = 0
            THROW 50030, N'شرکت‌کننده یافت نشد یا حذف شده است.', 1;
    END;

    EXEC dbo.Booking_Participant_GetById @ParticipantId;
END;
