CREATE   PROCEDURE [dbo].[Booking_Participants_Delete]
    @ParticipantId BIGINT,
    @OperatorUserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Enrollment_Class
        WHERE ParticipantId = @ParticipantId
    )
        THROW 50203, N'برای این شرکت‌کننده سابقه ثبت‌نام وجود دارد؛ حذف فیزیکی مجاز نیست.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Booking_HallRentalDetails
        WHERE RenterParticipantId = @ParticipantId
    )
        THROW 50204, N'این شرکت‌کننده در اطلاعات اجاره سالن استفاده شده است.', 1;

    UPDATE dbo.Booking_Participants
    SET IsDeleted = 1,
        IsActive = 0,
        UpdatedAt = SYSDATETIME(),
        UserUpdater = @OperatorUserId
    WHERE ParticipantId = @ParticipantId
      AND ISNULL(IsDeleted, 0) = 0;

    IF @@ROWCOUNT = 0
        THROW 50205, N'شرکت‌کننده یافت نشد یا قبلاً حذف شده است.', 1;
END;
GO
