CREATE   PROCEDURE [dbo].[Booking_ReservationEquipment_Delete]
    @ReservationEquipmentId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    DECLARE @EquipmentId BIGINT, @Quantity INT;

    SELECT @EquipmentId = EquipmentId, @Quantity = Quantity
    FROM dbo.Booking_ReservationEquipment WITH (UPDLOCK, HOLDLOCK)
    WHERE ReservationEquipmentId = @ReservationEquipmentId;

    IF @EquipmentId IS NULL
    BEGIN
        ROLLBACK;
        THROW 51407, N'تخصیص تجهیزات پیدا نشد.', 1;
    END;

    UPDATE dbo.Booking_Equipment
    SET AvailableQuantity = AvailableQuantity + @Quantity
    WHERE EquipmentId = @EquipmentId;

    DELETE FROM dbo.Booking_ReservationEquipment
    WHERE ReservationEquipmentId = @ReservationEquipmentId;

    COMMIT;
END;
GO
