CREATE   PROCEDURE [dbo].[Booking_ReservationEquipment_Save]
    @ReservationEquipmentId BIGINT = NULL,
    @BookingId BIGINT,
    @EquipmentId BIGINT,
    @Quantity INT,
    @Notes NVARCHAR(1000) = NULL,
    @NotesEn NVARCHAR(1000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Quantity <= 0
        THROW 51401, N'تعداد تجهیزات باید بیشتر از صفر باشد.', 1;

    BEGIN TRANSACTION;

    DECLARE @OldEquipmentId BIGINT = NULL, @OldQuantity INT = 0;

    IF @ReservationEquipmentId IS NOT NULL
    BEGIN
        SELECT @OldEquipmentId = EquipmentId,
               @OldQuantity = Quantity
        FROM dbo.Booking_ReservationEquipment WITH (UPDLOCK, HOLDLOCK)
        WHERE ReservationEquipmentId = @ReservationEquipmentId;

        IF @OldEquipmentId IS NULL
        BEGIN
            ROLLBACK;
            THROW 51402, N'تخصیص تجهیزات پیدا نشد.', 1;
        END;
    END;

    IF @ReservationEquipmentId IS NULL
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM dbo.Booking_ReservationEquipment WITH (UPDLOCK, HOLDLOCK)
            WHERE BookingId = @BookingId AND EquipmentId = @EquipmentId
        )
        BEGIN
            ROLLBACK;
            THROW 51403, N'این تجهیز قبلاً به رزرو تخصیص داده شده است.', 1;
        END;

        UPDATE dbo.Booking_Equipment
        SET AvailableQuantity = AvailableQuantity - @Quantity
        WHERE EquipmentId = @EquipmentId
          AND IsDeleted = 0
          AND IsActive = 1
          AND AvailableQuantity >= @Quantity;

        IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK;
            THROW 51404, N'موجودی تجهیز کافی نیست یا تجهیز فعال نیست.', 1;
        END;

        INSERT INTO dbo.Booking_ReservationEquipment
        (
            BookingId, EquipmentId, Quantity, Notes, NotesEn,
            CreatedAt, UserCreater
        )
        VALUES
        (
            @BookingId, @EquipmentId, @Quantity, @Notes, @NotesEn,
            GETDATE(), @UserId
        );

        SET @ReservationEquipmentId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        IF @OldEquipmentId = @EquipmentId
        BEGIN
            UPDATE dbo.Booking_Equipment
            SET AvailableQuantity = AvailableQuantity + @OldQuantity - @Quantity
            WHERE EquipmentId = @EquipmentId
              AND AvailableQuantity + @OldQuantity >= @Quantity;

            IF @@ROWCOUNT = 0
            BEGIN
                ROLLBACK;
                THROW 51405, N'موجودی تجهیز برای این تغییر کافی نیست.', 1;
            END;
        END
        ELSE
        BEGIN
            UPDATE dbo.Booking_Equipment
            SET AvailableQuantity = AvailableQuantity + @OldQuantity
            WHERE EquipmentId = @OldEquipmentId;

            UPDATE dbo.Booking_Equipment
            SET AvailableQuantity = AvailableQuantity - @Quantity
            WHERE EquipmentId = @EquipmentId
              AND IsDeleted = 0
              AND IsActive = 1
              AND AvailableQuantity >= @Quantity;

            IF @@ROWCOUNT = 0
            BEGIN
                ROLLBACK;
                THROW 51406, N'موجودی تجهیز جدید کافی نیست.', 1;
            END;
        END;

        UPDATE dbo.Booking_ReservationEquipment
        SET BookingId = @BookingId,
            EquipmentId = @EquipmentId,
            Quantity = @Quantity,
            Notes = @Notes,
            NotesEn = @NotesEn,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE ReservationEquipmentId = @ReservationEquipmentId;
    END;

    COMMIT;

    EXEC dbo.Booking_ReservationEquipment_GetById @ReservationEquipmentId;
END;
GO
/****** Object:  StoredProcedure [dbo].[Booking_Space_Approve]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[Booking_Space_Approve]
    @BookingId BIGINT,
    @ApprovedStatus TINYINT,
    @PendingStatus TINYINT,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    DECLARE
        @SpaceId BIGINT,
        @StartAt DATETIME2(0),
        @EndAt DATETIME2(0),
        @CurrentStatus TINYINT;

    SELECT
        @SpaceId = SpaceId,
        @StartAt = StartAt,
        @EndAt = EndAt,
        @CurrentStatus = BookingStatus
    FROM dbo.Booking_Space WITH (UPDLOCK, HOLDLOCK)
    WHERE BookingId = @BookingId
      AND ISNULL(IsDeleted, 0) = 0;

    IF @SpaceId IS NULL
    BEGIN
        ROLLBACK;
        THROW 51701, N'رزرو موردنظر پیدا نشد.', 1;
    END;

    IF @CurrentStatus <> @PendingStatus
    BEGIN
        ROLLBACK;
        THROW 51702, N'وضعیت رزرو برای تأیید معتبر نیست.', 1;
    END;

    IF @StartAt IS NULL OR @EndAt IS NULL OR @EndAt <= @StartAt
    BEGIN
        ROLLBACK;
        THROW 51703, N'بازه زمانی رزرو معتبر نیست.', 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Booking_Space AS b WITH (UPDLOCK, HOLDLOCK)
        WHERE b.SpaceId = @SpaceId
          AND b.BookingId <> @BookingId
          AND ISNULL(b.IsDeleted, 0) = 0
          AND b.BookingStatus = @ApprovedStatus
          AND b.StartAt < @EndAt
          AND b.EndAt > @StartAt
    )
    BEGIN
        ROLLBACK;
        THROW 51704, N'در این بازه زمانی رزرو تأییدشده دیگری وجود دارد.', 1;
    END;

    UPDATE dbo.Booking_Space
    SET BookingStatus = @ApprovedStatus,
        UpdatedAt = GETDATE(),
        UserUpdater = @UserId
    WHERE BookingId = @BookingId;

    COMMIT;

    EXEC dbo.Booking_Space_GetById @BookingId;
END;
GO
