/****** Object:  StoredProcedure [dbo].[Booking_Space_CheckConflict]    Script Date: 10/29/2026 8:34:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Booking_Space_CheckConflict]
    @SpaceId BIGINT,
    @StartAt DATETIME2(0),
    @EndAt DATETIME2(0),
    @ExcludeBookingId BIGINT = NULL,
    @BlockingStatuses NVARCHAR(100) = N'1,2,3'
AS
BEGIN
    SET NOCOUNT ON;

    IF @EndAt <= @StartAt
        THROW 51601, N'زمان پایان باید بعد از شروع باشد.', 1;

    SELECT CAST(
        CASE WHEN EXISTS
        (
            SELECT 1
            FROM dbo.Booking_Space b
            WHERE b.SpaceId = @SpaceId
              AND b.IsDeleted = 0
              AND (@ExcludeBookingId IS NULL OR b.BookingId <> @ExcludeBookingId)
              AND b.StartAt < @EndAt
              AND b.EndAt > @StartAt
              AND EXISTS
              (
                  SELECT 1
                  FROM STRING_SPLIT(@BlockingStatuses, ',') x
                  WHERE TRY_CONVERT(TINYINT, LTRIM(RTRIM(x.value))) = b.BookingStatus
              )
        )
        THEN 1 ELSE 0 END
    AS BIT) AS HasConflict;
END;
GO
