CREATE   PROCEDURE [dbo].[Booking_Space_GetList]
    @SpaceId BIGINT = NULL,
    @OrgId BIGINT = NULL,
    @StartFrom DATETIME2(0) = NULL,
    @StartTo DATETIME2(0) = NULL,
    @BookingStatus TINYINT = NULL,
    @BookingType TINYINT = NULL,
    @OnlyActive BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        b.*,
        s.SpaceName,
        s.SpaceNameEn,
        s.SpaceDesc,
        s.SpaceDescEn
    FROM dbo.Booking_Space AS b
    INNER JOIN dbo.Spaces AS s
        ON s.SpaceId = b.SpaceId
    WHERE ISNULL(b.IsDeleted, 0) = 0
      AND (@SpaceId IS NULL OR b.SpaceId = @SpaceId)
      AND (@OrgId IS NULL OR s.OrgId = @OrgId)
      AND (@StartFrom IS NULL OR b.StartAt >= @StartFrom)
      AND (@StartTo IS NULL OR b.StartAt <= @StartTo)
      AND (@BookingStatus IS NULL OR b.BookingStatus = @BookingStatus)
      AND (@BookingType IS NULL OR b.BookingType = @BookingType)
      AND (
          @OnlyActive = 0
          OR b.BookingStatus IN (1, 2, 3)
      )
    ORDER BY b.StartAt DESC;
END;
GO
