CREATE PROCEDURE [dbo].[Booking_Space_Save]
    @BookingId BIGINT = NULL,
    @OrgId BIGINT,
    @BuildingId BIGINT,
    @SpaceId BIGINT,
    @BookingType TINYINT,
    @StartAt DATETIME2(0),
    @EndAt DATETIME2(0),
    @BookingStatus TINYINT = 1,
    @RequestedByParticipantId BIGINT = NULL,
    @ApprovedByUserId BIGINT = NULL,
    @ApprovedAt DATETIME2(0) = NULL,
    @BookingTitle NVARCHAR(400) = NULL,
    @BookingDescription NVARCHAR(2000) = NULL,
    @BookingDescriptionEn NVARCHAR(2000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @EndAt <= @StartAt
        THROW 50001, N'زمان پایان باید بعد از زمان شروع باشد.', 1;

    IF @BookingId IS NULL
    BEGIN
        INSERT INTO dbo.Booking_Space
        (
            OrgId, BuildingId, SpaceId, BookingType,
            StartAt, EndAt, BookingStatus,
            RequestedByParticipantId, ApprovedByUserId, ApprovedAt,
            BookingTitle, BookingDescription, BookingDescriptionEn,
            IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @BuildingId, @SpaceId, @BookingType,
            @StartAt, @EndAt, @BookingStatus,
            @RequestedByParticipantId, @ApprovedByUserId, @ApprovedAt,
            @BookingTitle, @BookingDescription, @BookingDescriptionEn,
            0, GETDATE(), @UserId
        );

        SET @BookingId = CONVERT(BIGINT, SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        UPDATE dbo.Booking_Space
        SET OrgId = @OrgId,
            BuildingId = @BuildingId,
            SpaceId = @SpaceId,
            BookingType = @BookingType,
            StartAt = @StartAt,
            EndAt = @EndAt,
            BookingStatus = @BookingStatus,
            RequestedByParticipantId = @RequestedByParticipantId,
            ApprovedByUserId = @ApprovedByUserId,
            ApprovedAt = @ApprovedAt,
            BookingTitle = @BookingTitle,
            BookingDescription = @BookingDescription,
            BookingDescriptionEn = @BookingDescriptionEn,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE BookingId = @BookingId
          AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 50002, N'رزرو موردنظر یافت نشد یا حذف شده است.', 1;
    END;

    EXEC dbo.Booking_Space_GetById @BookingId = @BookingId;
END;
GO
