SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Buildings_BulkSave]
(
    @Buildings       dbo.BuildingBulkType READONLY,
    @CurrentUserId   BIGINT,
    @ResultCode      INT OUTPUT,
    @ResultMessage   NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده در عملیات ساختمان‌ها.';

    ---------------------------------------------------------
    -- 1. بررسی ورودی
    ---------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM @Buildings)
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'حداقل یک ساختمان باید ارسال شود.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Buildings
        WHERE NULLIF(LTRIM(RTRIM(BuildingName)), N'') IS NULL
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام تمام ساختمان‌ها الزامی است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 2. جلوگیری از ارسال شناسه تکراری در یک درخواست
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT BuildingId
        FROM @Buildings
        WHERE BuildingId IS NOT NULL
          AND BuildingId > 0
        GROUP BY BuildingId
        HAVING COUNT(*) > 1
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه یک ساختمان بیش از یک بار ارسال شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 3. بررسی سازمان‌ها
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Buildings B
        WHERE B.OrgId IS NOT NULL
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.Organizations O
              WHERE O.OrgId = B.OrgId
                AND ISNULL(O.IsDeleted, 0) = 0
          )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'یکی از سازمان‌های انتخاب‌شده وجود ندارد یا حذف شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 4. بررسی وجود ساختمان‌هایی که قرار است ویرایش شوند
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Buildings B
        WHERE ISNULL(B.BuildingId, 0) > 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.Buildings T
              WHERE T.BuildingId = B.BuildingId
                AND ISNULL(T.IsDeleted, 0) = 0
          )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'یکی از ساختمان‌های ارسالی برای ویرایش یافت نشد یا حذف شده است.';
        RETURN;
    END;

    -----------------------------------------------------------
    ---- 5. بررسی نام تکراری در خود درخواست
    ---- نام در محدوده هر سازمان باید یکتا باشد.
    ---- OrgId برابر NULL نیز به عنوان یک محدوده جداگانه بررسی می‌شود.
    -----------------------------------------------------------
    --IF EXISTS
    --(
    --    SELECT 1
    --    FROM @Buildings A
    --    INNER JOIN @Buildings B
    --        ON LTRIM(RTRIM(A.BuildingName))
    --         = LTRIM(RTRIM(B.BuildingName))
    --       AND
    --       (
    --           A.OrgId = B.OrgId
    --           OR (A.OrgId IS NULL AND B.OrgId IS NULL)
    --       )
    --       AND
    --       (
    --           ISNULL(A.BuildingId, 0) = 0
    --           OR ISNULL(B.BuildingId, 0) = 0
    --           OR A.BuildingId <> B.BuildingId
    --       )
    --)
    --BEGIN
    --    SET @ResultCode = 409;
    --    SET @ResultMessage = N'در اطلاعات ارسالی، نام تکراری برای یک سازمان وجود دارد.';
    --    RETURN;
    --END;

    ---------------------------------------------------------
    -- 6. بررسی نام تکراری در اطلاعات فعلی جدول
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Buildings B
        INNER JOIN dbo.Buildings T
            ON LTRIM(RTRIM(T.BuildingName))
             = LTRIM(RTRIM(B.BuildingName))
           AND
           (
               T.OrgId = B.OrgId
               OR (T.OrgId IS NULL AND B.OrgId IS NULL)
           )
           AND ISNULL(T.IsDeleted, 0) = 0
           AND
           (
               ISNULL(B.BuildingId, 0) = 0
               OR T.BuildingId <> B.BuildingId
           )
    )
    BEGIN
        SET @ResultCode = 409;
        SET @ResultMessage = N'ساختمانی با این نام قبلاً در همین سازمان ثبت شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 7. انجام ثبت و ویرایش در یک تراکنش
    ---------------------------------------------------------
    BEGIN TRY
        BEGIN TRANSACTION;

        -----------------------------------------------------
        -- 7.1 ویرایش ساختمان‌های موجود
        -----------------------------------------------------
        UPDATE T
        SET
            T.BuildingName =
                LTRIM(RTRIM(B.BuildingName)),

            T.BuildingAddress =
                B.BuildingAddress,

            T.BuildingDescription =
                B.BuildingDescription,

            T.IsActive =
                ISNULL(B.IsActive, T.IsActive),

            T.OrgId =
                B.OrgId,

            T.UpdatedAt =
                GETDATE(),

            T.UserUpdater =
                TRY_CONVERT(INT, @CurrentUserId)

        FROM dbo.Buildings T
        INNER JOIN @Buildings B
            ON T.BuildingId = B.BuildingId
        WHERE ISNULL(B.BuildingId, 0) > 0
          AND ISNULL(T.IsDeleted, 0) = 0;

        -----------------------------------------------------
        -- 7.2 ثبت ساختمان‌های جدید
        -----------------------------------------------------
        INSERT INTO dbo.Buildings
        (
            BuildingName,
            BuildingAddress,
            BuildingDescription,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater,
            OrgId
        )
        SELECT
            LTRIM(RTRIM(B.BuildingName)),
            B.BuildingAddress,
            B.BuildingDescription,
            ISNULL(B.IsActive, 1),
            0,
            GETDATE(),
            TRY_CONVERT(INT, @CurrentUserId),
            B.OrgId
        FROM @Buildings B
        WHERE ISNULL(B.BuildingId, 0) = 0;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'عملیات ثبت و ویرایش ساختمان‌ها با موفقیت انجام شد.';

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Buildings_GetByOrgId]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Buildings_GetByOrgId]
(
    @OrgId BIGINT,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده.';

    ---------------------------------------------------------
    -- اعتبارسنجی OrgId
    ---------------------------------------------------------
    IF @OrgId IS NULL OR @OrgId <= 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه سازمان معتبر نیست.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- بررسی سازمان
    ---------------------------------------------------------
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Organizations
        WHERE OrgId = @OrgId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'سازمان موردنظر یافت نشد یا حذف شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- دریافت ساختمان‌های سازمان
    ---------------------------------------------------------
    SELECT
        BuildingId,
        BuildingName,
        BuildingAddress,
        BuildingDescription,
        IsActive,
        IsDeleted,
        CreatedAt,
        UserCreater,
        UpdatedAt,
        UserUpdater,
        OrgId
    FROM dbo.Buildings
    WHERE OrgId = @OrgId
      AND ISNULL(IsDeleted, 0) = 0
    ORDER BY BuildingId DESC;

    SET @ResultCode = 200;
    SET @ResultMessage = N'اطلاعات ساختمان‌های سازمان با موفقیت دریافت شد.';
END;
GO
/****** Object:  StoredProcedure [dbo].[BuildingsAdd]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   BuildingsAdd
   ========================================================= */
CREATE PROCEDURE [dbo].[BuildingsAdd]
(
    @BuildingName        NVARCHAR(150),
    @BuildingAddress     NVARCHAR(500) = NULL,
    @BuildingDescription NVARCHAR(1000) = NULL,
    @IsActive            BIT = 1,
    @OrgId               BIGINT = NULL,
    @UserCreater         INT = NULL,

    @ResultCode          INT OUTPUT,
    @ResultMessage       NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در ثبت ساختمان.';

    BEGIN TRY

        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@BuildingName)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نام ساختمان الزامی است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Organization
        ---------------------------------------------------------
        IF @OrgId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM dbo.Organizations
               WHERE OrgId = @OrgId
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'سازمان انتخاب شده وجود ندارد یا حذف شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی نام تکراری ساختمان
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE LTRIM(RTRIM(BuildingName)) = LTRIM(RTRIM(@BuildingName))
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'ساختمانی با این نام قبلاً ثبت شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Insert
        ---------------------------------------------------------
        INSERT INTO dbo.Buildings
        (
            BuildingName,
            BuildingAddress,
            BuildingDescription,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater,
            OrgId
        )
        VALUES
        (
            LTRIM(RTRIM(@BuildingName)),
            @BuildingAddress,
            @BuildingDescription,
            ISNULL(@IsActive, 1),
            0,
            GETDATE(),
            @UserCreater,
            @OrgId
        );

        SET @ResultCode = 200;
        SET @ResultMessage = N'ساختمان با موفقیت ثبت شد.';

        ---------------------------------------------------------
        -- رکورد ایجاد شده
        ---------------------------------------------------------
        SELECT
            B.*
        FROM dbo.Buildings AS B
        WHERE B.BuildingId = SCOPE_IDENTITY();

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[BuildingsDel]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   BuildingsDel
   Soft Delete
   ========================================================= */
CREATE PROCEDURE [dbo].[BuildingsDel]
(
    @BuildingId  BIGINT,
    @UserUpdater INT = NULL,

    @ResultCode  INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در حذف ساختمان.';

    BEGIN TRY

        IF @BuildingId IS NULL OR @BuildingId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد ساختمان معتبر نیست.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی وجود ساختمان
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE BuildingId = @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'ساختمان مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی وابستگی Units
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Units
            WHERE BuildingId = @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'امکان حذف ساختمان وجود ندارد؛ برای این ساختمان واحد ثبت شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Soft Delete
        ---------------------------------------------------------
        UPDATE dbo.Buildings
        SET
            IsDeleted = 1,
            IsActive = 0,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE BuildingId = @BuildingId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'ساختمان با موفقیت حذف شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
