/* =========================================================
   BuildingsEdit
   ========================================================= */
CREATE PROCEDURE [dbo].[BuildingsEdit]
(
    @BuildingId          BIGINT,
    @BuildingName        NVARCHAR(150),
    @BuildingAddress     NVARCHAR(500) = NULL,
    @BuildingDescription NVARCHAR(1000) = NULL,
    @IsActive            BIT = 1,
    @OrgId               BIGINT = NULL,
    @UserUpdater         INT = NULL,

    @ResultCode          INT OUTPUT,
    @ResultMessage       NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در ویرایش ساختمان.';

    BEGIN TRY

        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF @BuildingId IS NULL OR @BuildingId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد ساختمان معتبر نیست.';
            RETURN;
        END;

        IF NULLIF(LTRIM(RTRIM(@BuildingName)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نام ساختمان الزامی است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی ساختمان
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE BuildingId = @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'ساختمان مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Organization
        ---------------------------------------------------------
        IF @OrgId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM dbo.Organizations
               WHERE OrgId = @OrgId
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'سازمان انتخاب شده وجود ندارد یا حذف شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی نام تکراری
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE LTRIM(RTRIM(BuildingName)) = LTRIM(RTRIM(@BuildingName))
              AND BuildingId <> @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'ساختمان دیگری با این نام قبلاً ثبت شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Update
        ---------------------------------------------------------
        UPDATE dbo.Buildings
        SET
            BuildingName        = LTRIM(RTRIM(@BuildingName)),
            BuildingAddress     = @BuildingAddress,
            BuildingDescription = @BuildingDescription,
            IsActive            = ISNULL(@IsActive, 1),
            OrgId               = @OrgId,
            UpdatedAt           = GETDATE(),
            UserUpdater         = @UserUpdater
        WHERE BuildingId = @BuildingId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'ساختمان با موفقیت ویرایش شد.';

        SELECT
            B.*
        FROM dbo.Buildings AS B
        WHERE B.BuildingId = @BuildingId;

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[BuildingsGet]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   BuildingsGet
   ========================================================= */
CREATE PROCEDURE [dbo].[BuildingsGet]
(
    @BuildingId      BIGINT = NULL,
    @Search          NVARCHAR(150) = NULL,
    @PageNumber      INT = 1,
    @PageSize        INT = 50,
    @IncludeDeleted  BIT = 0,

    @ResultCode      INT OUTPUT,
    @ResultMessage   NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در دریافت ساختمان‌ها.';

    BEGIN TRY

        SET @PageNumber = ISNULL(@PageNumber, 1);
        SET @PageSize = ISNULL(@PageSize, 50);
        SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');

        IF @PageNumber < 1
            SET @PageNumber = 1;

        IF @PageSize < 1
            SET @PageSize = 50;

        IF @PageSize > 500
            SET @PageSize = 500;

        ---------------------------------------------------------
        -- دریافت یک رکورد
        ---------------------------------------------------------
        IF @BuildingId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Buildings
                WHERE BuildingId = @BuildingId
                  AND
                  (
                      @IncludeDeleted = 1
                      OR ISNULL(IsDeleted, 0) = 0
                  )
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage = N'ساختمان مورد نظر یافت نشد.';
                RETURN;
            END;

            SELECT
                B.*
            FROM dbo.Buildings AS B
            WHERE B.BuildingId = @BuildingId
              AND
              (
                  @IncludeDeleted = 1
                  OR ISNULL(B.IsDeleted, 0) = 0
              );

            SET @ResultCode = 200;
            SET @ResultMessage = N'اطلاعات ساختمان با موفقیت دریافت شد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- دریافت لیست + Pagination
        ---------------------------------------------------------
        SELECT
            B.*
        FROM dbo.Buildings AS B
        WHERE
            (
                @IncludeDeleted = 1
                OR ISNULL(B.IsDeleted, 0) = 0
            )
            AND
            (
                @Search IS NULL
                OR B.BuildingName LIKE N'%' + ISNULL(@Search, N'') + N'%'
            )
        ORDER BY B.BuildingId DESC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

        SET @ResultCode = 200;
        SET @ResultMessage = N'لیست ساختمان‌ها با موفقیت دریافت شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAssignmentsActive]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAssignmentsActive]
(
    @EmployeeAssignmentId BIGINT,
    @IsActive BIT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        UPDATE dbo.EmployeeAssignments
        SET
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeAssignmentId = @EmployeeAssignmentId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'محل خدمت پیدا نشد.';
            RETURN;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage = N'وضعیت محل خدمت تغییر کرد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAssignmentsAdd]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAssignmentsAdd]
(
    @EmployeeId BIGINT,
    @OrgId BIGINT,
    @BuildingId BIGINT = NULL,
    @SpaceId BIGINT = NULL,
    @StartDate DATE,
    @EndDate DATE = NULL,
    @ShiftName NVARCHAR(100) = NULL,
    @EmployeeAssignmentDesc NVARCHAR(1000) = NULL,
    @UserCreater INT = NULL,
    @EmployeeAssignmentId BIGINT OUTPUT,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @EmployeeAssignmentId = NULL;

    BEGIN TRY
        IF @EndDate IS NOT NULL AND @EndDate < @StartDate
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'تاریخ پایان قبل از تاریخ شروع است.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE EmployeeId = @EmployeeId
              AND OrgId = @OrgId
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'کارمند فعال در سازمان انتخاب‌شده پیدا نشد.';
            RETURN;
        END;

        IF @BuildingId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM dbo.Buildings
               WHERE BuildingId = @BuildingId
           )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'ساختمان پیدا نشد.';
            RETURN;
        END;

        IF @SpaceId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM dbo.Spaces
               WHERE SpaceId = @SpaceId
                 AND (@BuildingId IS NULL OR BuildingId = @BuildingId)
           )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'فضا متعلق به ساختمان انتخاب‌شده نیست.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.EmployeeAssignments
            WHERE EmployeeId = @EmployeeId
              AND OrgId = @OrgId
              AND ISNULL(BuildingId, 0) = ISNULL(@BuildingId, 0)
              AND ISNULL(SpaceId, 0) = ISNULL(@SpaceId, 0)
              AND ISNULL(IsDeleted, 0) = 0
              AND IsActive = 1
              AND (@EndDate IS NULL OR StartDate <= @EndDate)
              AND (EndDate IS NULL OR EndDate >= @StartDate)
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'محل خدمت مشابه با بازه زمانی هم‌پوشان وجود دارد.';
            RETURN;
        END;

        INSERT INTO dbo.EmployeeAssignments
        (
            EmployeeId, OrgId, BuildingId, SpaceId,
            StartDate, EndDate, ShiftName, IsActive,
            IsDeleted, EmployeeAssignmentDesc, CreatedAt, UserCreater
        )
        VALUES
        (
            @EmployeeId, @OrgId, @BuildingId, @SpaceId,
            @StartDate, @EndDate, @ShiftName, 1,
            0, @EmployeeAssignmentDesc, GETDATE(), @UserCreater
        );

        SET @EmployeeAssignmentId = CONVERT(BIGINT, SCOPE_IDENTITY());
        SET @ResultCode = 200;
        SET @ResultMessage = N'محل خدمت با موفقیت ثبت شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAssignmentsDel]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAssignmentsDel]
(
    @EmployeeAssignmentId BIGINT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        UPDATE dbo.EmployeeAssignments
        SET
            IsActive = 0,
            IsDeleted = 1,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeAssignmentId = @EmployeeAssignmentId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'محل خدمت پیدا نشد.';
            RETURN;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage = N'محل خدمت حذف نرم شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAssignmentsEdit]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAssignmentsEdit]
(
    @EmployeeAssignmentId BIGINT,
    @OrgId BIGINT,
    @BuildingId BIGINT = NULL,
    @SpaceId BIGINT = NULL,
    @StartDate DATE,
    @EndDate DATE = NULL,
    @ShiftName NVARCHAR(100) = NULL,
    @EmployeeAssignmentDesc NVARCHAR(1000) = NULL,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @EmployeeId BIGINT;

        SELECT @EmployeeId = EmployeeId
        FROM dbo.EmployeeAssignments
        WHERE EmployeeAssignmentId = @EmployeeAssignmentId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @EmployeeId IS NULL
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'محل خدمت پیدا نشد.';
            RETURN;
        END;

        IF @EndDate IS NOT NULL AND @EndDate < @StartDate
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'تاریخ پایان قبل از تاریخ شروع است.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE EmployeeId = @EmployeeId
              AND OrgId = @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'سازمان محل خدمت با سازمان کارمند مطابقت ندارد.';
            RETURN;
        END;

        IF @SpaceId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM dbo.Spaces
               WHERE SpaceId = @SpaceId
                 AND (@BuildingId IS NULL OR BuildingId = @BuildingId)
           )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'فضا متعلق به ساختمان انتخاب‌شده نیست.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.EmployeeAssignments
            WHERE EmployeeId = @EmployeeId
              AND OrgId = @OrgId
              AND ISNULL(BuildingId, 0) = ISNULL(@BuildingId, 0)
              AND ISNULL(SpaceId, 0) = ISNULL(@SpaceId, 0)
              AND EmployeeAssignmentId <> @EmployeeAssignmentId
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
              AND (@EndDate IS NULL OR StartDate <= @EndDate)
              AND (EndDate IS NULL OR EndDate >= @StartDate)
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'محل خدمت مشابه با بازه زمانی هم‌پوشان وجود دارد.';
            RETURN;
        END;

        UPDATE dbo.EmployeeAssignments
        SET
            OrgId = @OrgId,
            BuildingId = @BuildingId,
            SpaceId = @SpaceId,
            StartDate = @StartDate,
            EndDate = @EndDate,
            ShiftName = @ShiftName,
            EmployeeAssignmentDesc = @EmployeeAssignmentDesc,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeAssignmentId = @EmployeeAssignmentId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'محل خدمت با موفقیت ویرایش شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAssignmentsGet]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAssignmentsGet]
(
    @EmployeeId BIGINT = NULL,
    @OrgId BIGINT = NULL,
    @BuildingId BIGINT = NULL,
    @IsActive BIT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 20
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize < 1 SET @PageSize = 20;
    IF @PageSize > 200 SET @PageSize = 200;

    SELECT
        ea.EmployeeAssignmentId,
        ea.EmployeeId,
        ea.OrgId,
        ea.BuildingId,
        ea.SpaceId,
        ea.StartDate,
        ea.EndDate,
        ea.ShiftName,
        ea.IsActive,
        ea.EmployeeAssignmentDesc,
        ea.CreatedAt,
        ea.UpdatedAt
    FROM dbo.EmployeeAssignments ea
    WHERE ISNULL(ea.IsDeleted, 0) = 0
      AND (@EmployeeId IS NULL OR ea.EmployeeId = @EmployeeId)
      AND (@OrgId IS NULL OR ea.OrgId = @OrgId)
      AND (@BuildingId IS NULL OR ea.BuildingId = @BuildingId)
      AND (@IsActive IS NULL OR ea.IsActive = @IsActive)
    ORDER BY ea.StartDate DESC, ea.EmployeeAssignmentId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO
