/****** Object:  StoredProcedure [dbo].[EmployeesActive]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeesActive]
(
    @EmployeeId BIGINT,
    @IsActive BIT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE EmployeeId = @EmployeeId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'کارمند پیدا نشد یا حذف شده است.';
            RETURN;
        END;

        UPDATE dbo.Employees
        SET
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeId = @EmployeeId;

        IF @IsActive = 0
        BEGIN
            UPDATE dbo.EmployeeAssignments
            SET
                IsActive = 0,
                UpdatedAt = GETDATE(),
                UserUpdater = @UserUpdater
            WHERE EmployeeId = @EmployeeId
              AND ISNULL(IsDeleted, 0) = 0;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage =
            CASE WHEN @IsActive = 1
                THEN N'کارمند فعال شد.'
                ELSE N'کارمند غیرفعال شد.'
            END;
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeesAdd]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[EmployeesAdd]
(
    -- اطلاعات حساب کاربری
    @Username           NVARCHAR(100) = NULL,
    @PasswordHash       NVARCHAR(500) = NULL,
    @Email              NVARCHAR(150) = NULL,
    @Mobile             NVARCHAR(30),
    @FirstName          NVARCHAR(100),
    @LastName           NVARCHAR(100),
    @NationalId         NVARCHAR(10) = NULL,
    @Gender             INT,
    @BirthDate          DATETIME = NULL,
    @AvatarUrl          NVARCHAR(500) = NULL,
    @PhoneVerified      BIT = 0,
    @UserIsActive       BIT = 1,

    -- اطلاعات پرسنلی
    @OrgId              BIGINT,
    @EmployeeTypeId     INT,
    @EmploymentType     TINYINT,
    @HireDate           DATE = NULL,
    @EndDate            DATE = NULL,
    @BaseSalary         DECIMAL(18,2) = NULL,
    @HourlyRate         DECIMAL(18,2) = NULL,
    @BankName           NVARCHAR(100) = NULL,
    @BankCardNumber     NVARCHAR(100) = NULL,
    @BankAccountNumber  NVARCHAR(100) = NULL,
    @ShebaNumber        NVARCHAR(50) = NULL,
    @EmployeeIsActive   BIT = 1,
    @EmployeesDesc      NVARCHAR(2000) = NULL,

    -- اطلاعات ثبت‌کننده
    @UserCreater        INT = NULL,

    -- خروجی‌ها
    @NewUserId          BIGINT OUTPUT,
    @NewEmployeeId      BIGINT OUTPUT,
    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @NewUserId = NULL,
        @NewEmployeeId = NULL,
        @ResultCode = 500,
        @ResultMessage = N'خطای پیش‌بینی‌نشده رخ داد.';

    BEGIN TRY

        ----------------------------------------------------
        -- 1. اعتبارسنجی ورودی‌های اجباری
        ----------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Mobile)), N'') IS NULL
           OR NULLIF(LTRIM(RTRIM(@FirstName)), N'') IS NULL
           OR NULLIF(LTRIM(RTRIM(@LastName)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'موبایل، نام و نام خانوادگی الزامی هستند.';
            RETURN;
        END;

        IF @Gender NOT IN (1, 2)
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'مقدار جنسیت معتبر نیست. مقدار 1 برای مرد و 2 برای زن است.';
            RETURN;
        END;

        IF @HireDate IS NOT NULL
           AND @EndDate IS NOT NULL
           AND @EndDate < @HireDate
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'تاریخ پایان استخدام نمی‌تواند قبل از تاریخ شروع باشد.';
            RETURN;
        END;

        IF @BaseSalary < 0 OR @HourlyRate < 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'حقوق پایه و نرخ ساعتی نمی‌توانند منفی باشند.';
            RETURN;
        END;

        ----------------------------------------------------
        -- 2. بررسی سازمان
        ----------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Organizations
            WHERE OrgId = @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'سازمان انتخاب‌شده معتبر نیست.';
            RETURN;
        END;

        ----------------------------------------------------
        -- 3. بررسی نوع پرسنل
        ----------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_LookupValues
            WHERE LookupId = @EmployeeTypeId
        )
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage =
                N'نوع پرسنل انتخاب‌شده معتبر یا فعال نیست.';
            RETURN;
        END;

        ----------------------------------------------------
        -- 4. بررسی تکراری نبودن اطلاعات کاربر
        ----------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.App_Users
            WHERE Mobile = @Mobile
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این شماره موبایل قبلاً ثبت شده است.';
            RETURN;
        END;

        IF @Username IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE Username = @Username
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این نام کاربری قبلاً ثبت شده است.';
            RETURN;
        END;

        IF @Email IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE Email = @Email
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این ایمیل قبلاً ثبت شده است.';
            RETURN;
        END;

        IF @NationalId IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM dbo.App_Users
               WHERE NationalId = @NationalId
                 AND ISNULL(IsDeleted, 0) = 0
           )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'این کد ملی قبلاً ثبت شده است.';
            RETURN;
        END;

        ----------------------------------------------------
        -- 5. ثبت حساب کاربری و اطلاعات پرسنلی
        ----------------------------------------------------
        BEGIN TRANSACTION;

        INSERT INTO dbo.App_Users
        (
            Username,
            PasswordHash,
            Email,
            Mobile,
            FirstName,
            LastName,
            NationalId,
            Gender,
            BirthDate,
            AvatarUrl,
            PhoneVerified,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater
        )
        VALUES
        (
            NULLIF(LTRIM(RTRIM(@Username)), N''),
            @PasswordHash,
            NULLIF(LTRIM(RTRIM(@Email)), N''),
            LTRIM(RTRIM(@Mobile)),
            LTRIM(RTRIM(@FirstName)),
            LTRIM(RTRIM(@LastName)),
            NULLIF(LTRIM(RTRIM(@NationalId)), N''),
            @Gender,
            @BirthDate,
            @AvatarUrl,
            @PhoneVerified,
            @UserIsActive,
            0,
            GETDATE(),
            @UserCreater
        );

        SET @NewUserId = CONVERT(BIGINT, SCOPE_IDENTITY());

        INSERT INTO dbo.Employees
        (
            UserId,
            OrgId,
            EmployeeTypeId,
            EmploymentType,
            HireDate,
            EndDate,
            BaseSalary,
            HourlyRate,
            BankName,
            BankCardNumber,
            BankAccountNumber,
            ShebaNumber,
            IsActive,
            IsDeleted,
            EmployeesDesc,
            CreatedAt,
            UserCreater
        )
        VALUES
        (
            @NewUserId,
            @OrgId,
            @EmployeeTypeId,
            @EmploymentType,
            @HireDate,
            @EndDate,
            @BaseSalary,
            @HourlyRate,
            @BankName,
            @BankCardNumber,
            @BankAccountNumber,
            @ShebaNumber,
            @EmployeeIsActive,
            0,
            @EmployeesDesc,
            GETDATE(),
            @UserCreater
        );

        SET @NewEmployeeId = CONVERT(BIGINT, SCOPE_IDENTITY());

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage =
            N'حساب کاربری و اطلاعات پرسنلی با موفقیت ثبت شدند.';

    END TRY
    BEGIN CATCH

        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SELECT
            @NewUserId = NULL,
            @NewEmployeeId = NULL,
            @ResultCode = 500,
            @ResultMessage = LEFT(ERROR_MESSAGE(), 500);

        -- در صورت نیاز به ثبت خطا در جدول لاگ،
        -- این قسمت را می‌توان توسعه داد.

    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeesDel]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeesDel]
(
    @EmployeeId BIGINT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @UserId BIGINT;

        SELECT @UserId = UserId
        FROM dbo.Employees WITH (UPDLOCK, HOLDLOCK)
        WHERE EmployeeId = @EmployeeId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @UserId IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SET @ResultCode = 404;
            SET @ResultMessage = N'کارمند پیدا نشد.';
            RETURN;
        END;

        UPDATE dbo.Employees
        SET
            IsActive = 0,
            IsDeleted = 1,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeId = @EmployeeId;

        UPDATE dbo.EmployeeAssignments
        SET
            IsActive = 0,
            IsDeleted = 1,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeId = @EmployeeId
          AND ISNULL(IsDeleted, 0) = 0;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'کارمند و محل‌های خدمت فعال او حذف نرم شدند.';
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeesEdit]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeesEdit]
(
    @EmployeeId BIGINT,
    @OrgId BIGINT,
    @EmployeeTypeId INT,
    @EmploymentType TINYINT,

    @HireDate DATE = NULL,
    @EndDate DATE = NULL,
    @BaseSalary DECIMAL(18,2) = NULL,
    @HourlyRate DECIMAL(18,2) = NULL,
    @BankName NVARCHAR(100) = NULL,
    @BankCardNumber NVARCHAR(100) = NULL,
    @BankAccountNumber NVARCHAR(100) = NULL,
    @ShebaNumber NVARCHAR(50) = NULL,
    @EmployeesDesc NVARCHAR(2000) = NULL,

    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @EmployeeId <= 0 OR @OrgId <= 0 OR @EmployeeTypeId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'پارامترهای ارسالی معتبر نیستند.';
            RETURN;
        END;

        IF @EndDate IS NOT NULL AND @HireDate IS NOT NULL
           AND @EndDate < @HireDate
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'تاریخ پایان استخدام نمی‌تواند قبل از تاریخ شروع باشد.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE EmployeeId = @EmployeeId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'کارمند پیدا نشد.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_LookupValues
            WHERE LookupId = @EmployeeTypeId
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نوع استخدام فعال پیدا نشد.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE OrgId = @OrgId
              AND EmployeeId <> @EmployeeId
              AND ISNULL(IsDeleted, 0) = 0
              AND UserId =
              (
                  SELECT UserId
                  FROM dbo.Employees
                  WHERE EmployeeId = @EmployeeId
              )
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این کارمند قبلاً در سازمان انتخاب‌شده ثبت شده است.';
            RETURN;
        END;

        BEGIN TRANSACTION;

        DECLARE @OldEmployeeTypeId INT;
        DECLARE @UserId BIGINT;

        SELECT
            @OldEmployeeTypeId = EmployeeTypeId,
            @UserId = UserId
        FROM dbo.Employees WITH (UPDLOCK, HOLDLOCK)
        WHERE EmployeeId = @EmployeeId;

        UPDATE dbo.Employees
        SET
            OrgId = @OrgId,
            EmployeeTypeId = @EmployeeTypeId,
            EmploymentType = @EmploymentType,
            HireDate = @HireDate,
            EndDate = @EndDate,
            BaseSalary = @BaseSalary,
            HourlyRate = @HourlyRate,
            BankName = @BankName,
            BankCardNumber = @BankCardNumber,
            BankAccountNumber = @BankAccountNumber,
            ShebaNumber = @ShebaNumber,
            EmployeesDesc = @EmployeesDesc,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeId = @EmployeeId;

        --------------------------------------------------
        -- If type changed, replace the roles that were
        -- previously mapped to the old employee type.
        --------------------------------------------------
        IF @OldEmployeeTypeId <> @EmployeeTypeId
        BEGIN
            UPDATE ur
            SET
                IsActive = 0,
                IsDeleted = 1,
                UpdatedAt = GETDATE(),
                UserUpdater = @UserUpdater
            FROM dbo.App_UserRoles ur
            INNER JOIN dbo.EmployeeTypeRoles oldMap
                ON oldMap.RoleId = ur.RoleId
            WHERE ur.UserId = @UserId
              AND oldMap.EmployeeTypeId = @OldEmployeeTypeId
              AND ISNULL(ur.IsDeleted, 0) = 0;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.EmployeeTypeRoles
                WHERE EmployeeTypeId = @EmployeeTypeId
                  AND IsActive = 1
                  AND ISNULL(IsDeleted, 0) = 0
            )
            BEGIN
                THROW 50001, N'برای نوع استخدام جدید نقشی تعریف نشده است.', 1;
            END;

            INSERT INTO dbo.App_UserRoles
            (
                UserId, RoleId, AssignedAt, ExpiresAt,
                IsActive, IsDeleted, CreatedAt, UserCreater, Notes
            )
            SELECT
                @UserId,
                etr.RoleId,
                GETDATE(),
                NULL,
                1,
                0,
                GETDATE(),
                @UserUpdater,
                N'نقش تخصیص‌یافته بر اساس تغییر نوع استخدام'
            FROM dbo.EmployeeTypeRoles etr
            WHERE etr.EmployeeTypeId = @EmployeeTypeId
              AND etr.IsActive = 1
              AND ISNULL(etr.IsDeleted, 0) = 0
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM dbo.App_UserRoles ur
                  WHERE ur.UserId = @UserId
                    AND ur.RoleId = etr.RoleId
                    AND ur.IsActive = 1
                    AND ISNULL(ur.IsDeleted, 0) = 0
              );
        END;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'اطلاعات کارمند با موفقیت ویرایش شد.';
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeesGet]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeesGet]
(
    @Search NVARCHAR(200) = NULL,
    @OrgId BIGINT = NULL,
    @EmployeeTypeId INT = NULL,
    @IsActive BIT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 20
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize < 1 SET @PageSize = 20;
    IF @PageSize > 200 SET @PageSize = 200;

    SELECT
        e.EmployeeId,
        e.UserId,
        e.OrgId,
        o.OrgName,
        e.EmployeeTypeId,
        et.LookupValueTitleFr AS EmployeeTypeNameFr,
        et.LookupValueTitleEn AS EmployeeTypeNameEn,
        e.EmploymentType,
        e.HireDate,
        e.EndDate,
        e.BaseSalary,
        e.HourlyRate,
        e.BankName,
        e.BankCardNumber,
        e.BankAccountNumber,
        e.ShebaNumber,
        e.IsActive,
        e.EmployeesDesc,
        e.CreatedAt,
        u.FirstName,
        u.LastName,
        u.Mobile
    FROM dbo.Employees e
    INNER JOIN dbo.Organizations o
        ON o.OrgId = e.OrgId
    INNER JOIN dbo.Base_LookupValues et
        ON et.LookupValueId = e.EmployeeTypeId
    INNER JOIN dbo.App_Users u
        ON u.UserId = e.UserId
    WHERE ISNULL(e.IsDeleted, 0) = 0
      AND (@OrgId IS NULL OR e.OrgId = @OrgId)
      AND (@EmployeeTypeId IS NULL OR e.EmployeeTypeId = @EmployeeTypeId)
      AND (@IsActive IS NULL OR e.IsActive = @IsActive)
      AND
      (
          @Search IS NULL
          OR u.FirstName LIKE N'%' + @Search + N'%'
          OR u.LastName LIKE N'%' + @Search + N'%'
          OR u.Mobile LIKE N'%' + @Search + N'%'
      )
    ORDER BY e.EmployeeId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeesGetById]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeesGetById]
(
    @EmployeeId BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        e.EmployeeId,
        e.UserId,
        e.OrgId,
        o.OrgName,
        e.EmployeeTypeId,
        et.LookupValueTitleFr EmployeeTypeNameFr,
        et.LookupValueTitleEn EmployeeTypeNameEn,
        e.EmploymentType,
        e.HireDate,
        e.EndDate,
        e.BaseSalary,
        e.HourlyRate,
        e.BankName,
        e.BankCardNumber,
        e.BankAccountNumber,
        e.ShebaNumber,
        e.IsActive,
        e.EmployeesDesc,
        e.CreatedAt,
        e.UpdatedAt,
        u.FirstName,
        u.LastName,
        u.Mobile
    FROM dbo.Employees e
    INNER JOIN dbo.Organizations o
        ON o.OrgId = e.OrgId
    INNER JOIN dbo.Base_LookupValues et
        ON et.LookupValueId = e.EmployeeTypeId
    INNER JOIN dbo.App_Users u
        ON u.UserId = e.UserId
    WHERE e.EmployeeId = @EmployeeId
      AND ISNULL(e.IsDeleted, 0) = 0;

    SELECT
        ea.EmployeeAssignmentId,
        ea.EmployeeId,
        ea.OrgId,
        ea.BuildingId,
        b.BuildingName,
        ea.SpaceId,
        ea.StartDate,
        ea.EndDate,
        ea.ShiftName,
        ea.IsActive,
        ea.EmployeeAssignmentDesc
    FROM dbo.EmployeeAssignments ea
    LEFT JOIN dbo.Buildings b
        ON b.BuildingId = ea.BuildingId
    WHERE ea.EmployeeId = @EmployeeId
      AND ISNULL(ea.IsDeleted, 0) = 0
    ORDER BY ea.StartDate DESC, ea.EmployeeAssignmentId DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeTypeRolesAdd]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeTypeRolesAdd]
(
    @EmployeeTypeId INT,
    @RoleId BIGINT,
    @UserId INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_LookupValues
            WHERE LookupValueId = @EmployeeTypeId
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نوع استخدام معتبر نیست.';
            RETURN;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.App_Roles
            WHERE RoleId = @RoleId
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نقش مورد نظر پیدا نشد.';
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.EmployeeTypeRoles
            WHERE EmployeeTypeId = @EmployeeTypeId
              AND RoleId = @RoleId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این نگاشت قبلاً ثبت شده است.';
            RETURN;
        END;

        INSERT INTO dbo.EmployeeTypeRoles
        (
            EmployeeTypeId, RoleId, IsActive,
            IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @EmployeeTypeId, @RoleId, 1,
            0, GETDATE(), @UserId
        );

        SET @ResultCode = 200;
        SET @ResultMessage = N'نگاشت نوع استخدام به نقش ثبت شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[EmployeeTypeRolesGet]    Script Date: 10/29/2026 8:34:29 PM ******/
