CREATE PROCEDURE [dbo].[EmployeeTypeRolesGet]
(
    @EmployeeTypeId INT = NULL,
    @RoleId BIGINT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        etr.EmployeeTypeRoleId,
        etr.EmployeeTypeId,
        et.LookupValueTitleFr EmployeeTypeNameFr,
        et.LookupValueTitleEn EmployeeTypeNameEn,
        etr.RoleId,
        r.RoleName,
        etr.IsActive,
        etr.CreatedAt
    FROM dbo.EmployeeTypeRoles etr
    INNER JOIN dbo.Base_LookupValues et
        ON et.LookupValueId = etr.EmployeeTypeId
    INNER JOIN dbo.App_Roles r
        ON r.RoleId = etr.RoleId
    WHERE ISNULL(etr.IsDeleted, 0) = 0
      AND (@EmployeeTypeId IS NULL OR etr.EmployeeTypeId = @EmployeeTypeId)
      AND (@RoleId IS NULL OR etr.RoleId = @RoleId)
    ORDER BY et.LookupValueTitleFr,LookupValueTitleEn, r.RoleName;
END;
