CREATE PROCEDURE [dbo].[EmployeeTypesActive]
(
    @EmployeeTypeId INT,
    @IsActive BIT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        UPDATE dbo.EmployeeTypes
        SET
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeTypeId = @EmployeeTypeId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نوع استخدام پیدا نشد.';
            RETURN;
        END;

        SET @ResultCode = 200;
        SET @ResultMessage = N'وضعیت نوع استخدام تغییر کرد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
