CREATE PROCEDURE [dbo].[EmployeeTypesDel]
(
    @EmployeeTypeId INT,
    @UserUpdater INT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Employees
            WHERE EmployeeTypeId = @EmployeeTypeId
              AND IsActive = 1
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage = N'این نوع استخدام به کارمند فعال متصل است و قابل حذف نیست.';
            RETURN;
        END;

        UPDATE dbo.EmployeeTypes
        SET
            IsActive = 0,
            IsDeleted = 1,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeTypeId = @EmployeeTypeId
          AND ISNULL(IsDeleted, 0) = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'نوع استخدام پیدا نشد.';
            RETURN;
        END;

        UPDATE dbo.EmployeeTypeRoles
        SET
            IsActive = 0,
            IsDeleted = 1,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE EmployeeTypeId = @EmployeeTypeId
          AND ISNULL(IsDeleted, 0) = 0;

        SET @ResultCode = 200;
        SET @ResultMessage = N'نوع استخدام حذف نرم شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = 500;
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH
END;
GO
