/****** Object:  StoredProcedure [dbo].[EmployeeTypesGet]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeTypesGet]
(
    @Search NVARCHAR(100) = NULL,
    @IsActive BIT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 20
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize < 1 SET @PageSize = 20;
    IF @PageSize > 200 SET @PageSize = 200;

    SELECT
        EmployeeTypeId,
        EmployeeTypeName,
        EmployeeTypeDesc,
        IsActive,
        CreatedAt,
        UpdatedAt
    FROM dbo.EmployeeTypes
    WHERE ISNULL(IsDeleted, 0) = 0
      AND (@IsActive IS NULL OR IsActive = @IsActive)
      AND
      (
          @Search IS NULL
          OR EmployeeTypeName LIKE N'%' + @Search + N'%'
          OR EmployeeTypeDesc LIKE N'%' + @Search + N'%'
      )
    ORDER BY EmployeeTypeName
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO
