CREATE   PROCEDURE [dbo].[Enrollment_Class_Cancel]
    @EnrollmentId BIGINT,
    @CancellationReason NVARCHAR(1000) = NULL,
    @CancellationReasonEn NVARCHAR(1000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE dbo.Enrollment_Class
    SET EnrollmentStatus = 4,
        CancelledAt = SYSDATETIME(),
        CancellationReason = @CancellationReason,
        CancellationReasonEn = @CancellationReasonEn,
        UpdatedAt = GETDATE(),
        UserUpdater = @UserId
    WHERE EnrollmentId = @EnrollmentId
      AND EnrollmentStatus NOT IN (4,5);

    IF @@ROWCOUNT = 0
        THROW 51106, N'ثبت‌نام فعال پیدا نشد.', 1;

    EXEC dbo.Enrollment_Class_GetById @EnrollmentId;
END;
GO
/****** Object:  StoredProcedure [dbo].[Enrollment_Class_CheckCapacity]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Enrollment_Class_CheckCapacity]
    @ClassSessionId BIGINT,
    @InactiveStatuses NVARCHAR(20) = N'4,5'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        s.ClassSessionId,
        cs.Capacity,
        COUNT_BIG(e.EnrollmentId) AS TotalEnrollments,
        CASE WHEN COUNT_BIG(e.EnrollmentId) < cs.Capacity
             THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END AS HasCapacity
    FROM dbo.Booking_ClassSessions s
    INNER JOIN dbo.Booking_ClassSeries cs
        ON cs.ClassSeriesId = s.ClassSeriesId
    LEFT JOIN dbo.Enrollment_Class e
        ON e.ClassSessionId = s.ClassSessionId
       AND NOT EXISTS
       (
           SELECT 1
           FROM STRING_SPLIT(@InactiveStatuses, ',') x
           WHERE TRY_CONVERT(TINYINT, LTRIM(RTRIM(x.value))) = e.EnrollmentStatus
       )
    WHERE s.ClassSessionId = @ClassSessionId
      AND s.IsDeleted = 0
      AND cs.IsDeleted = 0
    GROUP BY s.ClassSessionId, cs.Capacity;
END;
GO
