SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Enrollment_Class_GetList]
    @ClassSessionId BIGINT = NULL,
    @ParticipantId BIGINT = NULL,
    @EnrollmentStatus TINYINT = NULL,
    @PaymentStatus TINYINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT e.*, p.FullName, p.MobileNumber,
           s.ClassSeriesId, s.SessionTitle, s.SessionTitleEn
    FROM dbo.Enrollment_Class e
    INNER JOIN dbo.Booking_Participants p
        ON p.ParticipantId = e.ParticipantId
    INNER JOIN dbo.Booking_ClassSessions s
        ON s.ClassSessionId = e.ClassSessionId
    WHERE (@ClassSessionId IS NULL OR e.ClassSessionId = @ClassSessionId)
      AND (@ParticipantId IS NULL OR e.ParticipantId = @ParticipantId)
      AND (@EnrollmentStatus IS NULL OR e.EnrollmentStatus = @EnrollmentStatus)
      AND (@PaymentStatus IS NULL OR e.PaymentStatus = @PaymentStatus)
