/****** Object:  StoredProcedure [dbo].[Enrollment_Class_Register]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Enrollment_Class_Register]
    @ClassSessionId BIGINT,
    @ParticipantId BIGINT,
    @PricingRuleId BIGINT = NULL,
    @CurrencyCode CHAR(3) = 'IRR',
    @BaseAmount DECIMAL(18,2),
    @DiscountAmount DECIMAL(18,2) = 0,
    @FinalAmount DECIMAL(18,2),
    @PaymentStatus TINYINT = 1,
    @UserId INT = NULL,
    @EnrollmentId BIGINT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @BaseAmount < 0 OR @DiscountAmount < 0 OR @FinalAmount < 0
        THROW 51101, N'مبالغ ثبت‌نام نامعتبر است.', 1;

    IF @DiscountAmount > @BaseAmount
        THROW 51102, N'تخفیف نمی‌تواند بیشتر از مبلغ پایه باشد.', 1;

    BEGIN TRANSACTION;

    DECLARE @Capacity INT, @IsRegistrationOpen BIT;

    SELECT @Capacity = cs.Capacity,
           @IsRegistrationOpen = cs.IsRegistrationOpen
    FROM dbo.Booking_ClassSessions s WITH (UPDLOCK, HOLDLOCK)
    INNER JOIN dbo.Booking_ClassSeries cs
        ON cs.ClassSeriesId = s.ClassSeriesId
    WHERE s.ClassSessionId = @ClassSessionId
      AND s.IsDeleted = 0
      AND s.IsActive = 1
      AND cs.IsDeleted = 0
      AND cs.IsActive = 1
      AND (cs.RegistrationStartAt IS NULL
           OR cs.RegistrationStartAt <= SYSDATETIME())
      AND (cs.RegistrationEndAt IS NULL
           OR cs.RegistrationEndAt >= SYSDATETIME());

    IF @Capacity IS NULL OR @IsRegistrationOpen = 0
    BEGIN
        ROLLBACK;
        THROW 51103, N'جلسه فعال نیست یا ثبت‌نام آن باز نیست.', 1;
    END;

    IF EXISTS (
        SELECT 1
        FROM dbo.Enrollment_Class WITH (UPDLOCK, HOLDLOCK)
        WHERE ClassSessionId = @ClassSessionId
          AND ParticipantId = @ParticipantId
          AND EnrollmentStatus NOT IN (4,5)
    )
    BEGIN
        ROLLBACK;
        THROW 51104, N'شرکت‌کننده ثبت‌نام فعال دارد.', 1;
    END;

    IF (
        SELECT COUNT_BIG(*)
        FROM dbo.Enrollment_Class WITH (UPDLOCK, HOLDLOCK)
        WHERE ClassSessionId = @ClassSessionId
          AND EnrollmentStatus NOT IN (4,5)
    ) >= @Capacity
    BEGIN
        ROLLBACK;
        THROW 51105, N'ظرفیت کلاس تکمیل شده است.', 1;
    END;

    INSERT INTO dbo.Enrollment_Class
    (
        ClassSessionId, ParticipantId, EnrollmentStatus, RegisteredAt,
        PricingRuleId, CurrencyCode, BaseAmount, DiscountAmount,
        FinalAmount, PaymentStatus, CreatedAt, UserCreater
    )
    VALUES
    (
        @ClassSessionId, @ParticipantId, 1, SYSDATETIME(),
        @PricingRuleId, @CurrencyCode, @BaseAmount, @DiscountAmount,
        @FinalAmount, @PaymentStatus, GETDATE(), @UserId
    );

    SET @EnrollmentId = SCOPE_IDENTITY();

    COMMIT;

    EXEC dbo.Enrollment_Class_GetById @EnrollmentId;
END;
GO
