SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Enrollment_Waitlist_Join]
    @ClassSessionId BIGINT,
    @ParticipantId BIGINT,
    @UserId INT = NULL,
    @WaitlistId BIGINT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    IF EXISTS (
        SELECT 1
        FROM dbo.Enrollment_Class
        WHERE ClassSessionId = @ClassSessionId
          AND ParticipantId = @ParticipantId
          AND EnrollmentStatus NOT IN (4,5)
    )
    BEGIN
        ROLLBACK;
        THROW 51110, N'این شرکت‌کننده ثبت‌نام فعال دارد.', 1;
    END;

    IF EXISTS (
        SELECT 1
        FROM dbo.Enrollment_Waitlist WITH (UPDLOCK, HOLDLOCK)
        WHERE ClassSessionId = @ClassSessionId
          AND ParticipantId = @ParticipantId
          AND WaitlistStatus = 1
    )
    BEGIN
        ROLLBACK;
        THROW 51111, N'شرکت‌کننده از قبل در لیست انتظار فعال است.', 1;
    END;

    DECLARE @QueueNumber INT;

    SELECT @QueueNumber = ISNULL(MAX(QueueNumber), 0) + 1
    FROM dbo.Enrollment_Waitlist WITH (UPDLOCK, HOLDLOCK)
    WHERE ClassSessionId = @ClassSessionId;

    INSERT INTO dbo.Enrollment_Waitlist
    (
        ClassSessionId, ParticipantId, QueueNumber,
        WaitlistStatus, JoinedAt, CreatedAt, UserCreater
    )
    VALUES
    (
        @ClassSessionId, @ParticipantId, @QueueNumber,
        1, SYSDATETIME(), GETDATE(), @UserId
    );

    SET @WaitlistId = SCOPE_IDENTITY();

    COMMIT;

    EXEC dbo.Enrollment_Waitlist_GetById @WaitlistId;
END;
GO
/****** Object:  StoredProcedure [dbo].[Enrollment_Waitlist_UpdateStatus]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Enrollment_Waitlist_UpdateStatus]
    @WaitlistId BIGINT,
    @WaitlistStatus TINYINT,
    @OfferedAt DATETIME2(0) = NULL,
    @ExpiresAt DATETIME2(0) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @ExpiresAt IS NOT NULL AND @OfferedAt IS NOT NULL
       AND @ExpiresAt < @OfferedAt
        THROW 51112, N'زمان انقضا نمی‌تواند قبل از زمان پیشنهاد باشد.', 1;

    UPDATE dbo.Enrollment_Waitlist
    SET WaitlistStatus = @WaitlistStatus,
        OfferedAt = @OfferedAt,
        ExpiresAt = @ExpiresAt,
        UpdatedAt = GETDATE(),
        UserUpdater = @UserId
    WHERE WaitlistId = @WaitlistId;

    IF @@ROWCOUNT = 0
        THROW 51113, N'رکورد لیست انتظار پیدا نشد.', 1;

    EXEC dbo.Enrollment_Waitlist_GetById @WaitlistId;
END;
GO
