/* =========================================================
   OrganizationsDel
   ========================================================= */
CREATE PROCEDURE [dbo].[OrganizationsDel]
(
    @OrgId       BIGINT,
    @UserUpdater INT = NULL,

    @ResultCode  INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در حذف سازمان.';

    BEGIN TRY

        IF @OrgId IS NULL OR @OrgId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد سازمان معتبر نیست.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی وجود سازمان
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Organizations
            WHERE OrgId = @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'سازمان مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Buildings
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE OrgId = @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'امکان حذف سازمان وجود ندارد؛ ساختمان‌هایی به این سازمان متصل هستند.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Soft Delete
        ---------------------------------------------------------
        UPDATE dbo.Organizations
        SET
            IsDeleted = 1,
            IsActive = 0,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE OrgId = @OrgId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'سازمان با موفقیت حذف شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
