/* =========================================================
   OrganizationsEdit
   ========================================================= */
CREATE PROCEDURE [dbo].[OrganizationsEdit]
(
    @OrgId         BIGINT,
    @OrgName       NVARCHAR(200),
    @OrgType       INT,
    @GeoId         NVARCHAR(10),
    @OrgDesc       NVARCHAR(1000) = NULL,
    @IsActive      BIT = 1,
    @UserUpdater   INT = NULL,

    @ResultCode    INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در ویرایش سازمان.';

    BEGIN TRY
		SET @GeoId = NULLIF(LTRIM(RTRIM(@GeoId)), N'');
        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF @OrgId IS NULL OR @OrgId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد سازمان معتبر نیست.';
            RETURN;
        END;

        IF NULLIF(LTRIM(RTRIM(@OrgName)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نام سازمان الزامی است.';
            RETURN;
        END;

        IF @OrgType IS NULL OR @OrgType = 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'نوع سازمان معتبر نیست.';
            RETURN;
        END;

        IF @GeoId IS NULL OR @GeoId <= '0'
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'موقعیت جغرافیایی الزامی است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی سازمان
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Organizations
            WHERE OrgId = @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'سازمان مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Geo
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_Geo
            WHERE GeoId = @GeoId
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'موقعیت جغرافیایی انتخاب شده وجود ندارد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Duplicate
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Organizations
            WHERE LTRIM(RTRIM(OrgName)) = LTRIM(RTRIM(@OrgName))
              AND OrgType = @OrgType
              AND GeoId = @GeoId
              AND OrgId <> @OrgId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'سازمان دیگری با همین نام، نوع سازمان و موقعیت جغرافیایی وجود دارد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Update
        ---------------------------------------------------------
        UPDATE dbo.Organizations
        SET
            OrgName = LTRIM(RTRIM(@OrgName)),
            OrgType = @OrgType,
            GeoId = @GeoId,
            OrgDesc = @OrgDesc,
            IsActive = ISNULL(@IsActive, 1),
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE OrgId = @OrgId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'سازمان با موفقیت ویرایش شد.';

        SELECT
            O.*
        FROM dbo.Organizations AS O
        WHERE O.OrgId = @OrgId;

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
