/* =========================================================
   OrganizationsGet
   ========================================================= */
CREATE PROCEDURE [dbo].[OrganizationsGet]
(
    @OrgId          BIGINT = NULL,
    @Search         NVARCHAR(200) = NULL,
    @OrgType        INT = NULL,
    @GeoId          BIGINT = NULL,
    @PageNumber     INT = 1,
    @PageSize       INT = 50,
    @IncludeDeleted BIT = 0,

    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در دریافت سازمان‌ها.';

    BEGIN TRY

        SET @PageNumber = ISNULL(@PageNumber, 1);
        SET @PageSize = ISNULL(@PageSize, 50);
        SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');

        IF @PageNumber < 1
            SET @PageNumber = 1;

        IF @PageSize < 1
            SET @PageSize = 50;

        IF @PageSize > 500
            SET @PageSize = 500;

        ---------------------------------------------------------
        -- دریافت یک سازمان
        ---------------------------------------------------------
        IF @OrgId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Organizations
                WHERE OrgId = @OrgId
                  AND
                  (
                      @IncludeDeleted = 1
                      OR ISNULL(IsDeleted, 0) = 0
                  )
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage = N'سازمان مورد نظر یافت نشد.';
                RETURN;
            END;

            SELECT
                O.*
            FROM dbo.Organizations AS O
            WHERE O.OrgId = @OrgId
              AND
              (
                  @IncludeDeleted = 1
                  OR ISNULL(O.IsDeleted, 0) = 0
              );

            SET @ResultCode = 200;
            SET @ResultMessage = N'اطلاعات سازمان با موفقیت دریافت شد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- لیست سازمان‌ها
        ---------------------------------------------------------
        SELECT
            O.*,
            LV.LookupValueTitleFr AS OrgTypeNameFr,
            LV.LookupValueTitleEn AS OrgTypeNameEn
        FROM dbo.Organizations AS O INNER JOIN
             dbo.Base_LookupValues AS LV ON O.OrgType = LV.LookupValueId
        WHERE
            (
                @IncludeDeleted = 1
                OR ISNULL(O.IsDeleted, 0) = 0
            )
            AND
            (
                @Search IS NULL
                OR O.OrgName LIKE N'%' + ISNULL(@Search, N'') + N'%'
            )
            AND
            (
                @OrgType IS NULL
                OR O.OrgType = @OrgType
            )
            AND
            (
                @GeoId IS NULL
                OR O.GeoId = @GeoId
            )
        ORDER BY O.OrgId DESC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

        SET @ResultCode = 200;
        SET @ResultMessage = N'لیست سازمان‌ها با موفقیت دریافت شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[Pricing_CommissionPlans_Calculate]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Pricing_CommissionPlans_Calculate]
    @CommissionPlanId BIGINT,
    @ParticipantCount INT,
    @CommissionBaseAmount DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    IF @ParticipantCount < 0 OR @CommissionBaseAmount < 0
        THROW 51801, N'تعداد شرکت‌کنندگان یا مبلغ مبنا نامعتبر است.', 1;

    DECLARE
        @CommissionMethod TINYINT,
        @FixedAmount DECIMAL(18,2),
        @CommissionPercent DECIMAL(5,2),
        @CommissionAmount DECIMAL(18,2),
        @TierId BIGINT,
        @TierPercent DECIMAL(5,2),
        @TierAmount DECIMAL(18,2);

    SELECT
        @CommissionMethod = CommissionMethod,
        @FixedAmount = FixedAmount,
        @CommissionPercent = CommissionPercent
    FROM dbo.Pricing_CommissionPlans
    WHERE CommissionPlanId = @CommissionPlanId
      AND IsActive = 1
      AND IsDeleted = 0
      AND ValidFrom <= SYSDATETIME()
      AND (ValidTo IS NULL OR ValidTo >= SYSDATETIME());

    IF @CommissionMethod IS NULL
        THROW 51802, N'طرح کارمزد فعال و معتبر پیدا نشد.', 1;

    /*
      روش 1: مبلغ ثابت
      روش 2: درصد از مبلغ مبنا
      روش 3: انتخاب پلکان بر اساس تعداد شرکت‌کنندگان
    */
    IF @CommissionMethod = 1
    BEGIN
        SET @CommissionAmount = ISNULL(@FixedAmount, 0);
    END
    ELSE IF @CommissionMethod = 2
    BEGIN
        SET @CommissionAmount =
            ROUND(@CommissionBaseAmount * ISNULL(@CommissionPercent, 0) / 100.0, 2);
    END
    ELSE IF @CommissionMethod = 3
    BEGIN
        SELECT TOP (1)
            @TierId = CommissionTierId,
            @TierPercent = TierPercent,
            @TierAmount = TierAmount
        FROM dbo.Pricing_CommissionTiers
        WHERE CommissionPlanId = @CommissionPlanId
          AND MinParticipantCount <= @ParticipantCount
          AND (
              MaxParticipantCount IS NULL
              OR MaxParticipantCount >= @ParticipantCount
          )
        ORDER BY TierOrder;

        IF @TierId IS NULL
            THROW 51803, N'پلکان متناسب با تعداد شرکت‌کنندگان پیدا نشد.', 1;

        SET @CommissionAmount =
            CASE
                WHEN @TierPercent IS NOT NULL
                    THEN ROUND(@CommissionBaseAmount * @TierPercent / 100.0, 2)
                ELSE ISNULL(@TierAmount, 0)
            END;
    END
    ELSE
    BEGIN
        THROW 51804, N'روش محاسبه کارمزد پشتیبانی نمی‌شود.', 1;
    END;

    SELECT
        @CommissionPlanId AS CommissionPlanId,
        @TierId AS CommissionTierId,
        @CommissionBaseAmount AS CommissionBaseAmount,
        @CommissionAmount AS CommissionAmount,
        @CommissionBaseAmount - @CommissionAmount AS NetAmount;
END;
GO
