    @ClassSeriesId BIGINT = NULL,
    @OnlyActive BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SELECT *
    FROM dbo.Pricing_CommissionPlans
    WHERE IsDeleted = 0
      AND (@OrgId IS NULL OR OrgId = @OrgId)
      AND (@ClassSeriesId IS NULL OR ClassSeriesId = @ClassSeriesId
