/****** Object:  StoredProcedure [dbo].[Pricing_CommissionPlans_Save]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   PROCEDURE [dbo].[Pricing_CommissionPlans_Save]
    @CommissionPlanId BIGINT = NULL,
    @OrgId BIGINT,
    @ClassSeriesId BIGINT = NULL,
    @PlanName NVARCHAR(200),
    @PlanNameEn NVARCHAR(200) = NULL,
    @CommissionMethod TINYINT,
    @CommissionBasis TINYINT,
    @FixedAmount DECIMAL(18,2) = NULL,
    @CommissionPercent DECIMAL(5,2) = NULL,
    @ValidFrom DATETIME2(0),
    @ValidTo DATETIME2(0) = NULL,
    @IsActive BIT = 1,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @FixedAmount < 0 OR @CommissionPercent < 0 OR @CommissionPercent > 100
        THROW 51210, N'مقدار کارمزد نامعتبر است.', 1;

    IF @ValidTo IS NOT NULL AND @ValidTo < @ValidFrom
        THROW 51211, N'بازه اعتبار طرح کارمزد نامعتبر است.', 1;

    IF @CommissionPlanId IS NULL
    BEGIN
        INSERT INTO dbo.Pricing_CommissionPlans
        (
            OrgId, ClassSeriesId, PlanName, PlanNameEn,
            CommissionMethod, CommissionBasis, FixedAmount, CommissionPercent,
            ValidFrom, ValidTo, IsActive, IsDeleted, CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @ClassSeriesId, @PlanName, @PlanNameEn,
            @CommissionMethod, @CommissionBasis, @FixedAmount, @CommissionPercent,
            @ValidFrom, @ValidTo, @IsActive, 0, GETDATE(), @UserId
        );

        SET @CommissionPlanId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Pricing_CommissionPlans
        SET OrgId = @OrgId, ClassSeriesId = @ClassSeriesId,
            PlanName = @PlanName, PlanNameEn = @PlanNameEn,
            CommissionMethod = @CommissionMethod, CommissionBasis = @CommissionBasis,
            FixedAmount = @FixedAmount, CommissionPercent = @CommissionPercent,
            ValidFrom = @ValidFrom, ValidTo = @ValidTo, IsActive = @IsActive,
            UpdatedAt = GETDATE(), UserUpdater = @UserId
        WHERE CommissionPlanId = @CommissionPlanId AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 51212, N'طرح کارمزد پیدا نشد.', 1;
    END;

    EXEC dbo.Pricing_CommissionPlans_GetById @CommissionPlanId;
END;
GO
