CREATE   PROCEDURE [dbo].[Pricing_CommissionTiers_Save]
    @CommissionTierId BIGINT = NULL,
    @CommissionPlanId BIGINT,
    @MinParticipantCount INT,
    @MaxParticipantCount INT = NULL,
    @TierPercent DECIMAL(5,2) = NULL,
    @TierAmount DECIMAL(18,2) = NULL,
    @TierOrder INT,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @MinParticipantCount < 0
       OR (@MaxParticipantCount IS NOT NULL
           AND @MaxParticipantCount < @MinParticipantCount)
        THROW 51220, N'بازه پلکان کارمزد نامعتبر است.', 1;

    IF @TierPercent < 0 OR @TierPercent > 100 OR @TierAmount < 0
        THROW 51221, N'مقدار پلکان کارمزد نامعتبر است.', 1;

    IF @CommissionTierId IS NULL
    BEGIN
        INSERT INTO dbo.Pricing_CommissionTiers
        (
            CommissionPlanId, MinParticipantCount, MaxParticipantCount,
            TierPercent, TierAmount, TierOrder, CreatedAt, UserCreater
        )
        VALUES
        (
            @CommissionPlanId, @MinParticipantCount, @MaxParticipantCount,
            @TierPercent, @TierAmount, @TierOrder, GETDATE(), @UserId
        );

        SET @CommissionTierId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Pricing_CommissionTiers
        SET CommissionPlanId = @CommissionPlanId,
            MinParticipantCount = @MinParticipantCount,
            MaxParticipantCount = @MaxParticipantCount,
            TierPercent = @TierPercent,
            TierAmount = @TierAmount,
            TierOrder = @TierOrder,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE CommissionTierId = @CommissionTierId;

        IF @@ROWCOUNT = 0
            THROW 51222, N'پلکان کارمزد پیدا نشد.', 1;
    END;

    EXEC dbo.Pricing_CommissionTiers_GetById @CommissionTierId;
END;
GO
