    @EnrollmentId BIGINT = NULL,
    @ParticipantId BIGINT = NULL,
    @TransactionType TINYINT = NULL,
    @TransactionStatus TINYINT = NULL,
    @From DATETIME2(0) = NULL,
    @To DATETIME2(0) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT *
    FROM dbo.Pricing_FinancialTransactions
    WHERE (@BookingId IS NULL OR BookingId = @BookingId)
      AND (@EnrollmentId IS NULL OR EnrollmentId = @EnrollmentId)
      AND (@ParticipantId IS NULL OR ParticipantId = @ParticipantId)
      AND (@TransactionType IS NULL OR TransactionType = @TransactionType)
      AND (@TransactionStatus IS NULL OR TransactionStatus = @TransactionStatus)
      AND (@From IS NULL OR TransactionAt >= @From)
      AND (@To IS NULL OR TransactionAt <= @To)
    ORDER BY TransactionAt DESC, FinancialTransactionId DESC;
END;
