CREATE   PROCEDURE [dbo].[Pricing_FinancialTransactions_Save]
    @FinancialTransactionId BIGINT = NULL,
    @BookingId BIGINT = NULL,
    @EnrollmentId BIGINT = NULL,
    @ParticipantId BIGINT = NULL,
    @TransactionType TINYINT,
    @TransactionStatus TINYINT = 1,
    @Amount DECIMAL(18,2),
    @CurrencyCode CHAR(3) = 'IRR',
    @PaymentMethod TINYINT = NULL,
    @ExternalReference NVARCHAR(400) = NULL,
    @TransactionAt DATETIME2(0) = NULL,
    @Notes NVARCHAR(2000) = NULL,
    @NotesEn NVARCHAR(2000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Amount <= 0
        THROW 51501, N'مبلغ تراکنش باید بیشتر از صفر باشد.', 1;

    IF (@BookingId IS NULL AND @EnrollmentId IS NULL)
       OR (@BookingId IS NOT NULL AND @EnrollmentId IS NOT NULL)
        THROW 51502, N'باید دقیقاً یکی از BookingId یا EnrollmentId مشخص شود.', 1;

    IF @FinancialTransactionId IS NULL
    BEGIN
        INSERT INTO dbo.Pricing_FinancialTransactions
        (
            BookingId, EnrollmentId, ParticipantId, TransactionType,
            TransactionStatus, Amount, CurrencyCode, PaymentMethod,
            ExternalReference, TransactionAt, Notes, NotesEn,
            CreatedAt, UserCreater
        )
        VALUES
        (
            @BookingId, @EnrollmentId, @ParticipantId, @TransactionType,
            @TransactionStatus, @Amount, @CurrencyCode, @PaymentMethod,
            @ExternalReference, COALESCE(@TransactionAt, SYSDATETIME()),
            @Notes, @NotesEn, GETDATE(), @UserId
        );

        SET @FinancialTransactionId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Pricing_FinancialTransactions
        SET BookingId = @BookingId,
            EnrollmentId = @EnrollmentId,
            ParticipantId = @ParticipantId,
            TransactionType = @TransactionType,
            TransactionStatus = @TransactionStatus,
            Amount = @Amount,
            CurrencyCode = @CurrencyCode,
            PaymentMethod = @PaymentMethod,
            ExternalReference = @ExternalReference,
            TransactionAt = @TransactionAt,
            Notes = @Notes,
            NotesEn = @NotesEn,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE FinancialTransactionId = @FinancialTransactionId;

        IF @@ROWCOUNT = 0
            THROW 51503, N'تراکنش مالی پیدا نشد.', 1;
    END;

    EXEC dbo.Pricing_FinancialTransactions_GetById @FinancialTransactionId;
END;
GO
