/****** Object:  StoredProcedure [dbo].[Pricing_Rules_CalculateAmount]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Pricing_Rules_CalculateAmount]
    @OrgId BIGINT,
    @BookingType TINYINT,
    @ParticipantCategory TINYINT,
    @SpaceId BIGINT = NULL,
    @ParticipantCount INT = NULL,
    @StartAt DATETIME2(0) = NULL,
    @EndAt DATETIME2(0) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @PricingRuleId BIGINT,
        @RuleName NVARCHAR(400),
        @RuleNameEn NVARCHAR(400),
        @PriceMethod TINYINT,
        @Rate DECIMAL(18,2),
        @CurrencyCode CHAR(3),
        @Hours DECIMAL(18,4),
        @CalculatedAmount DECIMAL(18,2),
        @At DATETIME2(0) = COALESCE(@StartAt, SYSDATETIME());

    SELECT TOP (1)
        @PricingRuleId = PricingRuleId,
        @RuleName = RuleName,
        @RuleNameEn = RuleNameEn,
        @PriceMethod = PriceMethod,
        @Rate = Amount,
        @CurrencyCode = CurrencyCode
    FROM dbo.Pricing_Rules
    WHERE OrgId = @OrgId
      AND BookingType = @BookingType
      AND ParticipantCategory IN (0, @ParticipantCategory)
      AND (SpaceId = @SpaceId OR SpaceId IS NULL)
      AND IsActive = 1
      AND IsDeleted = 0
      AND ValidFrom <= @At
      AND (ValidTo IS NULL OR ValidTo >= @At)
      AND (@ParticipantCount IS NULL OR MinParticipants IS NULL
           OR MinParticipants <= @ParticipantCount)
      AND (@ParticipantCount IS NULL OR MaxParticipants IS NULL
           OR MaxParticipants >= @ParticipantCount)
    ORDER BY
        CASE WHEN SpaceId = @SpaceId AND SpaceId IS NOT NULL THEN 1 ELSE 0 END DESC,
        CASE WHEN ParticipantCategory = @ParticipantCategory THEN 1 ELSE 0 END DESC,
        Priority DESC,
        ValidFrom DESC;

    IF @PricingRuleId IS NULL
        THROW 51602, N'قانون قیمت‌گذاری معتبر پیدا نشد.', 1;

    SET @CalculatedAmount =
        CASE @PriceMethod
            WHEN 1 THEN @Rate
            WHEN 2 THEN
                CASE
                    WHEN @StartAt IS NULL OR @EndAt IS NULL OR @EndAt <= @StartAt
                    THEN NULL
                    ELSE ROUND(
                        @Rate * CONVERT(DECIMAL(18,4),
                            DATEDIFF(SECOND, @StartAt, @EndAt)) / 3600.0, 2)
                END
            WHEN 3 THEN ROUND(@Rate * ISNULL(@ParticipantCount, 1), 2)
            ELSE NULL
        END;

    IF @CalculatedAmount IS NULL
        THROW 51603, N'پارامترهای لازم برای روش قیمت‌گذاری کامل نیست.', 1;

    SELECT
        @PricingRuleId AS PricingRuleId,
        @RuleName AS RuleName,
        @RuleNameEn AS RuleNameEn,
        @PriceMethod AS PriceMethod,
        @Rate AS UnitAmount,
        @CalculatedAmount AS CalculatedAmount,
        @CurrencyCode AS CurrencyCode;
END;
GO
