CREATE   PROCEDURE [dbo].[Pricing_Rules_GetList]
    @OrgId BIGINT = NULL,
    @BookingType TINYINT = NULL,
    @ParticipantCategory TINYINT = NULL,
    @SpaceId BIGINT = NULL,
    @OnlyActive BIT = 1,
    @At DATETIME2(0) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET @At = COALESCE(@At, SYSDATETIME());

    SELECT *
    FROM dbo.Pricing_Rules
    WHERE IsDeleted = 0
      AND (@OrgId IS NULL OR OrgId = @OrgId)
      AND (@BookingType IS NULL OR BookingType = @BookingType)
      AND (@ParticipantCategory IS NULL OR ParticipantCategory = @ParticipantCategory)
      AND (@SpaceId IS NULL OR SpaceId = @SpaceId OR SpaceId IS NULL)
      AND (
          @OnlyActive = 0 OR
          (IsActive = 1 AND ValidFrom <= @At
           AND (ValidTo IS NULL OR ValidTo >= @At))
      )
    ORDER BY Priority DESC, ValidFrom DESC;
END;
