CREATE   PROCEDURE [dbo].[Pricing_Rules_Save]
    @PricingRuleId BIGINT = NULL,
    @OrgId BIGINT,
    @BuildingId BIGINT = NULL,
    @SpaceId BIGINT = NULL,
    @RuleName NVARCHAR(200),
    @RuleNameEn NVARCHAR(200) = NULL,
    @BookingType TINYINT,
    @ParticipantCategory TINYINT,
    @PriceMethod TINYINT,
    @Amount DECIMAL(18,2),
    @CurrencyCode CHAR(3) = 'IRR',
    @MinParticipants INT = NULL,
    @MaxParticipants INT = NULL,
    @RequiresAmenities BIT = 0,
    @ValidFrom DATETIME2(0),
    @ValidTo DATETIME2(0) = NULL,
    @Priority INT = 0,
    @IsActive BIT = 1,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Amount < 0
        THROW 51201, N'مبلغ قانون قیمت‌گذاری نامعتبر است.', 1;

    IF @MinParticipants < 0 OR @MaxParticipants < 0
       OR (@MinParticipants IS NOT NULL AND @MaxParticipants IS NOT NULL
           AND @MaxParticipants < @MinParticipants)
        THROW 51202, N'بازه تعداد شرکت‌کنندگان نامعتبر است.', 1;

    IF @ValidTo IS NOT NULL AND @ValidTo < @ValidFrom
        THROW 51203, N'بازه اعتبار قانون نامعتبر است.', 1;

    IF @PricingRuleId IS NULL
    BEGIN
        INSERT INTO dbo.Pricing_Rules
        (
            OrgId, BuildingId, SpaceId, RuleName, RuleNameEn,
            BookingType, ParticipantCategory, PriceMethod, Amount,
            CurrencyCode, MinParticipants, MaxParticipants, RequiresAmenities,
            ValidFrom, ValidTo, Priority, IsActive, IsDeleted,
            CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @BuildingId, @SpaceId, @RuleName, @RuleNameEn,
            @BookingType, @ParticipantCategory, @PriceMethod, @Amount,
            @CurrencyCode, @MinParticipants, @MaxParticipants, @RequiresAmenities,
            @ValidFrom, @ValidTo, @Priority, @IsActive, 0,
            GETDATE(), @UserId
        );

        SET @PricingRuleId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Pricing_Rules
        SET OrgId = @OrgId,
            BuildingId = @BuildingId,
            SpaceId = @SpaceId,
            RuleName = @RuleName,
            RuleNameEn = @RuleNameEn,
            BookingType = @BookingType,
            ParticipantCategory = @ParticipantCategory,
            PriceMethod = @PriceMethod,
            Amount = @Amount,
            CurrencyCode = @CurrencyCode,
            MinParticipants = @MinParticipants,
            MaxParticipants = @MaxParticipants,
            RequiresAmenities = @RequiresAmenities,
            ValidFrom = @ValidFrom,
            ValidTo = @ValidTo,
            Priority = @Priority,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE PricingRuleId = @PricingRuleId
          AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
            THROW 51204, N'قانون قیمت‌گذاری پیدا نشد.', 1;
    END;

    EXEC dbo.Pricing_Rules_GetById @PricingRuleId;
END;
GO
