CREATE   PROCEDURE [dbo].[Pricing_Settlements_Save]
    @SettlementId BIGINT = NULL,
    @OrgId BIGINT,
    @ClassSeriesId BIGINT = NULL,
    @ClassSessionId BIGINT = NULL,
    @CommissionPlanId BIGINT = NULL,
    @EmployeeId BIGINT = NULL,
    @ExternalRecipientName NVARCHAR(400) = NULL,
    @SettlementRole TINYINT,
    @GrossAmount DECIMAL(18,2),
    @CommissionAmount DECIMAL(18,2),
    @NetAmount DECIMAL(18,2),
    @SettlementStatus TINYINT = 1,
    @SettledAt DATETIME2(0) = NULL,
    @Notes NVARCHAR(2000) = NULL,
    @NotesEn NVARCHAR(2000) = NULL,
    @UserId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @GrossAmount < 0 OR @CommissionAmount < 0 OR @NetAmount < 0
        THROW 51510, N'مبالغ تسویه نمی‌توانند منفی باشند.', 1;

    IF @NetAmount <> @GrossAmount - @CommissionAmount
        THROW 51511, N'مبلغ خالص با مبلغ ناخالص و کارمزد همخوانی ندارد.', 1;

    IF @EmployeeId IS NULL
       AND NULLIF(LTRIM(RTRIM(@ExternalRecipientName)), N'') IS NULL
        THROW 51512, N'گیرنده تسویه باید مشخص شود.', 1;

    IF @SettlementId IS NULL
    BEGIN
        INSERT INTO dbo.Pricing_Settlements
        (
            OrgId, ClassSeriesId, ClassSessionId, CommissionPlanId,
            EmployeeId, ExternalRecipientName, SettlementRole,
            GrossAmount, CommissionAmount, NetAmount, SettlementStatus,
            SettledAt, Notes, NotesEn, CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @ClassSeriesId, @ClassSessionId, @CommissionPlanId,
            @EmployeeId, @ExternalRecipientName, @SettlementRole,
            @GrossAmount, @CommissionAmount, @NetAmount, @SettlementStatus,
            @SettledAt, @Notes, @NotesEn, GETDATE(), @UserId
        );

        SET @SettlementId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.Pricing_Settlements
        SET OrgId = @OrgId,
            ClassSeriesId = @ClassSeriesId,
            ClassSessionId = @ClassSessionId,
            CommissionPlanId = @CommissionPlanId,
            EmployeeId = @EmployeeId,
            ExternalRecipientName = @ExternalRecipientName,
            SettlementRole = @SettlementRole,
            GrossAmount = @GrossAmount,
            CommissionAmount = @CommissionAmount,
            NetAmount = @NetAmount,
            SettlementStatus = @SettlementStatus,
            SettledAt = @SettledAt,
            Notes = @Notes,
            NotesEn = @NotesEn,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserId
        WHERE SettlementId = @SettlementId;

        IF @@ROWCOUNT = 0
            THROW 51513, N'رکورد تسویه پیدا نشد.', 1;
    END;

    EXEC dbo.Pricing_Settlements_GetById @SettlementId;
END;
GO
