CREATE   PROCEDURE [dbo].[Spaces_BulkSave]
(
    @Spaces             dbo.SpaceBulkType READONLY,
    @CurrentUserId      BIGINT = NULL,
    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده.';

    IF NOT EXISTS (SELECT 1 FROM @Spaces)
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'حداقل یک فضا باید ارسال شود.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces
        WHERE OrgId IS NULL OR OrgId <= 0
           OR SpaceType IS NULL
           OR NULLIF(LTRIM(RTRIM(SpaceName)), N'') IS NULL
           OR (Capacity IS NOT NULL AND Capacity < 0)
           OR (Area IS NOT NULL AND Area < 0)
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage =
            N'اطلاعات سازمان، نوع فضا، نام فارسی، ظرفیت یا مساحت نامعتبر است.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT SpaceId
        FROM @Spaces
        WHERE SpaceId > 0
        GROUP BY SpaceId
        HAVING COUNT(*) > 1
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه یک فضا بیش از یک بار ارسال شده است.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Organizations O
            WHERE O.OrgId = S.OrgId
              AND ISNULL(O.IsDeleted, 0) = 0
        )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'یکی از سازمان‌ها یافت نشد یا حذف شده است.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Base_LookupValues L
            WHERE L.LookupValueId = S.SpaceType
        )
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'یکی از انواع فضای ارسالی در جدول مقادیر پایه معتبر نیست.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE S.BuildingId IS NOT NULL
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.Buildings B
              WHERE B.BuildingId = S.BuildingId
                AND B.OrgId = S.OrgId
                AND ISNULL(B.IsDeleted, 0) = 0
                AND B.IsActive = 1
          )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage =
            N'یکی از ساختمان‌ها نامعتبر، غیرفعال یا متعلق به سازمان دیگری است.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE S.ParentSpaceId IS NOT NULL
          AND
          (
              S.ParentSpaceId = S.SpaceId
              OR NOT EXISTS
              (
                  SELECT 1
                  FROM dbo.Spaces P
                  WHERE P.SpaceId = S.ParentSpaceId
                    AND P.OrgId = S.OrgId
                    AND ISNULL(P.IsDeleted, 0) = 0
              )
          )
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage =
            N'فضای والد نامعتبر است یا فضا نمی‌تواند والد خودش باشد.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE ISNULL(S.SpaceId, 0) > 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.Spaces T
              WHERE T.SpaceId = S.SpaceId
                AND ISNULL(T.IsDeleted, 0) = 0
          )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'یکی از فضاهای ارسالی برای ویرایش یافت نشد یا حذف شده است.';
        RETURN;
    END;

    -- جلوگیری از خودارجاعی در ارتباط والد و فرزند در همان درخواست
    IF EXISTS
    (
        SELECT 1
        FROM @Spaces S
        WHERE S.ParentSpaceId IS NOT NULL
          AND S.ParentSpaceId IN
          (
              SELECT SpaceId
              FROM @Spaces
              WHERE ISNULL(SpaceId, 0) > 0
          )
          AND S.ParentSpaceId = S.SpaceId
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'فضا نمی‌تواند والد خودش باشد.';
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE T
        SET
            T.OrgId = S.OrgId,
            T.BuildingId = S.BuildingId,
            T.ParentSpaceId = S.ParentSpaceId,
            T.SpaceName = LTRIM(RTRIM(S.SpaceName)),
            T.SpaceNameEn = NULLIF(LTRIM(RTRIM(S.SpaceNameEn)), N''),
            T.SpaceType = S.SpaceType,
            T.Capacity = S.Capacity,
            T.Area = S.Area,
            T.SpaceDesc = S.SpaceDesc,
            T.SpaceDescEn = S.SpaceDescEn,
            T.IsReservable = ISNULL(S.IsReservable, T.IsReservable),
            T.IsActive = ISNULL(S.IsActive, T.IsActive),
            T.UpdatedAt = GETDATE(),
            T.UserUpdater = TRY_CONVERT(INT, @CurrentUserId)
        FROM dbo.Spaces T
        INNER JOIN @Spaces S
            ON S.SpaceId = T.SpaceId
        WHERE ISNULL(S.SpaceId, 0) > 0
          AND ISNULL(T.IsDeleted, 0) = 0;

        INSERT INTO dbo.Spaces
        (
            OrgId, BuildingId, ParentSpaceId,
            SpaceName, SpaceNameEn, SpaceType,
            Capacity, Area, SpaceDesc, SpaceDescEn,
            IsReservable, IsActive, IsDeleted,
            CreatedAt, UserCreater
        )
        SELECT
            S.OrgId,
            S.BuildingId,
            S.ParentSpaceId,
            LTRIM(RTRIM(S.SpaceName)),
            NULLIF(LTRIM(RTRIM(S.SpaceNameEn)), N''),
            S.SpaceType,
            S.Capacity,
            S.Area,
            S.SpaceDesc,
            S.SpaceDescEn,
            ISNULL(S.IsReservable, 0),
            ISNULL(S.IsActive, 1),
            0,
            GETDATE(),
            TRY_CONVERT(INT, @CurrentUserId)
        FROM @Spaces S
        WHERE ISNULL(S.SpaceId, 0) = 0;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage = N'ثبت و ویرایش گروهی فضاها با موفقیت انجام شد.';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Spaces_Delete]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Spaces_Delete]
(
    @SpaceId BIGINT,
    @CurrentUserId BIGINT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @SpaceId IS NULL OR @SpaceId <= 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'کد فضا معتبر نیست.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Spaces
        WHERE SpaceId = @SpaceId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'فضای موردنظر یافت نشد یا قبلاً حذف شده است.';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Spaces
        WHERE ParentSpaceId = @SpaceId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 409;
        SET @ResultMessage =
            N'این فضا دارای فضای فرزند است؛ ابتدا فضاهای فرزند را تعیین تکلیف کنید.';
        RETURN;
    END;

    BEGIN TRY
        UPDATE dbo.Spaces
        SET
            IsDeleted = 1,
            IsActive = 0,
            UpdatedAt = GETDATE(),
            UserUpdater = TRY_CONVERT(INT, @CurrentUserId)
        WHERE SpaceId = @SpaceId
          AND ISNULL(IsDeleted, 0) = 0;

        SET @ResultCode = 200;
        SET @ResultMessage = N'فضا با موفقیت حذف شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Spaces_Get]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Spaces_Get]
(
    @OrgId BIGINT = NULL,
    @BuildingId BIGINT = NULL,
    @SpaceType INT = NULL,
    @IsActive BIT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        S.SpaceId,
        S.OrgId,
        S.BuildingId,
        S.ParentSpaceId,
        S.SpaceName,
        S.SpaceNameEn,
        S.SpaceType,
        S.Capacity,
        S.Area,
        S.SpaceDesc,
        S.SpaceDescEn,
        S.IsReservable,
        S.IsActive,
        S.IsDeleted,
        S.CreatedAt,
        S.UserCreater,
        S.UpdatedAt,
        S.UserUpdater
    FROM dbo.Spaces S
    WHERE ISNULL(S.IsDeleted, 0) = 0
      AND (@OrgId IS NULL OR S.OrgId = @OrgId)
      AND (@BuildingId IS NULL OR S.BuildingId = @BuildingId)
      AND (@SpaceType IS NULL OR S.SpaceType = @SpaceType)
      AND (@IsActive IS NULL OR S.IsActive = @IsActive)
    ORDER BY S.SpaceId DESC;

    SET @ResultCode = 200;
    SET @ResultMessage = N'فهرست فضاها دریافت شد.';
END;
GO
