/****** Object:  StoredProcedure [dbo].[Spaces_Insert]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Spaces_Insert]
(
    @OrgId              BIGINT,
    @BuildingId         BIGINT = NULL,
    @ParentSpaceId      BIGINT = NULL,
    @SpaceName          NVARCHAR(200),
    @SpaceNameEn        NVARCHAR(200) = NULL,
    @SpaceType          INT,
    @Capacity           INT = NULL,
    @Area               DECIMAL(10,2) = NULL,
    @SpaceDesc          NVARCHAR(1000) = NULL,
    @SpaceDescEn        NVARCHAR(1000) = NULL,
    @IsReservable       BIT = 0,
    @IsActive           BIT = 1,
    @CurrentUserId      BIGINT = NULL,
    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT,
    @SpaceId            BIGINT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده.';
    SET @SpaceId = NULL;

    SET @SpaceName = LTRIM(RTRIM(@SpaceName));
    SET @SpaceNameEn = NULLIF(LTRIM(RTRIM(@SpaceNameEn)), N'');

    IF @OrgId IS NULL OR @OrgId <= 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'کد سازمان معتبر نیست.';
        RETURN;
    END;

    IF NULLIF(@SpaceName, N'') IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام فارسی فضا الزامی است.';
        RETURN;
    END;

    IF @SpaceType IS NULL
       OR NOT EXISTS
       (
           SELECT 1
           FROM dbo.Base_LookupValues
           WHERE LookupValueId = @SpaceType
       )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نوع فضا در جدول مقادیر پایه معتبر نیست.';
        RETURN;
    END;

    IF @Capacity IS NOT NULL AND @Capacity < 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'ظرفیت نمی‌تواند منفی باشد.';
        RETURN;
    END;

    IF @Area IS NOT NULL AND @Area < 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'مساحت نمی‌تواند منفی باشد.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Organizations
        WHERE OrgId = @OrgId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'سازمان وجود ندارد یا حذف شده است.';
        RETURN;
    END;

    IF @BuildingId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.Buildings
           WHERE BuildingId = @BuildingId
             AND OrgId = @OrgId
             AND ISNULL(IsDeleted, 0) = 0
             AND IsActive = 1
       )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'ساختمان انتخاب‌شده معتبر یا متعلق به این سازمان نیست.';
        RETURN;
    END;

    IF @ParentSpaceId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.Spaces
           WHERE SpaceId = @ParentSpaceId
             AND OrgId = @OrgId
             AND ISNULL(IsDeleted, 0) = 0
       )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'فضای والد معتبر یا متعلق به این سازمان نیست.';
        RETURN;
    END;

    BEGIN TRY
        INSERT INTO dbo.Spaces
        (
            OrgId, BuildingId, ParentSpaceId,
            SpaceName, SpaceNameEn, SpaceType,
            Capacity, Area, SpaceDesc, SpaceDescEn,
            IsReservable, IsActive, IsDeleted,
            CreatedAt, UserCreater
        )
        VALUES
        (
            @OrgId, @BuildingId, @ParentSpaceId,
            @SpaceName, @SpaceNameEn, @SpaceType,
            @Capacity, @Area, @SpaceDesc, @SpaceDescEn,
            @IsReservable, @IsActive, 0,
            GETDATE(), TRY_CONVERT(INT, @CurrentUserId)
        );

        SET @SpaceId = CONVERT(BIGINT, SCOPE_IDENTITY());
        SET @ResultCode = 200;
        SET @ResultMessage = N'فضا با موفقیت ثبت شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Spaces_SetActive]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Spaces_SetActive]
(
    @SpaceId BIGINT,
    @IsActive BIT,
    @CurrentUserId BIGINT = NULL,
    @ResultCode INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @SpaceId IS NULL OR @SpaceId <= 0
       OR @IsActive IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه فضا یا وضعیت فعال‌بودن معتبر نیست.';
        RETURN;
    END;

    UPDATE dbo.Spaces
    SET
        IsActive = @IsActive,
        UpdatedAt = GETDATE(),
        UserUpdater = TRY_CONVERT(INT, @CurrentUserId)
    WHERE SpaceId = @SpaceId
      AND ISNULL(IsDeleted, 0) = 0;

    IF @@ROWCOUNT = 0
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'فضای موردنظر یافت نشد یا حذف شده است.';
        RETURN;
    END;

    SET @ResultCode = 200;
    SET @ResultMessage =
        CASE WHEN @IsActive = 1
             THEN N'فضا با موفقیت فعال شد.'
             ELSE N'فضا با موفقیت غیرفعال شد.'
        END;
END;
GO
/****** Object:  StoredProcedure [dbo].[Spaces_Update]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Spaces_Update]
(
    @SpaceId            BIGINT,
    @OrgId              BIGINT,
    @BuildingId         BIGINT = NULL,
    @ParentSpaceId      BIGINT = NULL,
    @SpaceName          NVARCHAR(200),
    @SpaceNameEn        NVARCHAR(200) = NULL,
    @SpaceType          INT,
    @Capacity           INT = NULL,
    @Area               DECIMAL(10,2) = NULL,
    @SpaceDesc          NVARCHAR(1000) = NULL,
    @SpaceDescEn        NVARCHAR(1000) = NULL,
    @IsReservable       BIT,
    @IsActive           BIT,
    @CurrentUserId      BIGINT = NULL,
    @ResultCode         INT OUTPUT,
    @ResultMessage      NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده.';

    SET @SpaceName = LTRIM(RTRIM(@SpaceName));
    SET @SpaceNameEn = NULLIF(LTRIM(RTRIM(@SpaceNameEn)), N'');

    IF @SpaceId IS NULL OR @SpaceId <= 0
       OR @OrgId IS NULL OR @OrgId <= 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'کد فضا یا سازمان معتبر نیست.';
        RETURN;
    END;

    IF NULLIF(@SpaceName, N'') IS NULL
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نام فارسی فضا الزامی است.';
        RETURN;
    END;

    IF @Capacity < 0 OR @Area < 0
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'ظرفیت و مساحت نمی‌توانند منفی باشند.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Spaces
        WHERE SpaceId = @SpaceId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'فضای موردنظر یافت نشد یا حذف شده است.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Organizations
        WHERE OrgId = @OrgId
          AND ISNULL(IsDeleted, 0) = 0
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'سازمان وجود ندارد یا حذف شده است.';
        RETURN;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Base_LookupValues
        WHERE LookupValueId = @SpaceType
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'نوع فضا در جدول مقادیر پایه معتبر نیست.';
        RETURN;
    END;

    IF @BuildingId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.Buildings
           WHERE BuildingId = @BuildingId
             AND OrgId = @OrgId
             AND ISNULL(IsDeleted, 0) = 0
             AND IsActive = 1
       )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'ساختمان معتبر یا متعلق به این سازمان نیست.';
        RETURN;
    END;

    IF @ParentSpaceId = @SpaceId
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'یک فضا نمی‌تواند والد خودش باشد.';
        RETURN;
    END;

    IF @ParentSpaceId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.Spaces
           WHERE SpaceId = @ParentSpaceId
             AND OrgId = @OrgId
             AND ISNULL(IsDeleted, 0) = 0
       )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage = N'فضای والد معتبر یا متعلق به این سازمان نیست.';
        RETURN;
    END;

    BEGIN TRY
        UPDATE dbo.Spaces
        SET
            OrgId = @OrgId,
            BuildingId = @BuildingId,
            ParentSpaceId = @ParentSpaceId,
            SpaceName = @SpaceName,
            SpaceNameEn = @SpaceNameEn,
            SpaceType = @SpaceType,
            Capacity = @Capacity,
            Area = @Area,
            SpaceDesc = @SpaceDesc,
            SpaceDescEn = @SpaceDescEn,
            IsReservable = @IsReservable,
            IsActive = @IsActive,
            UpdatedAt = GETDATE(),
            UserUpdater = TRY_CONVERT(INT, @CurrentUserId)
        WHERE SpaceId = @SpaceId
          AND ISNULL(IsDeleted, 0) = 0;

        SET @ResultCode = 200;
        SET @ResultMessage = N'فضا با موفقیت ویرایش شد.';
    END TRY
    BEGIN CATCH
        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[Units_BulkSave]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[Units_BulkSave]
(
    @Units          dbo.UnitBulkType READONLY,
    @CurrentUserId  BIGINT,
    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای پیش‌بینی‌نشده در عملیات واحدها.';

    ---------------------------------------------------------
    -- 1. بررسی خالی نبودن ورودی
    ---------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM @Units)
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'حداقل یک واحد باید ارسال شود.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 2. اعتبارسنجی BuildingId
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Units
        WHERE BuildingId IS NULL OR BuildingId <= 0
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'کد ساختمان معتبر نیست.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 3. اعتبارسنجی UnitNumber
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Units
        WHERE NULLIF(LTRIM(RTRIM(UnitNumber)), N'') IS NULL
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شماره یا نام واحد الزامی است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 4. جلوگیری از شناسه تکراری در یک درخواست
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT UnitId
        FROM @Units
        WHERE UnitId IS NOT NULL
          AND UnitId > 0
        GROUP BY UnitId
        HAVING COUNT(*) > 1
    )
    BEGIN
        SET @ResultCode = 400;
        SET @ResultMessage = N'شناسه یک واحد بیش از یک بار ارسال شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 5. بررسی ساختمان‌ها
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Units U
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Buildings B
            WHERE B.BuildingId = U.BuildingId
              AND ISNULL(B.IsDeleted, 0) = 0
              AND B.IsActive = 1
        )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage =
            N'ساختمان انتخاب شده وجود ندارد، حذف شده یا غیرفعال است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 6. بررسی وجود واحدهای ارسالی برای ویرایش
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Units U
        WHERE ISNULL(U.UnitId, 0) > 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.Units T
              WHERE T.UnitId = U.UnitId
                AND ISNULL(T.IsDeleted, 0) = 0
          )
    )
    BEGIN
        SET @ResultCode = 404;
        SET @ResultMessage =
            N'یکی از واحدهای ارسالی برای ویرایش یافت نشد یا حذف شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 7. بررسی تکراری نبودن واحدها در خود درخواست
    -- کلید: ساختمان + طبقه + شماره واحد
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT
            BuildingId,
            FloorNumber,
            LTRIM(RTRIM(UnitNumber))
        FROM @Units
        GROUP BY
            BuildingId,
            FloorNumber,
            LTRIM(RTRIM(UnitNumber))
        HAVING COUNT(*) > 1
    )
    BEGIN
        SET @ResultCode = 409;
        SET @ResultMessage =
            N'در اطلاعات ارسالی، شماره واحد در یک ساختمان و طبقه تکراری است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 8. بررسی تکراری نبودن در جدول موجود
    ---------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM @Units U
        INNER JOIN dbo.Units T
            ON T.BuildingId = U.BuildingId
           AND
           (
               T.FloorNumber = U.FloorNumber
               OR (T.FloorNumber IS NULL AND U.FloorNumber IS NULL)
           )
           AND LTRIM(RTRIM(T.UnitNumber)) =
               LTRIM(RTRIM(U.UnitNumber))
           AND ISNULL(T.IsDeleted, 0) = 0
           AND
           (
               ISNULL(U.UnitId, 0) = 0
               OR T.UnitId <> U.UnitId
           )
    )
    BEGIN
        SET @ResultCode = 409;
        SET @ResultMessage =
            N'در این طبقه از این ساختمان، واحدی با این شماره یا نام قبلاً ثبت شده است.';
        RETURN;
    END;

    ---------------------------------------------------------
    -- 9. ثبت و ویرایش اتمیک
    ---------------------------------------------------------
    BEGIN TRY
        BEGIN TRANSACTION;

        -----------------------------------------------------
        -- 9.1 ویرایش واحدهای موجود
        -----------------------------------------------------
        UPDATE T
        SET
            T.BuildingId = U.BuildingId,
            T.UnitNumber = LTRIM(RTRIM(U.UnitNumber)),
            T.FloorNumber = U.FloorNumber,
            T.Area = U.Area,
            T.Bedrooms = U.Bedrooms,
            T.UnitDescription = U.UnitDescription,
            T.IsActive = ISNULL(U.IsActive, T.IsActive),
            T.UpdatedAt = GETDATE(),
            T.UserUpdater = TRY_CONVERT(INT, @CurrentUserId)
        FROM dbo.Units T
        INNER JOIN @Units U
            ON U.UnitId = T.UnitId
        WHERE ISNULL(U.UnitId, 0) > 0
          AND ISNULL(T.IsDeleted, 0) = 0;

        -----------------------------------------------------
        -- 9.2 ثبت واحدهای جدید
        -----------------------------------------------------
        INSERT INTO dbo.Units
        (
            BuildingId,
            UnitNumber,
            FloorNumber,
            Area,
            Bedrooms,
            UnitDescription,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater
        )
        SELECT
            U.BuildingId,
            LTRIM(RTRIM(U.UnitNumber)),
            U.FloorNumber,
            U.Area,
            U.Bedrooms,
            U.UnitDescription,
            ISNULL(U.IsActive, 1),
            0,
            GETDATE(),
            TRY_CONVERT(INT, @CurrentUserId)
        FROM @Units U
        WHERE ISNULL(U.UnitId, 0) = 0;

        COMMIT TRANSACTION;

        SET @ResultCode = 200;
        SET @ResultMessage =
            N'عملیات ثبت و ویرایش واحدها با موفقیت انجام شد.';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[UnitsAdd]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   UnitsAdd
   ========================================================= */
CREATE PROCEDURE [dbo].[UnitsAdd]
(
    @BuildingId       BIGINT,
    @UnitNumber       NVARCHAR(50),
    @FloorNumber      INT = NULL,
    @Area             DECIMAL(10,2) = NULL,
    @Bedrooms         TINYINT = NULL,
    @UnitDescription  NVARCHAR(1000) = NULL,
    @IsActive         BIT = 1,
    @UserCreater      INT = NULL,

    @ResultCode       INT OUTPUT,
    @ResultMessage    NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در ثبت واحد.';

    BEGIN TRY

        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF @BuildingId IS NULL OR @BuildingId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد ساختمان معتبر نیست.';
            RETURN;
        END;

        IF NULLIF(LTRIM(RTRIM(@UnitNumber)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'شماره یا نام واحد الزامی است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Building
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE BuildingId = @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
              AND IsActive = 1
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage =
                N'ساختمان انتخاب شده وجود ندارد، حذف شده یا غیرفعال است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Duplicate
        -- Building + Floor + UnitNumber
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Units
            WHERE BuildingId = @BuildingId
              AND ISNULL(FloorNumber, -999999) =
                  ISNULL(@FloorNumber, -999999)
              AND LTRIM(RTRIM(UnitNumber)) =
                  LTRIM(RTRIM(@UnitNumber))
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'در این طبقه از این ساختمان، واحدی با این شماره یا نام قبلاً ثبت شده است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Insert
        ---------------------------------------------------------
        INSERT INTO dbo.Units
        (
            BuildingId,
            UnitNumber,
            FloorNumber,
            Area,
            Bedrooms,
            UnitDescription,
            IsActive,
            IsDeleted,
            CreatedAt,
            UserCreater
        )
        VALUES
        (
            @BuildingId,
            LTRIM(RTRIM(@UnitNumber)),
            @FloorNumber,
            @Area,
            @Bedrooms,
            @UnitDescription,
            ISNULL(@IsActive, 1),
            0,
            GETDATE(),
            @UserCreater
        );

        SET @ResultCode = 200;
        SET @ResultMessage = N'واحد با موفقیت ثبت شد.';

        SELECT
            U.*
        FROM dbo.Units AS U
        WHERE U.UnitId = SCOPE_IDENTITY();

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
