SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   UnitsDel
   ========================================================= */
CREATE PROCEDURE [dbo].[UnitsDel]
(
    @UnitId      BIGINT,
    @UserUpdater INT = NULL,

    @ResultCode  INT OUTPUT,
    @ResultMessage NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در حذف واحد.';

    BEGIN TRY

        IF @UnitId IS NULL OR @UnitId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد واحد معتبر نیست.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی وجود Unit
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Units
            WHERE UnitId = @UnitId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'واحد مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Soft Delete
        ---------------------------------------------------------
        UPDATE dbo.Units
        SET
            IsDeleted = 1,
            IsActive = 0,
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE UnitId = @UnitId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'واحد با موفقیت حذف شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
