/* =========================================================
   UnitsEdit
   ========================================================= */
CREATE PROCEDURE [dbo].[UnitsEdit]
(
    @UnitId           BIGINT,
    @BuildingId       BIGINT,
    @UnitNumber       NVARCHAR(50),
    @FloorNumber      INT = NULL,
    @Area             DECIMAL(10,2) = NULL,
    @Bedrooms         TINYINT = NULL,
    @UnitDescription  NVARCHAR(1000) = NULL,
    @IsActive         BIT = 1,
    @UserUpdater      INT = NULL,

    @ResultCode       INT OUTPUT,
    @ResultMessage    NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در ویرایش واحد.';

    BEGIN TRY

        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF @UnitId IS NULL OR @UnitId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد واحد معتبر نیست.';
            RETURN;
        END;

        IF @BuildingId IS NULL OR @BuildingId <= 0
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'کد ساختمان معتبر نیست.';
            RETURN;
        END;

        IF NULLIF(LTRIM(RTRIM(@UnitNumber)), N'') IS NULL
        BEGIN
            SET @ResultCode = 400;
            SET @ResultMessage = N'شماره یا نام واحد الزامی است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Unit
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Units
            WHERE UnitId = @UnitId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage = N'واحد مورد نظر یافت نشد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Building
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Buildings
            WHERE BuildingId = @BuildingId
              AND ISNULL(IsDeleted, 0) = 0
              AND IsActive = 1
        )
        BEGIN
            SET @ResultCode = 404;
            SET @ResultMessage =
                N'ساختمان انتخاب شده وجود ندارد، حذف شده یا غیرفعال است.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- بررسی Duplicate
        ---------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Units
            WHERE BuildingId = @BuildingId
              AND ISNULL(FloorNumber, -999999) =
                  ISNULL(@FloorNumber, -999999)
              AND LTRIM(RTRIM(UnitNumber)) =
                  LTRIM(RTRIM(@UnitNumber))
              AND UnitId <> @UnitId
              AND ISNULL(IsDeleted, 0) = 0
        )
        BEGIN
            SET @ResultCode = 409;
            SET @ResultMessage =
                N'در این طبقه از این ساختمان، واحد دیگری با این شماره یا نام وجود دارد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- Update
        ---------------------------------------------------------
        UPDATE dbo.Units
        SET
            BuildingId = @BuildingId,
            UnitNumber = LTRIM(RTRIM(@UnitNumber)),
            FloorNumber = @FloorNumber,
            Area = @Area,
            Bedrooms = @Bedrooms,
            UnitDescription = @UnitDescription,
            IsActive = ISNULL(@IsActive, 1),
            UpdatedAt = GETDATE(),
            UserUpdater = @UserUpdater
        WHERE UnitId = @UnitId;

        SET @ResultCode = 200;
        SET @ResultMessage = N'واحد با موفقیت ویرایش شد.';

        SELECT
            U.*
        FROM dbo.Units AS U
        WHERE U.UnitId = @UnitId;

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[UnitsGet]    Script Date: 10/29/2026 8:34:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* =========================================================
   UnitsGet
   ========================================================= */
CREATE PROCEDURE [dbo].[UnitsGet]
(
    @UnitId         BIGINT = NULL,
    @BuildingId     BIGINT = NULL,
    @Search         NVARCHAR(50) = NULL,
    @FloorNumber    INT = NULL,
    @PageNumber     INT = 1,
    @PageSize       INT = 50,
    @IncludeDeleted BIT = 0,

    @ResultCode     INT OUTPUT,
    @ResultMessage  NVARCHAR(500) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @ResultCode = 500;
    SET @ResultMessage = N'خطای داخلی در دریافت واحدها.';

    BEGIN TRY

        SET @PageNumber = ISNULL(@PageNumber, 1);
        SET @PageSize = ISNULL(@PageSize, 50);
        SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');

        IF @PageNumber < 1
            SET @PageNumber = 1;

        IF @PageSize < 1
            SET @PageSize = 50;

        IF @PageSize > 500
            SET @PageSize = 500;

        ---------------------------------------------------------
        -- دریافت یک Unit
        ---------------------------------------------------------
        IF @UnitId IS NOT NULL
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Units
                WHERE UnitId = @UnitId
                  AND
                  (
                      @IncludeDeleted = 1
                      OR ISNULL(IsDeleted, 0) = 0
                  )
            )
            BEGIN
                SET @ResultCode = 404;
                SET @ResultMessage = N'واحد مورد نظر یافت نشد.';
                RETURN;
            END;

            SELECT
                U.*
            FROM dbo.Units AS U
            WHERE U.UnitId = @UnitId
              AND
              (
                  @IncludeDeleted = 1
                  OR ISNULL(U.IsDeleted, 0) = 0
              );

            SET @ResultCode = 200;
            SET @ResultMessage = N'اطلاعات واحد با موفقیت دریافت شد.';
            RETURN;
        END;

        ---------------------------------------------------------
        -- لیست Units + Pagination
        ---------------------------------------------------------
        SELECT
            U.*
        FROM dbo.Units AS U
        WHERE
            (
                @IncludeDeleted = 1
                OR ISNULL(U.IsDeleted, 0) = 0
            )
            AND
            (
                @BuildingId IS NULL
                OR U.BuildingId = @BuildingId
            )
            AND
            (
                @FloorNumber IS NULL
                OR U.FloorNumber = @FloorNumber
            )
            AND
            (
                @Search IS NULL
                OR U.UnitNumber LIKE N'%' + ISNULL(@Search, N'') + N'%'
            )
        ORDER BY U.UnitId DESC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

        SET @ResultCode = 200;
        SET @ResultMessage = N'لیست واحدها با موفقیت دریافت شد.';

    END TRY
    BEGIN CATCH

        SET @ResultCode = ERROR_NUMBER();
        SET @ResultMessage = ERROR_MESSAGE();

    END CATCH
END;
GO
